div.script:
//

        let activeUser = null;
        let dataPegawai = [];
        let tableMasterRef, tableLaporanRef;
        let charts = {}; let pubCharts = {};

        Chart.defaults.font.family = "'Poppins', sans-serif"; Chart.defaults.color = '#64748b';

        function showPublicDashboard() { $('#login-section').hide(); $('#app-container').hide(); $('#public-dashboard-section').fadeIn(); }
        function showLoginScreen() { $('#public-dashboard-section').hide(); $('#login-section').css('display', 'flex').hide().fadeIn(); }
        function toggleChat() { $('#ai-chat-window').fadeToggle(); }

        async function sendAIMessage() {
            let msg = $('#aiInput').val().trim(); if (!msg) return; $('#aiInput').val('');
            $('#chatBody').append(`<div class="msg-user">${msg}</div>`);
            let loadingId = "loading-" + Date.now();
            $('#chatBody').append(`<div class="msg-ai" id="${loadingId}"><i class="fas fa-ellipsis-h fa-spin"></i> Mengetik...</div>`);
            $('#chatBody').scrollTop($('#chatBody')[0].scrollHeight);

            try {
                let response = await fetch('/api/chat', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ message: msg })
                });
                let data = await response.json();
                let textRes = data.text || data.error || "Maaf, terjadi masalah.";
                $(`#${loadingId}`).html(textRes.replace(/\n/g, '<br>'));
            } catch (error) {
                $(`#${loadingId}`).html("Terjadi kesalahan koneksi AI Chatbot.");
            }
            $('#chatBody').scrollTop($('#chatBody')[0].scrollHeight);
        }

        function loadDataFromGAS() {
            $('#loadingText').text("Memuat Data SIMPEG..."); $('#loadingOverlay').css('display', 'flex');
            fetch('/api/gas?action=getPegawaiData')
                .then(res => res.json())
                .then(data => {
                    dataPegawai = data || [];
                    refreshAllData();
                    $('#loadingOverlay').hide();
                })
                .catch(err => {
                    $('#loadingOverlay').hide();
                    showToast("Gagal memuat data dari server.", "danger");
                });
        }

        function refreshAllData() {
            renderTableMaster(); renderTableLaporan(); updateDashboard(); updatePublicDashboard(); renderDUK(); renderDisiplin();
        }

        function renderTableMaster() {
            if($.fn.DataTable.isDataTable('#tableMaster')) { $('#tableMaster').DataTable().clear().destroy(); }

            const statusFilter = ($('#filterMasterStatus').val() || '').toLowerCase().trim();
            const tugasFilter = ($('#filterMasterTugas').val() || '').toLowerCase().trim();

            let list = [...dataPegawai];

            if (statusFilter) {
                list = list.filter(p => {
                    const st = (p.status_pegawai || '').toLowerCase().trim();
                    if (statusFilter === 'pppk paruh waktu' || statusFilter === 'pppk pw') {
                        return st.includes('paruh') || st.includes('pw');
                    }
                    return st === statusFilter || st.includes(statusFilter);
                });
            }

            if (tugasFilter) {
                list = list.filter(p => {
                    const tt = (p.tempat_tugas || p.nama_ukpd || '').toLowerCase().trim();
                    if (tugasFilter.includes('seribu utara')) return tt.includes('seribu utara') || tt.includes('pukm') || tt.includes('kecamatan');
                    if (tugasFilter.includes('panggang')) return tt.includes('panggang');
                    if (tugasFilter.includes('harapan')) return tt.includes('harapan');
                    if (tugasFilter.includes('sabira')) return tt.includes('sabira');
                    return tt.includes(tugasFilter);
                });
            }

            let tbody = '';
            list.forEach((p, idx) => {
                let origIdx = dataPegawai.indexOf(p);
                if (origIdx === -1) origIdx = idx;

                let fotoSrc = p.foto && p.foto.trim() !== '' ? p.foto : `https://ui-avatars.com/api/?name=${encodeURIComponent(p.nama || 'P')}&background=6366F1&color=fff&bold=true&size=128`;

                let jabatanPergub = p.jabatan_orb || p.jabatan_pergub || p.jabatan || '-';
                let jabatanKepmenpan = p.jabatan_permenpan11 || p.jabatan_kepmenpan11 || p.jabatan_permenpan41 || p.jabatan || '-';
                let statusRumpun = p.status_rumpun || p.rumpun || '-';
                let statusPegawai = p.status_pegawai || 'PNS';
                let unitTugas = p.tempat_tugas || p.nama_ukpd || '-';

                let badgeClass = 'bg-primary';
                const stUpper = statusPegawai.toUpperCase();
                if (stUpper === 'CPNS') badgeClass = 'bg-warning text-dark';
                else if (stUpper.includes('PPPK')) badgeClass = 'bg-info text-dark';
                else if (stUpper.includes('NON') || stUpper.includes('PJLP')) badgeClass = 'bg-secondary';
                else if (stUpper.includes('PUTIH')) badgeClass = 'bg-light text-dark border';

                tbody += `<tr>
                    <td>${idx + 1}</td>
                    <td>
                        <div class="d-flex align-items-center gap-2">
                            <img src="${fotoSrc}" class="rounded-circle shadow-sm object-fit-cover flex-shrink-0" style="width: 38px; height: 38px; border: 2px solid #E2E8F0;" alt="Foto ${p.nama || ''}" onerror="this.onerror=null;this.src='https://ui-avatars.com/api/?name=${encodeURIComponent(p.nama || 'P')}&background=6366F1&color=fff&bold=true&size=128';">
                            <div>
                                <div class="fw-bold text-dark">${p.nama || '-'}</div>
                                <div class="small text-muted" style="font-size:0.75rem;">${p.kategori || ''}</div>
                            </div>
                        </div>
                    </td>
                    <td>
                        <div class="small lh-tight">
                            <div class="mb-1"><span class="badge bg-light text-secondary border me-1" style="font-size:0.65rem;">NIK</span><span class="fw-semibold text-dark">${p.nik || '-'}</span></div>
                            <div class="mb-1"><span class="badge bg-light text-secondary border me-1" style="font-size:0.65rem;">NIP</span><span class="fw-semibold text-dark">${p.nip || '-'}</span></div>
                            <div><span class="badge bg-light text-secondary border me-1" style="font-size:0.65rem;">NRK</span><span class="fw-semibold text-dark">${p.nrk || '-'}</span></div>
                        </div>
                    </td>
                    <td><span class="fw-semibold text-dark">${jabatanPergub}</span></td>
                    <td><span class="text-secondary">${jabatanKepmenpan}</span></td>
                    <td><span class="badge bg-light text-dark border">${statusRumpun}</span></td>
                    <td><span class="badge ${badgeClass}">${statusPegawai}</span></td>
                    <td><span class="fw-semibold text-dark"><i class="fas fa-map-marker-alt text-danger me-1"></i>${unitTugas}</span></td>
                    <td class="text-center">
                        <div class="btn-group btn-group-sm" role="group">
                            <button class="btn btn-outline-info rounded-pill me-1" onclick="window.viewProfilPegawai(${origIdx})" title="Lihat Profil">
                                <i class="fas fa-eye me-1"></i>Lihat Profil
                            </button>
                            <button class="btn btn-outline-primary rounded-pill me-1" onclick="window.editForm(${origIdx})" title="Edit">
                                <i class="fas fa-edit me-1"></i>Edit
                            </button>
                            <button class="btn btn-outline-danger rounded-pill" onclick="window.deletePegawai(${origIdx})" title="Hapus">
                                <i class="fas fa-trash me-1"></i>Hapus
                            </button>
                        </div>
                    </td>
                </tr>`;
            });
            $('#tableMaster tbody').html(tbody);
            try { tableMasterRef = $('#tableMaster').DataTable(); } catch(e){}
        }

        window.applyMasterFilter = function() {
            window.renderTableMaster();
        };

        window.currentViewedPegawaiIdx = -1;

        window.viewProfilPegawai = function(idx) {
            if (idx < 0 || idx >= dataPegawai.length) return;
            window.currentViewedPegawaiIdx = idx;
            const p = dataPegawai[idx];

            let defaultAvatar = `https://ui-avatars.com/api/?name=${encodeURIComponent(p.nama || 'P')}&background=6366F1&color=fff&bold=true&size=128`;
            $('#v_foto').attr('src', p.foto && p.foto.trim() !== '' ? p.foto : defaultAvatar);
            $('#v_nama').text(p.nama || '-');
            $('#v_status_badge').text(`${p.status_pegawai || 'PNS'} | ${p.tempat_tugas || p.nama_ukpd || '-'}`);

            let qrVal = p.nip || p.nik || p.nrk || p.nama || 'SIMPEG-PKSU';
            $('#v_qr_code').attr('src', `https://api.qrserver.com/v1/create-qr-code/?size=120x120&data=${encodeURIComponent(qrVal)}`);

            $('#v_nik').text(p.nik || '-');
            $('#v_nip').text(p.nip || '-');
            $('#v_nrk').text(p.nrk || '-');
            $('#v_jk').text(p.jenis_kelamin || '-');
            $('#v_ttl').text(`${p.tempat_lahir || '-'}, ${p.tanggal_lahir || '-'}`);
            $('#v_agama_nikah').text(`${p.agama || '-'} / ${p.status_nikah || '-'}`);
            $('#v_nohp').text(p.no_hp || p.nohp || '-');
            $('#v_email').text(p.email || '-');
            $('#v_alamat').text(p.alamat || '-');

            $('#v_jabatan_pergub').text(p.jabatan_orb || p.jabatan_pergub || p.jabatan || '-');
            $('#v_jabatan_kepmenpan').text(p.jabatan_permenpan11 || p.jabatan_kepmenpan11 || p.jabatan_permenpan41 || p.jabatan || '-');
            $('#v_status_rumpun').text(p.status_rumpun || p.rumpun || '-');
            $('#v_status_pegawai').text(p.status_pegawai || '-');
            $('#v_unit_tugas').text(p.tempat_tugas || p.nama_ukpd || '-');
            $('#v_pangkat_gol').text(p.pangkat_gol || '-');
            $('#v_tmt').text(p.tmt || '-');
            $('#v_kategori').text(p.kategori || '-');

            $('#v_str').text(p.str || '-');
            $('#v_aktif_str').text(p.aktif_str || '-');
            $('#v_sip').text(p.sip || '-');
            $('#v_aktif_sip').text(p.aktif_sip || '-');

            $('#v_btn_edit').attr('onclick', `bootstrap.Modal.getInstance(document.getElementById('modalProfilPegawai')).hide(); window.editForm(${idx});`);
            $('#v_btn_delete').attr('onclick', `bootstrap.Modal.getInstance(document.getElementById('modalProfilPegawai')).hide(); window.deletePegawai(${idx});`);
            $('#v_btn_print_pdf').attr('onclick', `window.printProfilePDF(${idx});`);

            new bootstrap.Modal(document.getElementById('modalProfilPegawai')).show();
        };

        window.printProfilePDF = function(idx) {
            let targetIdx = idx !== undefined ? idx : window.currentViewedPegawaiIdx;
            if (targetIdx === undefined || targetIdx < 0 || targetIdx >= dataPegawai.length) {
                showToast("Data pegawai tidak ditemukan untuk dicetak.", "warning");
                return;
            }
            const p = dataPegawai[targetIdx];
            if (!p) return;

            let defaultAvatar = `https://ui-avatars.com/api/?name=${encodeURIComponent(p.nama || 'P')}&background=6366F1&color=fff&bold=true&size=128`;
            let fotoSrc = p.foto && p.foto.trim() !== '' ? p.foto : defaultAvatar;
            let todayStr = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });

            let printHTML = `<!DOCTYPE html>
<html b:css='false' b:defaultmagic='true' b:layoutsUrl='http://www.google.com/layouts' b:responsive='true' b:version='2' class='v2' expr:dir='data:blog.languageDirection' xmlns='http://www.w3.org/1999/xhtml' xmlns:b='http://www.google.com/2005/gml/b' xmlns:data='http://www.google.com/2005/gml/data' xmlns:expr='http://www.google.com/2005/gml/expr'>
<head>
    <meta charset="UTF-8">
    <title>BIODATA PEGAWAI - ${(p.nama || 'PEGAWAI').toUpperCase()}</title>
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet">
    <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" rel="stylesheet">
    ___STYLE_BLOCK_1___
</head>
<body>
<b:section id="main" class="main">
<b:widget id="Blog1" locked="true" title="Blog Posts" type="Blog" version="1">
<b:includable id="main">
    <div class="no-print mb-3 text-end">
        <button onclick="window.print()" class="btn btn-primary btn-sm px-4 rounded-pill shadow-sm"><i class="fas fa-print me-1"></i> Cetak Sekarang / Simpan PDF</button>
        <button onclick="window.close()" class="btn btn-secondary btn-sm px-3 rounded-pill ms-1">Tutup</button>
    </div>

    <!-- KOP SURAT RESMI PEMPROV DKI JAKARTA -->
    <div class="kop-container d-flex align-items-center justify-content-between gap-3">
        <div class="text-center" style="width: 70px;">
            <img src="https://upload.wikimedia.org/wikipedia/commons/e/eb/Coat_of_arms_of_Jakarta.svg" style="width: 62px; height: auto;" alt="Lambang Jaya Raya DKI Jakarta" onerror="this.style.display='none'">
        </div>
        <div class="kop-text text-center flex-grow-1">
            <div class="kop-title-prov">PEMERINTAH PROVINSI DKI JAKARTA</div>
            <div class="kop-title-dinas">DINAS KESEHATAN</div>
            <div class="kop-title-sudi">SUKU DINAS KESEHATAN KABUPATEN ADMINISTRASI KEPULAUAN SERIBU</div>
            <div class="kop-title-pkm">PUSKESMAS KEPULAUAN SERIBU UTARA</div>
            <div class="kop-address">Jl. Utama Pulau Kelapa, Kec. Kepulauan Seribu Utara, Kab. Adm. Kepulauan Seribu, Kode Pos 14540<br>Email: pkmkepseributara@jakarta.go.id • JAKARTA</div>
        </div>
        <div style="width: 70px;"></div>
    </div>
    <div class="garis-ganda-kedinasan"></div>

    <!-- JUDUL DOKUMEN -->
    <div class="doc-heading">
        <h5>RINGKASAN BIODATA PROFIL PEGAWAI</h5>
        <p>Sistem Informasi Manajemen Kepegawaian (SIMPEG Digital) • Tanggal Cetak: ${todayStr}</p>
    </div>

    <!-- HEADER SUMMARY -->
    <div class="summary-box d-flex align-items-center gap-3">
        <img src="${fotoSrc}" class="foto-profil flex-shrink-0" alt="Foto">
        <div class="flex-grow-1">
            <h4 class="fw-bold mb-1 text-dark" style="font-size: 13pt;">${p.nama || '-'}</h4>
            <div class="text-primary fw-bold mb-1" style="font-size: 10pt;">${p.jabatan_orb || p.jabatan_pergub || p.jabatan || '-'}</div>
            <div class="d-flex flex-wrap gap-2 text-muted" style="font-size: 8.5pt;">
                <span><strong class="text-dark">NIP:</strong> ${p.nip || '-'}</span> | 
                <span><strong class="text-dark">NRK:</strong> ${p.nrk || '-'}</span> | 
                <span><strong class="text-dark">NIK:</strong> ${p.nik || '-'}</span>
            </div>
            <div class="mt-2">
                <span class="badge bg-primary px-2 py-1">${p.status_pegawai || 'PNS'}</span>
                <span class="badge bg-dark px-2 py-1 ms-1">${p.tempat_tugas || p.nama_ukpd || '-'}</span>
            </div>
        </div>
    </div>

    <!-- BAGIAN I: IDENTITAS PRIBADI -->
    <div class="section-bar"><i class="fas fa-user me-1"></i> I. Identitas Pribadi & Kontak</div>
    <table class="tbl-info">
        <tr>
            <td class="lbl">Nama Lengkap</td>
            <td class="val">: ${p.nama || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">NIK (Nomor Induk Kependudukan)</td>
            <td class="val">: ${p.nik || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">NIP (Nomor Induk Pegawai)</td>
            <td class="val">: ${p.nip || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">NRK (Nomor Registrasi Kepegawaian)</td>
            <td class="val">: ${p.nrk || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Jenis Kelamin</td>
            <td class="val">: ${p.jenis_kelamin || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Tempat, Tanggal Lahir</td>
            <td class="val">: ${p.tempat_lahir || '-'}, ${p.tanggal_lahir || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Agama & Status Pernikahan</td>
            <td class="val">: ${p.agama || '-'} / ${p.status_nikah || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Nomor Telepon / WhatsApp</td>
            <td class="val">: ${p.no_hp || p.nohp || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Alamat Email</td>
            <td class="val">: ${p.email || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Alamat Tempat Tinggal</td>
            <td class="val">: ${p.alamat || '-'}</td>
        </tr>
    </table>

    <!-- BAGIAN II: JABATAN & KEPEGAWAIAN -->
    <div class="section-bar"><i class="fas fa-briefcase me-1"></i> II. Data Jabatan & Kepegawaian</div>
    <table class="tbl-info">
        <tr>
            <td class="lbl">Jabatan Pergub 1/2017 (SOTK)</td>
            <td class="val">: ${p.jabatan_orb || p.jabatan_pergub || p.jabatan || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Jabatan Kepmenpan 11 / Pelaksana</td>
            <td class="val">: ${p.jabatan_permenpan11 || p.jabatan_kepmenpan11 || p.jabatan_permenpan41 || p.jabatan || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Rumpun Jabatan</td>
            <td class="val">: ${p.status_rumpun || p.rumpun || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Status Kepegawaian</td>
            <td class="val">: ${p.status_pegawai || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Unit Tugas / Lokasi Kerja</td>
            <td class="val">: ${p.tempat_tugas || p.nama_ukpd || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Pangkat / Golongan Ruang</td>
            <td class="val">: ${p.pangkat_gol || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">TMT Pegawai</td>
            <td class="val">: ${p.tmt || '-'}</td>
        </tr>
        <tr>
            <td class="lbl">Kategori SDMK</td>
            <td class="val">: ${p.kategori || '-'}</td>
        </tr>
    </table>

    <!-- BAGIAN III: LISENSI PROFESI -->
    <div class="section-bar"><i class="fas fa-id-card me-1"></i> III. Lisensi Profesi (STR & SIP)</div>
    <table class="tbl-info">
        <tr>
            <td class="lbl">Nomor STR (Surat Tanda Registrasi)</td>
            <td class="val">: ${p.str || '-'} (Masa Aktif s/d: ${p.aktif_str || '-'})</td>
        </tr>
        <tr>
            <td class="lbl">Nomor SIP (Surat Izin Praktik)</td>
            <td class="val">: ${p.sip || '-'} (Masa Aktif s/d: ${p.aktif_sip || '-'})</td>
        </tr>
    </table>

    <!-- BAGIAN IV: LEGALITAS -->
    <div class="ttd-section clearfix">
        <div class="ttd-box">
            <div>Kepulauan Seribu Utara, ${todayStr}</div>
            <div class="fw-semibold">Pengelola Kepegawaian / SIMPEG</div>
            <div class="ttd-space"></div>
            <div class="fw-bold text-decoration-underline">Puskesmas Kepulauan Seribu Utara</div>
            <div class="text-muted" style="font-size: 8pt;">Dokumen Resmi SIMPEG Digital</div>
        </div>
    </div>

    <script>
        window.onload = function() {
            setTimeout(function() {
                window.print();
            }, 400);
        };
    <\/script>
</b:includable>
</b:widget>
</b:section>
</body>
</html>`;

            let printWindow = window.open('', '_blank', 'height=800,width=950');
            if (printWindow) {
                printWindow.document.write(printHTML);
                printWindow.document.close();
                printWindow.focus();
            } else {
                let printIframe = document.getElementById('pdfPrintIframe');
                if (!printIframe) {
                    printIframe = document.createElement('iframe');
                    printIframe.id = 'pdfPrintIframe';
                    printIframe.style.display = 'none';
                    document.body.appendChild(printIframe);
                }
                let doc = printIframe.contentWindow.document;
                doc.open();
                doc.write(printHTML);
                doc.close();
                setTimeout(function() {
                    printIframe.contentWindow.focus();
                    printIframe.contentWindow.print();
                }, 500);
            }
        };

        /* ==========================================================================
           QR CODE SCANNER & LOOKUP MODULE FOR PEGAWAI ID CARDS
           ========================================================================== */
        let html5QrCode = null;
        let currentCameraFacingMode = "environment";

        window.openQRScannerModal = function() {
            $('#qr-scanner-alert').addClass('d-none').text('');
            $('#manualQRInput').val('');
            const modalEl = document.getElementById('modalQRScanner');
            if (modalEl) {
                const bsModal = new bootstrap.Modal(modalEl);
                bsModal.show();
            }
        };

        window.startQRCameraScanner = function() {
            $('#qr-scanner-placeholder').addClass('d-none');
            $('#qr-scanner-alert').addClass('d-none').text('');

            if (html5QrCode && html5QrCode.isScanning) {
                return;
            }

            if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                $('#qr-scanner-placeholder').removeClass('d-none');
                $('#qr-scanner-alert').removeClass('d-none').html(
                    `<i class="fas fa-exclamation-triangle me-1"></i> Perangkat atau browser ini tidak mendukung akses kamera langsung. Silakan gunakan <strong>Upload File QR Gambar</strong> atau pencarian manual.`
                );
                return;
            }

            try {
                if (!html5QrCode) {
                    html5QrCode = new Html5Qrcode("qr-reader");
                }

                const config = { fps: 12, qrbox: { width: 220, height: 220 } };

                html5QrCode.start(
                    { facingMode: currentCameraFacingMode },
                    config,
                    window.onQRScanSuccess,
                    window.onQRScanFailure
                ).catch(err => {
                    let fallbackFacingMode = currentCameraFacingMode === "environment" ? "user" : "environment";
                    html5QrCode.start(
                        { facingMode: fallbackFacingMode },
                        config,
                        window.onQRScanSuccess,
                        window.onQRScanFailure
                    ).catch(err2 => {
                        $('#qr-scanner-placeholder').removeClass('d-none');
                        const isNotAllowed = err2 && (err2.name === 'NotAllowedError' || String(err2).includes('Permission denied') || String(err2).includes('NotAllowedError'));
                        const errMessage = isNotAllowed 
                            ? 'Izin akses kamera ditolak atau diblokir oleh browser/iframe' 
                            : String(err2.message || err2 || 'Kamera tidak dapat diakses');

                        $('#qr-scanner-alert').removeClass('d-none').html(
                            `<i class="fas fa-exclamation-triangle me-1"></i> <strong>Akses Kamera Terkendala:</strong> ${errMessage}.<br><span class="small text-muted mt-1 d-block">Solusi: Izinkan kamera di browser, atau gunakan fitur <strong>Upload File QR Gambar</strong> / <strong>Pencarian Manual NIP</strong> di bawah.</span>`
                        );
                    });
                });
            } catch(e) {
                $('#qr-scanner-placeholder').removeClass('d-none');
                const eText = String(e.message || e).replace(/</g, '&lt;');
                $('#qr-scanner-alert').removeClass('d-none').html(
                    `<i class="fas fa-exclamation-triangle me-1"></i> Kendala scanner kamera: ${eText}.`
                );
            }
        };

        window.stopQRCameraScanner = function() {
            if (html5QrCode) {
                if (html5QrCode.isScanning) {
                    html5QrCode.stop().then(() => {
                        try { html5QrCode.clear(); } catch(e) {}
                        $('#qr-scanner-placeholder').removeClass('d-none');
                    }).catch(err => {
                        console.error("Error stopping QR scanner:", err);
                        $('#qr-scanner-placeholder').removeClass('d-none');
                    });
                } else {
                    try { html5QrCode.clear(); } catch(e) {}
                    $('#qr-scanner-placeholder').removeClass('d-none');
                }
            }
        };

        window.switchQRCamera = function() {
            currentCameraFacingMode = currentCameraFacingMode === "environment" ? "user" : "environment";
            if (html5QrCode && html5QrCode.isScanning) {
                html5QrCode.stop().then(() => {
                    window.startQRCameraScanner();
                }).catch(() => {
                    window.startQRCameraScanner();
                });
            } else {
                window.startQRCameraScanner();
            }
        };

        window.handleQRFileUpload = function(e) {
            const file = e.target.files && e.target.files[0];
            if (!file) return;

            $('#qr-scanner-alert').addClass('d-none').text('');

            if (!html5QrCode) {
                html5QrCode = new Html5Qrcode("qr-reader");
            }

            if (html5QrCode.isScanning) {
                html5QrCode.stop().then(() => {
                    processFile(file);
                }).catch(() => {
                    processFile(file);
                });
            } else {
                processFile(file);
            }

            function processFile(fileObj) {
                html5QrCode.scanFile(fileObj, true)
                .then(decodedText => {
                    window.onQRScanSuccess(decodedText);
                })
                .catch(err => {
                    console.warn("File QR scan error:", err);
                    $('#qr-scanner-alert').removeClass('d-none').html(
                        `<i class="fas fa-exclamation-circle me-1"></i> QR Code tidak terdeteksi pada file gambar yang dipilih. Pastikan gambar memuat QR Code ID Card yang jelas.`
                    );
                });
            }
        };

        window.onQRScanFailure = function(error) {
            // Ignored per frame scan
        };

        window.onQRScanSuccess = function(decodedText) {
            console.log("QR Code decoded text:", decodedText);
            if (!decodedText) return;

            try {
                const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                osc.type = 'sine';
                osc.frequency.value = 880;
                gain.gain.setValueAtTime(0.12, audioCtx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.00001, audioCtx.currentTime + 0.25);
                osc.connect(gain);
                gain.connect(audioCtx.destination);
                osc.start();
                osc.stop(audioCtx.currentTime + 0.25);
            } catch(e) {}

            let searchKey = String(decodedText).trim();

            if (searchKey.startsWith('{') && searchKey.endsWith('}')) {
                try {
                    const obj = JSON.parse(searchKey);
                    searchKey = obj.nip || obj.nik || obj.nrk || obj.nama || obj.id || searchKey;
                } catch(e) {}
            } else if (searchKey.includes('http://') || searchKey.includes('https://')) {
                try {
                    const u = new URL(searchKey);
                    searchKey = u.searchParams.get('nip') || u.searchParams.get('nik') || u.searchParams.get('nrk') || u.searchParams.get('q') || searchKey;
                } catch(e) {}
            }

            searchKey = String(searchKey).trim();
            const cleanDigits = searchKey.replace(/\D/g, '');

            let foundIdx = -1;
            if (dataPegawai && dataPegawai.length > 0) {
                foundIdx = dataPegawai.findIndex(p => {
                    if (!p) return false;
                    const pNip = String(p.nip || '').trim();
                    const pNik = String(p.nik || '').trim();
                    const pNrk = String(p.nrk || '').trim();
                    const pNama = String(p.nama || '').trim().toLowerCase();

                    if (pNip && pNip === searchKey) return true;
                    if (pNik && pNik === searchKey) return true;
                    if (pNrk && pNrk === searchKey) return true;

                    if (cleanDigits.length >= 5) {
                        if (pNip.replace(/\D/g, '') === cleanDigits) return true;
                        if (pNik.replace(/\D/g, '') === cleanDigits) return true;
                        if (pNrk.replace(/\D/g, '') === cleanDigits) return true;
                    }

                    if (searchKey.length >= 3 && pNama.includes(searchKey.toLowerCase())) return true;

                    return false;
                });
            }

            if (foundIdx !== -1) {
                const foundPegawai = dataPegawai[foundIdx];
                window.stopQRCameraScanner();

                const modalEl = document.getElementById('modalQRScanner');
                if (modalEl) {
                    const bsModal = bootstrap.Modal.getInstance(modalEl);
                    if (bsModal) bsModal.hide();
                }

                showToast(`QR Code Cocok! Profil Pegawai: ${foundPegawai.nama}`, "success");

                setTimeout(() => {
                    window.viewProfilPegawai(foundIdx);
                }, 350);
            } else {
                const safeSearchKey = String(searchKey).replace(/</g, '&lt;').replace(/>/g, '&gt;');
                $('#qr-scanner-alert').removeClass('d-none').html(
                    `<i class="fas fa-exclamation-triangle me-1"></i> Data pegawai tidak ditemukan untuk QR: <strong>${safeSearchKey}</strong>. Pastikan ID Card terdaftar pada SIMPEG.`
                );
            }
        };

        window.testManualQRInput = function() {
            const val = $('#manualQRInput').val();
            if (!val || !val.trim()) {
                showToast("Masukkan NIP, NIK, atau Nama untuk dicari.", "info");
                return;
            }
            window.onQRScanSuccess(val.trim());
        };

        let pendingDeletePegawaiIdx = -1;

        window.deletePegawai = function(idx) {
            if (idx < 0 || idx >= dataPegawai.length) return;
            const p = dataPegawai[idx];
            if (!p) return;

            pendingDeletePegawaiIdx = idx;
            $('#deletePegawaiTargetName').text(p.nama || 'ini');

            const modalEl = document.getElementById('modalConfirmDeletePegawai');
            if (modalEl) {
                const bsModal = new bootstrap.Modal(modalEl);
                bsModal.show();
            } else {
                if (confirm(`Apakah Anda yakin ingin menghapus data pegawai "${p.nama || 'ini'}"?`)) {
                    window.executeDeletePegawai();
                }
            }
        };

        window.executeDeletePegawai = function() {
            if (pendingDeletePegawaiIdx < 0 || pendingDeletePegawaiIdx >= dataPegawai.length) return;
            const p = dataPegawai[pendingDeletePegawaiIdx];
            if (!p) return;

            const targetNik = p.nik;
            const targetNip = p.nip;
            const targetRowIndex = p.rowIndex;
            const targetNama = p.nama;

            const modalEl = document.getElementById('modalConfirmDeletePegawai');
            if (modalEl) {
                const bsModal = bootstrap.Modal.getInstance(modalEl);
                if (bsModal) bsModal.hide();
            }

            fetch('/api/gas', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ 
                    action: 'hapusPegawai', 
                    data: { rowIndex: targetRowIndex, nip: targetNip, nik: targetNik, nama: targetNama } 
                })
            }).then(r => r.json()).then(res => {
                const realIdx = dataPegawai.findIndex(item => 
                    (targetRowIndex !== undefined && targetRowIndex !== null && item.rowIndex === targetRowIndex) ||
                    (targetNip && item.nip && String(item.nip).trim() === String(targetNip).trim()) ||
                    (targetNik && item.nik && String(item.nik).trim() === String(targetNik).trim()) ||
                    (targetNama && item.nama && String(item.nama).trim() === String(targetNama).trim())
                );

                if (realIdx !== -1) {
                    dataPegawai.splice(realIdx, 1);
                } else if (pendingDeletePegawaiIdx < dataPegawai.length) {
                    dataPegawai.splice(pendingDeletePegawaiIdx, 1);
                }

                pendingDeletePegawaiIdx = -1;
                refreshAllData();
                showToast("Data pegawai berhasil dihapus!", "success");
            }).catch(err => {
                console.error("Error deleting pegawai:", err);
                const realIdx = dataPegawai.findIndex(item => 
                    (targetRowIndex !== undefined && targetRowIndex !== null && item.rowIndex === targetRowIndex) ||
                    (targetNip && item.nip && String(item.nip).trim() === String(targetNip).trim()) ||
                    (targetNik && item.nik && String(item.nik).trim() === String(targetNik).trim()) ||
                    (targetNama && item.nama && String(item.nama).trim() === String(targetNama).trim())
                );

                if (realIdx !== -1) {
                    dataPegawai.splice(realIdx, 1);
                } else if (pendingDeletePegawaiIdx < dataPegawai.length) {
                    dataPegawai.splice(pendingDeletePegawaiIdx, 1);
                }

                pendingDeletePegawaiIdx = -1;
                refreshAllData();
                showToast("Data pegawai dihapus secara lokal.", "info");
            });
        };

