        function getStatusDist(list) {
            const dist = { 'PNS': 0, 'CPNS': 0, 'PPPK': 0, 'PPPK PW': 0, 'NON PNS': 0, 'PJLP': 0 };
            list.forEach(p => {
                if (!p) return;
                const s = (p.status_pegawai || 'Lainnya').trim().toUpperCase();
                if (dist[s] !== undefined) {
                    dist[s]++;
                } else if (s) {
                    dist[s] = (dist[s] || 0) + 1;
                }
            });
            return dist;
        }

        function getGenderDist(list) {
            const dist = {};
            list.forEach(p => {
                if (!p) return;
                const g = (p.jenis_kelamin || 'Tidak Ditentukan').trim();
                dist[g] = (dist[g] || 0) + 1;
            });
            return dist;
        }

        function getUnitDist(list) {
            const dist = {};
            list.forEach(p => {
                if (!p) return;
                const u = (p.tempat_tugas || 'Belum Diatur').trim();
                dist[u] = (dist[u] || 0) + 1;
            });
            return dist;
        }

        function getRumpunDist(list) {
            const dist = {};
            list.forEach(p => {
                if (!p) return;
                const r = (p.rumpun || 'Belum Diatur').trim();
                dist[r] = (dist[r] || 0) + 1;
            });
            return dist;
        }

        function getPangkatDist(list) {
            const dist = {};
            list.forEach(p => {
                if (!p) return;
                const pg = (p.pangkat_gol || 'Belum Diatur').trim();
                dist[pg] = (dist[pg] || 0) + 1;
            });
            return dist;
        }

        function getPendidikanDist(list) {
            const dist = {};
            list.forEach(p => {
                if (!p) return;
                const edu = (p.pendidikan || 'Belum Diatur').trim();
                dist[edu] = (dist[edu] || 0) + 1;
            });
            return dist;
        }

        function getStrExpiringCount(list) {
            let count = 0;
            const now = new Date();
            list.forEach(p => {
                if (!p || !p.aktif_str) return;
                const strDate = new Date(p.aktif_str);
                if (isNaN(strDate.getTime())) return;
                const diffDays = (strDate.getTime() - now.getTime()) / (1000 * 3600 * 24);
                if (diffDays <= 90) {
                    count++;
                }
            });
            return count;
        }

