        window.calculateDocDays = function(dateStr) {
            if (!dateStr || dateStr === '-' || String(dateStr).trim() === '') return null;
            const cleanStr = String(dateStr).trim();
            let expDate;
            if (cleanStr.includes('/')) {
                const parts = cleanStr.split('/');
                if (parts.length === 3) {
                    expDate = new Date(`${parts[2]}-${parts[1]}-${parts[0]}`);
                } else {
                    expDate = new Date(cleanStr);
                }
            } else {
                expDate = new Date(cleanStr);
            }
            if (isNaN(expDate.getTime())) return null;

            const today = new Date();
            today.setHours(0, 0, 0, 0);
            expDate.setHours(0, 0, 0, 0);

            const diffTime = expDate.getTime() - today.getTime();
            return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        };

        window.getDocStatusBadge = function(days) {
            if (days === null) {
                return {
                    category: 'EMPTY',
                    badge: '<span class="badge bg-secondary-subtle text-secondary border border-secondary-subtle"><i class="fas fa-question-circle me-1"></i>Belum Diisi</span>',
                    label: 'Belum Diisi',
                    isCritical: false
                };
            }
            if (days < 0) {
                const pastDays = Math.abs(days);
                return {
                    category: 'EXPIRED',
                    badge: `<span class="badge bg-danger text-white border border-danger shadow-sm"><i class="fas fa-times-circle me-1"></i>Expired (${pastDays} hr lalu)</span>`,
                    label: `Kadaluarsa (${pastDays} hari lalu)`,
                    isCritical: true
                };
            }
            if (days <= 30) {
                return {
                    category: 'DANGER',
                    badge: `<span class="badge bg-danger text-white border border-danger shadow-sm"><i class="fas fa-exclamation-triangle me-1"></i>Sisa ${days} Hari (≤ 30)</span>`,
                    label: `Kritis (Sisa ${days} Hari)`,
                    isCritical: true
                };
            }
            if (days <= 60) {
                return {
                    category: 'WARNING',
                    badge: `<span class="badge bg-warning text-dark border border-warning"><i class="fas fa-clock me-1"></i>Sisa ${days} Hari</span>`,
                    label: `Peringatan (Sisa ${days} Hari)`,
                    isCritical: false
                };
            }
            if (days <= 90) {
                return {
                    category: 'INFO',
                    badge: `<span class="badge bg-info-subtle text-info-emphasis border border-info-subtle"><i class="fas fa-info-circle me-1"></i>Sisa ${days} Hari</span>`,
                    label: `Perhatian (Sisa ${days} Hari)`,
                    isCritical: false
                };
            }
            return {
                category: 'VALID',
                badge: `<span class="badge bg-success-subtle text-success border border-success"><i class="fas fa-check-circle me-1"></i>Valid (${days} hr)</span>`,
                label: `Valid (${days} hari)`,
                isCritical: false
            };
        };

