            $('.btn-doc-filter-type').removeClass('active');
            if (window.currentDocTypeFilter === 'ALL') $('.btn-doc-filter-type:eq(0)').addClass('active');
            if (window.currentDocTypeFilter === 'SIP') $('.btn-doc-filter-type:eq(1)').addClass('active');
