        window.sendDocReminderWA = function(nama, nohp, jenisDoc, noDoc, dateStr, days) {
            if (!nohp) {
                showToast("Nomor HP pegawai belum terdaftar.", "warning");
                return;
            }
            let cleanPhone = String(nohp).replace(/[^0-9]/g, '');
            if (cleanPhone.startsWith('0')) {
                cleanPhone = '62' + cleanPhone.substring(1);
            }

            let statusMsg = days < 0 ? `telah KADALUARSA sejak ${Math.abs(days)} hari yang lalu` : `akan BERAKHIR pada tanggal ${dateStr || '-'} (Sisa ${days} hari lagi)`;
            let text = `Yth. Bapak/Ibu ${nama},\n\nDiberitahukan dari Bagian Kepegawaian PKSU bahwa dokumen *${jenisDoc}* Anda (No: ${noDoc || '-'}) ${statusMsg}.\n\nMohon untuk segera melakukan pembaruan perizinan dokumen tersebut demi kelancaran administrasi dan izin praktik pelayanan.\n\nTerima kasih.\n*SIMPEG Digital Puskesmas Kepulauan Seribu Utara*`;

            let waUrl = `https://wa.me/${cleanPhone}?text=${encodeURIComponent(text)}`;
            window.open(waUrl, '_blank');
        };

        window.renderDocExpirationTable = function() {
            if (!dataPegawai || !Array.isArray(dataPegawai)) return;

            const searchQuery = ($('#searchDocMonitoring').val() || '').toLowerCase().trim();
            const statusFilter = $('#filterDocStatus').val() || 'KRITIS_ALL';
            const typeFilter = window.currentDocTypeFilter || 'ALL';

            let docEntries = [];
            let criticalEmployeesCount = 0;

            dataPegawai.forEach((p, pIdx) => {
                let docs = [];
                if (typeFilter === 'ALL' || typeFilter === 'SIP') {
                    docs.push({
                        type: 'SIP',
                        no: p.sip || p.no_sip || '-',
                        dateStr: p.aktif_sip || p.m_sip || p.masa_aktif_sip || '',
                    });
                }
                if (typeFilter === 'ALL' || typeFilter === 'STR') {
                    docs.push({
                        type: 'STR',
                        no: p.str || p.no_str || '-',
                        dateStr: p.aktif_str || p.m_str || p.masa_aktif_str || '',
                    });
                }

                let employeeHasCritical = false;

                docs.forEach(d => {
                    const days = window.calculateDocDays(d.dateStr);
                    const statusInfo = window.getDocStatusBadge(days);

                    if (statusInfo.isCritical) {
                        employeeHasCritical = true;
                    }

                    docEntries.push({
                        pegawai: p,
                        pIdx: pIdx,
                        docType: d.type,
                        docNo: d.no,
                        dateStr: d.dateStr,
                        days: days,
                        statusInfo: statusInfo
                    });
                });

                if (employeeHasCritical) {
                    criticalEmployeesCount++;
                }
            });

            // Update banner
            if (criticalEmployeesCount > 0) {
                $('#bannerCriticalCount').text(criticalEmployeesCount);
                $('#docWarningBanner').css('display', 'flex').hide().fadeIn();
            } else {
                $('#docWarningBanner').fadeOut();
            }

            // Apply Filter Status
            let filtered = docEntries.filter(item => {
                const cat = item.statusInfo.category;
                if (statusFilter === 'KRITIS_ALL') {
                    return item.statusInfo.isCritical; // EXPIRED or DANGER (<= 30 days)
                } else if (statusFilter === 'EXPIRED') {
                    return cat === 'EXPIRED';
                } else if (statusFilter === 'DANGER') {
                    return cat === 'DANGER'; // <= 30 days
                } else if (statusFilter === 'WARNING') {
                    return cat === 'WARNING'; // 31-60 days
                } else if (statusFilter === 'INFO') {
                    return cat === 'INFO'; // 61-90 days
                }
                return true; // ALL
            });

            // Apply Search Query
            if (searchQuery) {
                filtered = filtered.filter(item => {
                    const p = item.pegawai;
                    const text = `${p.nama || ''} ${p.nip || ''} ${p.nik || ''} ${p.tempat_tugas || ''} ${item.docNo || ''} ${item.docType}`.toLowerCase();
                    return text.includes(searchQuery);
                });
            }

            // Sort by Urgency: EXPIRED first, then smallest days, then NULL last
            filtered.sort((a, b) => {
                if (a.days === null && b.days === null) return 0;
                if (a.days === null) return 1;
                if (b.days === null) return -1;
                return a.days - b.days;
            });

            $('#docCountValue').text(filtered.length);

            let html = '';
            if (filtered.length === 0) {
                html = `<tr>
                    <td colspan="7" class="text-center py-4 text-muted">
                        <i class="fas fa-check-circle text-success fs-3 mb-2 d-block"></i>
                        Tidak ditemukan dokumen pegawai dengan kriteria filter yang dipilih.
                    </td>
                </tr>`;
            } else {
                filtered.forEach((item, idx) => {
                    const p = item.pegawai;
                    const origIdx = dataPegawai.indexOf(p);
                    const fotoSrc = p.foto && p.foto.trim() !== '' ? p.foto : `https://ui-avatars.com/api/?name=${encodeURIComponent(p.nama || 'P')}&background=6366F1&color=fff&bold=true&size=128`;
                    const docBadge = item.docType === 'SIP' ? '<span class="badge bg-primary-subtle text-primary border border-primary-subtle fw-bold">SIP</span>' : '<span class="badge bg-warning-subtle text-warning-emphasis border border-warning-subtle fw-bold">STR</span>';

                    html += `<tr>
                        <td class="ps-3 fw-bold text-secondary">${idx + 1}</td>
                        <td>
                            <div class="d-flex align-items-center gap-2">
                                <img src="${fotoSrc}" class="rounded-circle object-fit-cover flex-shrink-0" style="width:36px; height:36px; border:1px solid #cbd5e1;" alt="Foto">
                                <div>
                                    <div class="fw-bold text-dark lh-sm">${p.nama || '-'}</div>
                                    <div class="text-muted" style="font-size:0.75rem;">${p.nip ? 'NIP: ' + p.nip : (p.nik ? 'NIK: ' + p.nik : '-')}</div>
                                </div>
                            </div>
                        </td>
                        <td>
                            <div class="fw-semibold text-dark">${p.tempat_tugas || p.nama_ukpd || '-'}</div>
                            <div class="text-muted" style="font-size:0.75rem;">${p.jabatan || '-'}</div>
                        </td>
                        <td>
                            <div class="d-flex align-items-center gap-2 mb-1">
                                ${docBadge}
                                <span class="fw-mono text-dark fw-bold" style="font-size:0.85rem;">${item.docNo || '-'}</span>
                            </div>
                        </td>
                        <td>
                            <div class="fw-semibold text-dark"><i class="far fa-calendar-alt text-muted me-1"></i>${item.dateStr || '-'}</div>
                        </td>
                        <td>
                            ${item.statusInfo.badge}
                        </td>
                        <td class="text-end pe-3">
                            <div class="btn-group btn-group-sm" role="group">
                                <button type="button" class="btn btn-sm btn-outline-primary rounded-pill me-1" onclick="window.editForm(${origIdx >= 0 ? origIdx : item.pIdx})" title="Edit Data Dokumen">
                                    <i class="fas fa-edit me-1"></i>Edit
                                </button>
                                ${p.no_hp || p.nohp ? `
                                    <button type="button" class="btn btn-sm btn-outline-success rounded-pill" onclick="window.sendDocReminderWA('${(p.nama || '').replace(/'/g, "\\'")}', '${p.no_hp || p.nohp}', '${item.docType}', '${item.docNo}', '${item.dateStr}', ${item.days})" title="Kirim Pengingat WA">
                                        <i class="fab fa-whatsapp me-1"></i>Ingatkan
                                    </button>
                                ` : `
                                    <button type="button" class="btn btn-sm btn-light text-muted rounded-pill" disabled title="No HP belum diisi">
                                        <i class="fab fa-whatsapp me-1"></i>-
                                    </button>
                                `}
                            </div>
                        </td>
                    </tr>`;
                });
            }

            $('#tbodyDocMonitoring').html(html);
        };

        function updateDashboard() {
            const total = dataPegawai.length;

            let countSipKritis = 0;
            let countStrKritis = 0;
            let countDocValid = 0;

            dataPegawai.forEach(p => {
                const sipDays = window.calculateDocDays(p.aktif_sip || p.m_sip || p.masa_aktif_sip);
                const strDays = window.calculateDocDays(p.aktif_str || p.m_str || p.masa_aktif_str);

                if (sipDays !== null && sipDays <= 30) countSipKritis++;
                if (strDays !== null && strDays <= 30) countStrKritis++;

                let hasValidDoc = (sipDays !== null && sipDays > 30) || (strDays !== null && strDays > 30);
                if (hasValidDoc) countDocValid++;
            });

            $('#dash-total').text(total);
            $('#dash-sip-alert').text(countSipKritis);
            $('#dash-str-alert').text(countStrKritis);
            $('#dash-doc-valid').text(countDocValid);

            // Render table
            window.renderDocExpirationTable();

            // Status Distribution Chart
            const statusDist = getStatusDist(dataPegawai);
            renderOrUpdateChart('dashStatus', 'chartStatusDashboard', 'bar', {
                labels: Object.keys(statusDist),
                datasets: [{
                    label: 'Jumlah Pegawai',
                    data: Object.values(statusDist),
                    backgroundColor: ['#8B5CF6', '#10B981', '#F59E0B', '#06B6D4', '#EF4444', '#EC4899'],
                    borderRadius: 8
                }]
            }, barChartOptions);

            // Gender Distribution Chart
            const genderDist = getGenderDist(dataPegawai);
            renderOrUpdateChart('dashGender', 'chartGenderDashboard', 'doughnut', {
                labels: Object.keys(genderDist),
                datasets: [{
                    data: Object.values(genderDist),
                    backgroundColor: ['#06B6D4', '#EC4899', '#8B5CF6'],
                    borderWidth: 2,
                    borderColor: '#ffffff'
                }]
            }, doughnutChartOptions);

            // Unit/Tempat Tugas Distribution Chart
            const unitDist = getUnitDist(dataPegawai);
            renderOrUpdateChart('dashTugas', 'chartTugasDashboard', 'bar', {
                labels: Object.keys(unitDist),
