        $('#formPegawai').on('submit', function(e) {
            e.preventDefault();
            let idx = parseInt($('#editIndex').val());

            let riwayat_keluarga = [];
            $('#containerKeluargaRows tr').each(function() {
                let hub = $(this).find('.k-hub').val();
                let nama = $(this).find('.k-nama').val();
                let jk = $(this).find('.k-jk').val();
                let tgl = $(this).find('.k-tgl').val();
                let pekerjaan = $(this).find('.k-pekerjaan').val();
                if (nama && nama.trim() !== '') {
                    riwayat_keluarga.push({ hub, nama, jk, tgl, pekerjaan });
                }
            });

            let payload = {
                nik: $('#f_nik').val(), nip: $('#f_nip').val(), nrk: $('#f_nrk').val(), nama: $('#f_nama').val(),
                foto: $('#f_foto').val(),
                jabatan: $('#f_jabatan').val(),
                jabatan_orb: $('#f_jabatan_pergub').val(),
                jabatan_permenpan11: $('#f_jabatan_kepmenpan11').val(),
                status_rumpun: $('#f_status_rumpun').val(),
                rumpun: $('#f_rumpun').val(), kategori: $('#f_kategori').val(),
                pangkat_gol: $('#f_pangkat_gol').val(), jenis_kelamin: $('#f_jk').val(), status_pegawai: $('#f_status').val(),
                tempat_tugas: $('#f_tugas').val(), tmt: $('#f_tmt').val(), str: $('#f_str').val(), aktif_str: $('#f_aktif_str').val(),
                sip: $('#f_sip').val(), aktif_sip: $('#f_aktif_sip').val(),
                agama: $('#f_agama').val(), status_nikah: $('#f_status_nikah').val(),
                tempat_lahir: $('#f_tempat_lahir').val(), tanggal_lahir: $('#f_tgl_lahir').val(),
                no_hp: $('#f_nohp').val(), email: $('#f_email').val(), alamat: $('#f_alamat').val(),
                riwayat_keluarga: JSON.stringify(riwayat_keluarga)
            };
            let action = idx === -1 ? 'simpanPegawaiBaru' : 'updatePegawai';
            if (idx !== -1) payload.rowIndex = dataPegawai[idx].rowIndex;

            fetch('/api/gas', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: action, data: payload })
            }).then(r => r.json()).then(res => {
                if(res.success) {
                    bootstrap.Modal.getInstance(document.getElementById('modalPegawai')).hide();
                    showToast("Data tersimpan!", "success");
                    loadDataFromGAS();
                } else showToast(res.message, "danger");
            });
        });

        function getNamaTanpaGelar(nama) {
            if (!nama) return '-';
            let clean = nama.toString().trim();
            // Remove front titles
            clean = clean.replace(/^(drg\.|dr\.|Drs\.|Dra\.|Ir\.|Hj\.|H\.|Prof\.|Dr\.)\s+/gi, '');
            // Remove trailing degrees after comma
            if (clean.includes(',')) {
                clean = clean.split(',')[0].trim();
            }
            return clean || nama;
        }

        function getPangkatWeight(pangkatStr) {
            if (!pangkatStr) return 0;
            const str = pangkatStr.toString().toUpperCase().trim();
            if (str.includes('IV/E')) return 170;
            if (str.includes('IV/D')) return 160;
            if (str.includes('IV/C')) return 150;
            if (str.includes('IV/B')) return 140;
            if (str.includes('IV/A')) return 130;

            if (str.includes('III/D')) return 120;
            if (str.includes('III/C')) return 110;
            if (str.includes('III/B')) return 100;
            if (str.includes('III/A')) return 90;

            if (str.includes('II/D')) return 80;
            if (str.includes('II/C')) return 70;
            if (str.includes('II/B')) return 60;
            if (str.includes('II/A')) return 50;

            if (str.includes('I/D')) return 40;
            if (str.includes('I/C')) return 30;
            if (str.includes('I/B')) return 20;
            if (str.includes('I/A')) return 10;

            if (str.includes('IX')) return 85;
            if (str.includes('PPPK')) return 80;
            if (str.includes('NON PNS') || str.includes('HONORER')) return 5;
            if (str.includes('PJLP')) return 1;

            return 0;
        }

        window.renderDUK = function() {
            if (!dataPegawai || !Array.isArray(dataPegawai)) return;
            let list = [...dataPegawai];

            const statusFilter = $('#filterDUKStatus').val() || 'ALL';
            const tugasFilter = $('#filterDUKTugas').val() || '';
            const searchQuery = ($('#searchDUK').val() || '').toLowerCase().trim();

            if (statusFilter === 'ASN') {
                list = list.filter(p => ['PNS', 'CPNS', 'PPPK'].includes((p.status_pegawai || '').toUpperCase()));
            } else if (statusFilter === 'PNS') {
                list = list.filter(p => ['PNS', 'CPNS'].includes((p.status_pegawai || '').toUpperCase()));
            } else if (statusFilter === 'PPPK') {
                list = list.filter(p => (p.status_pegawai || '').toUpperCase().includes('PPPK'));
            } else if (statusFilter === 'NON PNS') {
                list = list.filter(p => ['NON PNS', 'PJLP', 'HONORER'].includes((p.status_pegawai || '').toUpperCase()));
            }

            if (tugasFilter) {
                list = list.filter(p => (p.tempat_tugas || '') === tugasFilter);
            }

            if (searchQuery) {
                list = list.filter(p => 
                    (p.nama || '').toLowerCase().includes(searchQuery) ||
                    (p.nip || '').toLowerCase().includes(searchQuery) ||
                    (p.nik || '').toLowerCase().includes(searchQuery) ||
                    (p.jabatan || '').toLowerCase().includes(searchQuery) ||
                    (p.pangkat_gol || '').toLowerCase().includes(searchQuery)
                );
            }

            // Sort by Pangkat Weight descending, then TMT ascending, then Nama ascending
            list.sort((a, b) => {
                const weightA = getPangkatWeight(a.pangkat_gol);
                const weightB = getPangkatWeight(b.pangkat_gol);
                if (weightB !== weightA) {
                    return weightB - weightA;
                }
                const tmtA = a.tmt ? new Date(a.tmt).getTime() : 9999999999999;
                const tmtB = b.tmt ? new Date(b.tmt).getTime() : 9999999999999;
                if (tmtA !== tmtB) {
                    return tmtA - tmtB;
                }
                return (a.nama || '').localeCompare(b.nama || '');
            });

            let tbody = '';
            if (list.length === 0) {
                tbody = `<tr><td colspan="7" class="text-center py-4 text-muted">Tidak ada data pegawai dalam DUK.</td></tr>`;
            } else {
                list.forEach((p, idx) => {
                    let fotoSrc = p.foto && p.foto.trim() !== '' ? p.foto : `https://ui-avatars.com/api/?name=${encodeURIComponent(p.nama || 'P')}&background=6366F1&color=fff&bold=true&size=128`;
                    let badgeClass = 'bg-secondary';
                    const st = (p.status_pegawai || '').toUpperCase();
                    if (st === 'PNS') badgeClass = 'bg-primary';
                    else if (st === 'PPPK') badgeClass = 'bg-info text-dark';
                    else if (st === 'CPNS') badgeClass = 'bg-warning text-dark';

                    // 1. Nama Tanpa Gelar
                    const namaTanpaGelar = getNamaTanpaGelar(p.nama);

                    // 2. Wilayah & UKPD
                    const wilayah = "Sudin Kesehatan Kepulauan Seribu";
                    const ukpd = p.tempat_tugas || "Puskesmas Kepulauan Seribu Utara";

                    // 3. Riwayat Jabatan (Sorted newest first)
                    let rJabatan = [];
                    if (p.riwayat_jabatan) {
                        try {
                            rJabatan = typeof p.riwayat_jabatan === 'string' ? JSON.parse(p.riwayat_jabatan) : p.riwayat_jabatan;
                        } catch(e) { rJabatan = []; }
                    }
                    if (!Array.isArray(rJabatan) || rJabatan.length === 0) {
                        rJabatan = [{ jabatan: p.jabatan || '-', tmt: p.tmt || '-', unit: ukpd }];
                    }
                    rJabatan.sort((a, b) => new Date(b.tmt || '1900-01-01').getTime() - new Date(a.tmt || '1900-01-01').getTime());

                    let htmlJabatan = '<ol class="mb-0 ps-3 small" style="line-height:1.4;">';
                    rJabatan.forEach((j, jIdx) => {
                        const isTerbaru = jIdx === 0;
                        htmlJabatan += `
                            <li class="mb-1">
                                <span class="${isTerbaru ? 'fw-bold text-primary' : 'text-dark'}">${j.jabatan || '-'}</span>
                                ${isTerbaru ? '<span class="badge bg-primary-subtle text-primary border border-primary-subtle ms-1" style="font-size:0.6rem;">Terbaru</span>' : ''}
                                <div class="text-muted" style="font-size:0.75rem;"><i class="far fa-calendar-alt me-1"></i>TMT: ${j.tmt || '-'} ${j.unit ? '| ' + j.unit : ''}</div>
                            </li>
                        `;
                    });
                    htmlJabatan += '</ol>';

                    // 4. Riwayat Pendidikan (Sorted newest first) & Pendidikan SIASN
                    let rPendidikan = [];
                    if (p.riwayat_pendidikan) {
                        try {
                            rPendidikan = typeof p.riwayat_pendidikan === 'string' ? JSON.parse(p.riwayat_pendidikan) : p.riwayat_pendidikan;
                        } catch(e) { rPendidikan = []; }
                    }
                    if (!Array.isArray(rPendidikan) || rPendidikan.length === 0) {
                        rPendidikan = [{ tingkat: p.pendidikan || '-', jurusan: '', sekolah: '-', tgl: '-' }];
                    }
                    rPendidikan.sort((a, b) => {
                        let dateA = a.tgl || a.thn || '1900';
                        let dateB = b.tgl || b.thn || '1900';
                        return new Date(dateB).getTime() - new Date(dateA).getTime();
                    });

                    // Pendidikan Terakhir Diakui SIASN (top entry or p.pendidikan)
                    const topEdu = rPendidikan[0] || {};
                    const eduLevel = topEdu.tingkat || p.pendidikan || '-';
                    const eduJurusan = topEdu.jurusan ? ` (${topEdu.jurusan})` : '';
                    const pendidikanSIASN = `${eduLevel}${eduJurusan}`;

                    let htmlPendidikan = `
                        <div class="p-1 px-2 mb-2 rounded bg-success-subtle text-success-emphasis border border-success-subtle small fw-bold">
                            <i class="fas fa-check-circle text-success me-1"></i>
                            Diakui SIASN: <span class="text-dark">${pendidikanSIASN}</span>
                        </div>
                        <ol class="mb-0 ps-3 small" style="line-height:1.4;">
                    `;
                    rPendidikan.forEach((e) => {
                        const year = e.tgl ? ` (${e.tgl.slice(0, 4)})` : (e.thn ? ` (${e.thn})` : '');
                        htmlPendidikan += `
                            <li class="mb-1">
                                <span class="fw-semibold text-dark">${e.tingkat || '-'} ${e.jurusan || ''}</span>
                                <div class="text-muted" style="font-size:0.75rem;">${e.sekolah || '-'}${year}</div>
                            </li>
                        `;
                    });
                    htmlPendidikan += '</ol>';

                    tbody += `
                        <tr>
                            <td class="text-center fw-bold text-primary fs-6">${idx + 1}</td>
                            <td>
                                <div class="fw-bold text-dark" style="font-size:0.85rem;"><i class="fas fa-map-marker-alt text-danger me-1"></i> ${wilayah}</div>
                                <div class="small text-secondary mt-1"><i class="fas fa-hospital-alt me-1 text-primary"></i> ${ukpd}</div>
                            </td>
                            <td>
                                <div class="d-flex align-items-center gap-2">
                                    <img src="${fotoSrc}" class="rounded-circle shadow-sm object-fit-cover flex-shrink-0" style="width: 42px; height: 42px; border: 2px solid #E2E8F0;" alt="Foto ${namaTanpaGelar}" onerror="this.onerror=null;this.src='https://ui-avatars.com/api/?name=${encodeURIComponent(namaTanpaGelar)}&background=6366F1&color=fff&bold=true&size=128';">
                                    <div>
                                        <div class="fw-bold text-dark fs-6">${namaTanpaGelar}</div>
                                        <div class="text-muted small" style="font-size:0.725rem;">(Gelar: ${p.nama || '-'})</div>
                                    </div>
                                </div>
                            </td>
                            <td>
                                <div class="fw-semibold text-dark" style="font-family: monospace; font-size:0.9rem;">
                                    ${p.nip || p.nik || '-'}
                                </div>
                                <div class="small text-muted" style="font-size:0.725rem;">
                                    ${p.nip ? 'NIP Resmi' : (p.nik ? 'NIK' : '-')}
                                </div>
                            </td>
                            <td>
                                <div class="fw-bold text-dark">${p.pangkat_gol || '-'}</div>
                                <span class="badge ${badgeClass} mt-1" style="font-size:0.7rem;">${p.status_pegawai || '-'}</span>
                                <div class="small text-muted mt-1"><i class="far fa-calendar-alt me-1"></i>TMT: ${p.tmt || '-'}</div>
                            </td>
                            <td>
                                ${htmlJabatan}
                            </td>
                            <td>
                                ${htmlPendidikan}
                            </td>
                        </tr>
                    `;
                });
            }

            $('#tbodyDUK').html(tbody);
        };

        window.exportDUKExcel = function() {
            let list = [...dataPegawai];
            list.sort((a, b) => getPangkatWeight(b.pangkat_gol) - getPangkatWeight(a.pangkat_gol));

            let csvContent = "data:text/csv;charset=utf-8,";
            csvContent += "No DUK,Wilayah,Nama UKPD,Nama Pegawai (Tanpa Gelar),Nama Lengkap,NIP/NIK,Pangkat/Gol (Terakhir),Status,Riwayat Jabatan (Urut Terbaru),Pendidikan Terakhir (Diakui SIASN),Riwayat Pendidikan (Urut Terbaru)\n";

            list.forEach((p, idx) => {
                const namaTanpaGelar = getNamaTanpaGelar(p.nama);
                const wilayah = "Sudin Kesehatan Kepulauan Seribu";
                const ukpd = p.tempat_tugas || "Puskesmas Kepulauan Seribu Utara";

                let rJabatan = [];
                if (p.riwayat_jabatan) {
                    try { rJabatan = typeof p.riwayat_jabatan === 'string' ? JSON.parse(p.riwayat_jabatan) : p.riwayat_jabatan; } catch(e){}
                }
                if (!Array.isArray(rJabatan) || rJabatan.length === 0) rJabatan = [{ jabatan: p.jabatan || '-', tmt: p.tmt || '-' }];
                rJabatan.sort((a, b) => new Date(b.tmt || '1900-01-01').getTime() - new Date(a.tmt || '1900-01-01').getTime());
                const strJabatan = rJabatan.map(j => `${j.jabatan} (TMT: ${j.tmt || '-'})`).join("; ");

                let rPendidikan = [];
                if (p.riwayat_pendidikan) {
                    try { rPendidikan = typeof p.riwayat_pendidikan === 'string' ? JSON.parse(p.riwayat_pendidikan) : p.riwayat_pendidikan; } catch(e){}
                }
                if (!Array.isArray(rPendidikan) || rPendidikan.length === 0) rPendidikan = [{ tingkat: p.pendidikan || '-', jurusan: '', sekolah: '' }];
                rPendidikan.sort((a, b) => new Date(b.tgl || b.thn || '1900').getTime() - new Date(a.tgl || a.thn || '1900').getTime());
                const strPendidikan = rPendidikan.map(e => `${e.tingkat} ${e.jurusan || ''} (${e.sekolah || '-'})`).join("; ");

                const topEdu = rPendidikan[0] || {};
                const eduSIASN = `${topEdu.tingkat || p.pendidikan || '-'} ${topEdu.jurusan || ''}`.trim();

                let row = [
                    idx + 1,
                    `"${wilayah}"`,
                    `"${ukpd}"`,
                    `"${namaTanpaGelar.replace(/"/g, '""')}"`,
                    `"${(p.nama || '').replace(/"/g, '""')}"`,
                    `"${(p.nip || p.nik || '').replace(/"/g, '""')}"`,
                    `"${(p.pangkat_gol || '').replace(/"/g, '""')}"`,
                    `"${(p.status_pegawai || '').replace(/"/g, '""')}"`,
                    `"${strJabatan.replace(/"/g, '""')}"`,
                    `"${eduSIASN.replace(/"/g, '""')}"`,
                    `"${strPendidikan.replace(/"/g, '""')}"`
                ];
                csvContent += row.join(",") + "\n";
            });

            let encodedUri = encodeURI(csvContent);
            let link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", `DUK_Pegawai_PKSU_${new Date().toISOString().slice(0,10)}.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            showToast("File DUK berhasil diexport!", "success");
        };

        // DISIPLIN PEGAWAI MODULE LOGIC
        window.updateJenisHukdisOptions = function() {
            const tingkat = $('#d_tingkat').val();
            let options = '';
            if (tingkat === 'Ringan') {
                options = `
                    <option value="Teguran Lisan">Teguran Lisan</option>
                    <option value="Teguran Tertulis">Teguran Tertulis</option>
                    <option value="Pernyataan Tidak Puas Secara Tertulis">Pernyataan Tidak Puas Secara Tertulis</option>
                `;
            } else if (tingkat === 'Sedang') {
                options = `
                    <option value="Penundaan Kenaikan Gaji Berkala (KGB) 1 Tahun">Penundaan Kenaikan Gaji Berkala (KGB) 1 Tahun</option>
                    <option value="Penundaan Kenaikan Pangkat 1 Tahun">Penundaan Kenaikan Pangkat 1 Tahun</option>
                    <option value="Penurunan Pangkat Setingkat Lebih Rendah 1 Tahun">Penurunan Pangkat Setingkat Lebih Rendah 1 Tahun</option>
                `;
            } else if (tingkat === 'Berat') {
                options = `
                    <option value="Penurunan Pangkat Setingkat Lebih Rendah 3 Tahun">Penurunan Pangkat Setingkat Lebih Rendah 3 Tahun</option>
                    <option value="Pembebasan dari Jabatan">Pembebasan dari Jabatan</option>
                    <option value="Pemberhentian Dengan Hormat Tidak Atas Permintaan Sendiri">Pemberhentian Dengan Hormat Tidak Atas Permintaan Sendiri</option>
                    <option value="Pemberhentian Tidak Dengan Hormat">Pemberhentian Tidak Dengan Hormat</option>
                `;
            }
            $('#d_jenis').html(options);
        };

        window.renderDisiplin = function() {
            let totalRekam = 0;
            let totalRingan = 0;
            let totalSedang = 0;
            let totalBerat = 0;

            const searchQuery = ($('#searchDisiplin').val() || '').toLowerCase().trim();
            const tingkatFilter = $('#filterDisiplinTingkat').val() || 'ALL';
            const statusFilter = $('#filterDisiplinStatus').val() || 'ALL';
            const tugasFilter = $('#filterDisiplinTugas').val() || '';

            let entries = [];

            dataPegawai.forEach((p, pIdx) => {
                let rDisiplin = [];
                if (p.riwayat_disiplin) {
                    try {
                        rDisiplin = typeof p.riwayat_disiplin === 'string' ? JSON.parse(p.riwayat_disiplin) : p.riwayat_disiplin;
                    } catch(e) { rDisiplin = []; }
                }

                if (Array.isArray(rDisiplin) && rDisiplin.length > 0) {
                    rDisiplin.forEach((d, dIdx) => {
                        const tingkat = d.tingkat || 'Ringan';
                        if (tingkat === 'Ringan') totalRingan++;
                        else if (tingkat === 'Sedang') totalSedang++;
                        else if (tingkat === 'Berat') totalBerat++;
                        totalRekam++;

                        entries.push({
                            pegawaiIdx: pIdx,
                            disiplinIdx: dIdx,
                            pegawai: p,
                            disiplin: d
                        });
                    });
                }
            });

            $('#disiplin-stat-total').text(totalRekam);
            $('#disiplin-stat-ringan').text(totalRingan);
            $('#disiplin-stat-sedang').text(totalSedang);
            $('#disiplin-stat-berat').text(totalBerat);

            let filtered = entries.filter(item => {
                const p = item.pegawai;
                const d = item.disiplin;

                if (tingkatFilter !== 'ALL' && d.tingkat !== tingkatFilter) return false;
                if (statusFilter !== 'ALL') {
                    const st = d.status || 'Aktif';
                    if (statusFilter === 'Aktif' && st !== 'Aktif') return false;
                    if (statusFilter === 'Selesai' && st !== 'Selesai') return false;
                }
                if (tugasFilter && (p.tempat_tugas || '') !== tugasFilter) return false;

                if (searchQuery) {
                    const matchNama = (p.nama || '').toLowerCase().includes(searchQuery);
                    const matchNip = (p.nip || p.nik || '').toLowerCase().includes(searchQuery);
                    const matchSK = (d.no_sk || '').toLowerCase().includes(searchQuery);
                    const matchJenis = (d.jenis || '').toLowerCase().includes(searchQuery);
                    const matchPelanggaran = (d.pelanggaran || '').toLowerCase().includes(searchQuery);
                    return matchNama || matchNip || matchSK || matchJenis || matchPelanggaran;
                }
                return true;
            });

            filtered.sort((a, b) => new Date(b.disiplin.tmt_mulai || '1900-01-01').getTime() - new Date(a.disiplin.tmt_mulai || '1900-01-01').getTime());

            let tbody = '';
            if (filtered.length === 0) {
                tbody = `<tr><td colspan="7" class="text-center py-4 text-muted">Belum ada rekam catatan disiplin pegawai yang sesuai filter.</td></tr>`;
            } else {
                filtered.forEach((item, idx) => {
                    const p = item.pegawai;
                    const d = item.disiplin;
                    const namaTanpaGelar = getNamaTanpaGelar(p.nama);
                    const fotoSrc = p.foto && p.foto.trim() !== '' ? p.foto : `https://ui-avatars.com/api/?name=${encodeURIComponent(namaTanpaGelar)}&background=6366F1&color=fff&bold=true&size=128`;

                    let badgeTingkat = 'bg-info text-dark';
                    if (d.tingkat === 'Sedang') badgeTingkat = 'bg-warning text-dark';
                    else if (d.tingkat === 'Berat') badgeTingkat = 'bg-danger text-white';

                    let badgeStatus = (d.status === 'Selesai') ? '<span class="badge bg-success-subtle text-success border border-success"><i class="fas fa-check-circle me-1"></i>Selesai</span>' : '<span class="badge bg-danger-subtle text-danger border border-danger"><i class="fas fa-clock me-1"></i>Masa Hukdis</span>';

                    tbody += `
                        <tr>
                            <td class="text-center fw-bold text-secondary">${idx + 1}</td>
                            <td>
                                <div class="d-flex align-items-center gap-2">
                                    <img src="${fotoSrc}" class="rounded-circle shadow-sm object-fit-cover flex-shrink-0" style="width: 38px; height: 38px; border: 2px solid #E2E8F0;" alt="${namaTanpaGelar}" onerror="this.onerror=null;this.src='https://ui-avatars.com/api/?name=${encodeURIComponent(namaTanpaGelar)}&background=6366F1&color=fff&bold=true&size=128';">
                                    <div>
                                        <div class="fw-bold text-dark" style="font-size:0.85rem;">${namaTanpaGelar}</div>
                                        <div class="small text-muted" style="font-size:0.75rem;">${p.nip ? 'NIP: ' + p.nip : (p.nik ? 'NIK: ' + p.nik : '-')}</div>
                                        <div class="small text-secondary" style="font-size:0.7rem;">${p.jabatan || '-'} (${p.tempat_tugas || '-'})</div>
                                    </div>
                                </div>
                            </td>
                            <td>
                                <div><span class="badge ${badgeTingkat} mb-1" style="font-size:0.7rem;">Tingkat ${d.tingkat || 'Ringan'}</span></div>
                                <div class="fw-bold text-dark" style="font-size:0.8rem;">${d.jenis || '-'}</div>
                            </td>
                            <td>
                                <div class="text-dark fw-semibold mb-1" style="font-size:0.8rem;">${d.pelanggaran || '-'}</div>
                                <div class="small text-muted" style="font-size:0.725rem;"><i class="fas fa-file-signature text-primary me-1"></i><strong>SK:</strong> ${d.no_sk || '-'} (${d.tgl_sk || '-'})</div>
                                <div class="small text-muted" style="font-size:0.7rem;"><i class="fas fa-user-tie me-1"></i>Pejabat: ${d.pejabat || '-'}</div>
                            </td>
                            <td>
                                <div class="small fw-bold text-dark"><i class="far fa-calendar-alt text-primary me-1"></i>TMT Mulai: ${d.tmt_mulai || '-'}</div>
                                <div class="small text-muted"><i class="far fa-calendar-check me-1"></i>TMT Selesai: ${d.tmt_selesai || '-'}</div>
                            </td>
                            <td>
                                ${badgeStatus}
                                ${d.keterangan ? `<div class="small text-muted mt-1" style="font-size:0.675rem;">${d.keterangan}</div>` : ''}
                            </td>
                            <td class="text-center">
                                <div class="btn-group btn-group-sm">
                                    <button type="button" class="btn btn-light text-primary border btn-admin-only" onclick="window.editDisiplin(${item.pegawaiIdx}, ${item.disiplinIdx})" title="Edit Catatan"><i class="fas fa-edit"></i></button>
                                    <button type="button" class="btn btn-light text-danger border btn-admin-only" onclick="window.deleteDisiplin(${item.pegawaiIdx}, ${item.disiplinIdx})" title="Hapus"><i class="fas fa-trash-alt"></i></button>
                                </div>
                            </td>
                        </tr>
                    `;
                });
            }

            $('#tbodyDisiplin').html(tbody);
        };

        window.openModalTambahDisiplin = function(pegawaiIdx) {
            let options = '<option value="">-- Pilih Pegawai --</option>';
            dataPegawai.forEach((p, idx) => {
                const namaTanpaGelar = getNamaTanpaGelar(p.nama);
                options += `<option value="${idx}">${namaTanpaGelar} (${p.nip || p.nik || '-'}) - ${p.jabatan || ''}</option>`;
            });
            $('#d_pegawai_select').html(options);

            $('#disiplin_pegawai_idx').val(pegawaiIdx !== undefined ? pegawaiIdx : '');
            $('#disiplin_item_idx').val('-1');
            $('#modalDisiplinTitle').html('<i class="fas fa-balance-scale me-2"></i> Tambah Catatan Disiplin Pegawai');

            if (pegawaiIdx !== undefined) {
                $('#d_pegawai_select').val(pegawaiIdx);
            } else {
                $('#d_pegawai_select').val('');
            }

            $('#d_tingkat').val('Ringan');
            window.updateJenisHukdisOptions();
            $('#d_pelanggaran').val('');
            $('#d_no_sk').val('');
            $('#d_tgl_sk').val(new Date().toISOString().slice(0, 10));
            $('#d_pejabat').val('Kepala Puskesmas Kepulauan Seribu Utara');
            $('#d_tmt_mulai').val(new Date().toISOString().slice(0, 10));
            $('#d_tmt_selesai').val('');
            $('#d_status').val('Aktif');
            $('#d_keterangan').val('');

            let modal = new bootstrap.Modal(document.getElementById('modalDisiplin'));
            modal.show();
        };

        window.editDisiplin = function(pegawaiIdx, disiplinIdx) {
            const p = dataPegawai[pegawaiIdx];
            if (!p) return;

            let rDisiplin = [];
            if (p.riwayat_disiplin) {
                try { rDisiplin = typeof p.riwayat_disiplin === 'string' ? JSON.parse(p.riwayat_disiplin) : p.riwayat_disiplin; } catch(e){}
            }
            const d = rDisiplin[disiplinIdx];
            if (!d) return;

            let options = '<option value="">-- Pilih Pegawai --</option>';
            dataPegawai.forEach((pg, idx) => {
                const namaTanpaGelar = getNamaTanpaGelar(pg.nama);
                options += `<option value="${idx}">${namaTanpaGelar} (${pg.nip || pg.nik || '-'}) - ${pg.jabatan || ''}</option>`;
            });
            $('#d_pegawai_select').html(options);

            $('#disiplin_pegawai_idx').val(pegawaiIdx);
            $('#disiplin_item_idx').val(disiplinIdx);
            $('#d_pegawai_select').val(pegawaiIdx);
            $('#modalDisiplinTitle').html('<i class="fas fa-edit me-2"></i> Edit Catatan Disiplin Pegawai');

            $('#d_tingkat').val(d.tingkat || 'Ringan');
            window.updateJenisHukdisOptions();
            $('#d_jenis').val(d.jenis || '');
            $('#d_pelanggaran').val(d.pelanggaran || '');
            $('#d_no_sk').val(d.no_sk || '');
            $('#d_tgl_sk').val(d.tgl_sk || '');
            $('#d_pejabat').val(d.pejabat || 'Kepala Puskesmas Kepulauan Seribu Utara');
            $('#d_tmt_mulai').val(d.tmt_mulai || '');
            $('#d_tmt_selesai').val(d.tmt_selesai || '');
            $('#d_status').val(d.status || 'Aktif');
            $('#d_keterangan').val(d.keterangan || '');

            let modal = new bootstrap.Modal(document.getElementById('modalDisiplin'));
            modal.show();
        };

        window.deleteDisiplin = function(pegawaiIdx, disiplinIdx) {
            if (!confirm("Apakah Anda yakin ingin menghapus rekam catatan disiplin ini?")) return;
            const p = dataPegawai[pegawaiIdx];
            if (!p) return;

            let rDisiplin = [];
            if (p.riwayat_disiplin) {
                try { rDisiplin = typeof p.riwayat_disiplin === 'string' ? JSON.parse(p.riwayat_disiplin) : p.riwayat_disiplin; } catch(e){}
            }
            rDisiplin.splice(disiplinIdx, 1);
            p.riwayat_disiplin = JSON.stringify(rDisiplin);

            window.renderDisiplin();
            showToast("Catatan disiplin berhasil dihapus.");
        };

        window.saveDisiplin = function(e) {
            e.preventDefault();
            const pIdx = $('#d_pegawai_select').val();
            if (pIdx === '' || pIdx === null) {
                showToast("Silakan pilih pegawai terlebih dahulu.", "danger");
                return;
            }

            const p = dataPegawai[pIdx];
            if (!p) return;

            let rDisiplin = [];
            if (p.riwayat_disiplin) {
                try { rDisiplin = typeof p.riwayat_disiplin === 'string' ? JSON.parse(p.riwayat_disiplin) : p.riwayat_disiplin; } catch(e){}
            }

            const itemIdx = parseInt($('#disiplin_item_idx').val());
            const record = {
                tingkat: $('#d_tingkat').val(),
                jenis: $('#d_jenis').val(),
                pelanggaran: $('#d_pelanggaran').val(),
                no_sk: $('#d_no_sk').val(),
                tgl_sk: $('#d_tgl_sk').val(),
                pejabat: $('#d_pejabat').val(),
                tmt_mulai: $('#d_tmt_mulai').val(),
                tmt_selesai: $('#d_tmt_selesai').val(),
                status: $('#d_status').val(),
                keterangan: $('#d_keterangan').val()
            };

            if (itemIdx >= 0 && itemIdx < rDisiplin.length) {
                rDisiplin[itemIdx] = record;
            } else {
                rDisiplin.push(record);
            }

            p.riwayat_disiplin = JSON.stringify(rDisiplin);

            const modalEl = document.getElementById('modalDisiplin');
            const modal = bootstrap.Modal.getInstance(modalEl);
            if (modal) modal.hide();

            window.renderDisiplin();
            showToast("Data catatan disiplin pegawai berhasil disimpan!");
        };

        window.exportDisiplinExcel = function() {
            let csvContent = "data:text/csv;charset=utf-8,";
            csvContent += "No,Nama Pegawai (Tanpa Gelar),NIP/NIK,Jabatan,Unit Kerja,Tingkat Hukdis,Jenis Hukdis,Bentuk Pelanggaran,Nomor SK,Tanggal SK,Pejabat SK,TMT Mulai,TMT Selesai,Status,Keterangan\n";

            let count = 0;
            dataPegawai.forEach((p) => {
                let rDisiplin = [];
                if (p.riwayat_disiplin) {
                    try { rDisiplin = typeof p.riwayat_disiplin === 'string' ? JSON.parse(p.riwayat_disiplin) : p.riwayat_disiplin; } catch(e){}
                }

                if (Array.isArray(rDisiplin) && rDisiplin.length > 0) {
                    rDisiplin.forEach((d) => {
                        count++;
                        const namaTanpaGelar = getNamaTanpaGelar(p.nama);
                        let row = [
                            count,
                            `"${namaTanpaGelar.replace(/"/g, '""')}"`,
                            `"${(p.nip || p.nik || '').replace(/"/g, '""')}"`,
                            `"${(p.jabatan || '').replace(/"/g, '""')}"`,
                            `"${(p.tempat_tugas || '').replace(/"/g, '""')}"`,
                            `"${(d.tingkat || '').replace(/"/g, '""')}"`,
                            `"${(d.jenis || '').replace(/"/g, '""')}"`,
                            `"${(d.pelanggaran || '').replace(/"/g, '""')}"`,
                            `"${(d.no_sk || '').replace(/"/g, '""')}"`,
                            `"${(d.tgl_sk || '').replace(/"/g, '""')}"`,
                            `"${(d.pejabat || '').replace(/"/g, '""')}"`,
                            `"${(d.tmt_mulai || '').replace(/"/g, '""')}"`,
                            `"${(d.tmt_selesai || '').replace(/"/g, '""')}"`,
                            `"${(d.status || '').replace(/"/g, '""')}"`,
                            `"${(d.keterangan || '').replace(/"/g, '""')}"`
                        ];
                        csvContent += row.join(",") + "\n";
                    });
                }
            });

            if (count === 0) {
                showToast("Tidak ada data catatan disiplin untuk diexport.", "warning");
                return;
            }

            let encodedUri = encodeURI(csvContent);
            let link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", `Disiplin_Pegawai_PKSU_${new Date().toISOString().slice(0,10)}.csv`);
            document.body.appendChild(link);
            link.click();
        };

