        window.downloadTemplatePegawaiExcel = function() {
            if (typeof XLSX === 'undefined') {
                showToast("Library SheetJS (XLSX) belum siap.", "danger");
                return;
            }
            const templateData = window.getTemplateSampleData();

            const worksheet = XLSX.utils.json_to_sheet(templateData);
            const workbook = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(workbook, worksheet, "Template Data Pegawai");

            const wscols = Object.keys(templateData[0]).map(key => ({ wch: Math.max(key.length + 4, 18) }));
            worksheet['!cols'] = wscols;

            XLSX.writeFile(workbook, "Template_Import_Pegawai_PKSU_Dengan_Contoh.xlsx");
            showToast("Template Excel dengan contoh data berhasil di-download!", "success");
        };

        window.downloadTemplatePegawaiExcelKosong = function() {
            if (typeof XLSX === 'undefined') {
                showToast("Library SheetJS (XLSX) belum siap.", "danger");
                return;
            }
            const headers = window.getTemplateHeaders();
            const emptyObj = {};
            headers.forEach(h => { emptyObj[h] = ''; });

            const worksheet = XLSX.utils.json_to_sheet([emptyObj]);
            const workbook = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(workbook, worksheet, "Template Kosong");

            const wscols = headers.map(key => ({ wch: Math.max(key.length + 4, 18) }));
            worksheet['!cols'] = wscols;

            XLSX.writeFile(workbook, "Template_Import_Pegawai_PKSU_Kosong.xlsx");
            showToast("Template Excel kosong berhasil di-download!", "success");
        };

        window.downloadTemplatePegawaiCSV = function() {
            const headers = window.getTemplateHeaders();
            const samples = window.getTemplateSampleData();

            let csv = headers.map(h => `"${h}"`).join(",") + "\n";
            samples.forEach(row => {
                let line = headers.map(h => {
                    let val = row[h] || '';
                    return `"${val.replace(/"/g, '""')}"`;
                }).join(",");
                csv += line + "\n";
            });

            let blob = new Blob(["\ufeff" + csv], { type: 'text/csv;charset=utf-8;' });
            let link = document.createElement("a");
            let url = URL.createObjectURL(blob);
            link.setAttribute("href", url);
            link.setAttribute("download", "Template_Import_Pegawai_PKSU.csv");
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            showToast("Template CSV berhasil di-download!", "success");
        };

        window.downloadTemplatePegawaiJSON = function() {
            const samples = window.getTemplateSampleData();
            let jsonStr = JSON.stringify(samples, null, 4);
            let blob = new Blob([jsonStr], { type: 'application/json' });
            let link = document.createElement("a");
            let url = URL.createObjectURL(blob);
            link.setAttribute("href", url);
            link.setAttribute("download", "Template_Import_Pegawai_PKSU.json");
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            showToast("Template JSON berhasil di-download!", "success");
        };

        window.normalizeHeaderKey = function(key) {
            if (!key) return '';
            let k = String(key).toLowerCase().trim().replace(/[^a-z0-9]/g, '');
            if (k.includes('nik')) return 'nik';
            if (k.includes('nip')) return 'nip';
            if (k.includes('nrk')) return 'nrk';
            if (k.includes('nama')) return 'nama';
            if (k.includes('jabatan')) return 'jabatan';
            if (k.includes('kategori')) return 'kategori';
            if (k.includes('rumpun')) return 'rumpun';
            if (k.includes('pangkat') || k.includes('gol')) return 'pangkat_gol';
            if (k.includes('kelamin') || k.includes('jk')) return 'jenis_kelamin';
            if (k.includes('agama')) return 'agama';
            if (k.includes('nikah') || k.includes('marit')) return 'status_nikah';
            if (k.includes('tempatlahir')) return 'tempat_lahir';
            if (k.includes('tanggallahir') || k.includes('tgllahir') || k.includes('dob')) return 'tanggal_lahir';
            if (k.includes('tugas') || k.includes('unit') || k.includes('pustu')) return 'tempat_tugas';
            if (k.includes('tmt')) return 'tmt';
            if (k.includes('str') && !k.includes('aktif')) return 'str';
            if (k.includes('aktifstr') || k.includes('expstr')) return 'aktif_str';
            if (k.includes('sip') && !k.includes('aktif')) return 'sip';
            if (k.includes('aktifsip') || k.includes('expsip')) return 'aktif_sip';
            if (k.includes('alamat')) return 'alamat';
            if (k.includes('hp') || k.includes('telepon') || k.includes('wa')) return 'no_hp';
            if (k.includes('email')) return 'email';
            if (k.includes('statuspeg') || k.includes('status')) return 'status_pegawai';
            if (k.includes('npwp')) return 'npwp';
            if (k.includes('pajak')) return 'status_pajak';
            if (k.includes('rekening') || k.includes('bank')) return 'rekening';
            if (k.includes('pendidikan') || k.includes('pend')) return 'pendidikan';
            return k;
        };

        window.handleFilePegawaiSelect = function(e) {
            const files = e.target.files || (e.dataTransfer && e.dataTransfer.files);
            if (!files || files.length === 0) return;
            const file = files[0];

            const reader = new FileReader();
            const fileName = file.name.toLowerCase();

            if (fileName.endsWith('.json')) {
                reader.onload = function(evt) {
                    try {
                        const json = JSON.parse(evt.target.result);
                        let arr = Array.isArray(json) ? json : (json.data || [json]);
                        window.processParsedRows(arr);
                    } catch(err) {
                        showToast("Format file JSON tidak valid!", "danger");
                    }
                };
                reader.readAsText(file);
            } else {
                reader.onload = function(evt) {
                    try {
                        const data = new Uint8Array(evt.target.result);
                        const workbook = XLSX.read(data, { type: 'array', cellDates: true });
                        const firstSheetName = workbook.SheetNames[0];
                        const worksheet = workbook.Sheets[firstSheetName];
                        const rawJson = XLSX.utils.sheet_to_json(worksheet, { defval: '' });
                        window.processParsedRows(rawJson);
                    } catch(err) {
                        showToast("Gagal membaca file Excel/CSV!", "danger");
                    }
                };
                reader.readAsArrayBuffer(file);
            }
        };

        window.processParsedRows = function(rawRows) {
            if (!Array.isArray(rawRows) || rawRows.length === 0) {
                showToast("File tidak berisi baris data pegawai.", "warning");
                return;
            }

            tempParsedPegawaiData = [];

            rawRows.forEach(row => {
                let p = {
                    nik: '', nip: '', nrk: '', nama: '', jabatan: '', kategori: 'Tenaga Kesehatan', rumpun: '03. Keperawatan',
                    pangkat_gol: 'III/a (Penata Muda)', jenis_kelamin: 'Laki-laki', agama: 'Islam', status_nikah: 'Kawin',
                    tempat_lahir: 'Jakarta', tanggal_lahir: '1990-01-01', tempat_tugas: 'Puskesmas Kepulauan Seribu Utara',
                    tmt: '2020-01-01', str: '', aktif_str: '', sip: '', aktif_sip: '', alamat: '', no_hp: '', email: '',
                    status_pegawai: 'PNS', npwp: '', status_pajak: 'TK0', rekening: 'Bank DKI - 1234567890', pendidikan: 'S1'
                };

                Object.keys(row).forEach(originalKey => {
                    let normKey = window.normalizeHeaderKey(originalKey);
                    let val = row[originalKey];
                    if (val !== undefined && val !== null) {
                        if (val instanceof Date) {
                            val = val.toISOString().slice(0, 10);
                        } else {
                            val = String(val).trim();
                        }
                    } else {
                        val = '';
                    }

                    if (normKey && val !== '') {
                        p[normKey] = val;
                    }
                });

                if (p.nama || p.nip || p.nik) {
                    tempParsedPegawaiData.push(p);
                }
            });

            if (tempParsedPegawaiData.length === 0) {
                showToast("Tidak ada data pegawai yang valid ditemukan di dalam file.", "warning");
                return;
            }

            let tbodyHtml = '';
            tempParsedPegawaiData.forEach((item, idx) => {
                const namaTanpaGelar = getNamaTanpaGelar(item.nama);
                tbodyHtml += `
                    <tr>
                        <td class="fw-bold text-secondary">${idx + 1}</td>
                        <td class="font-monospace small">${item.nik || '-'}</td>
                        <td class="font-monospace small">${item.nip || '-'}</td>
                        <td>${item.nrk || '-'}</td>
                        <td class="fw-bold text-dark">${namaTanpaGelar}</td>
                        <td>${item.jabatan || '-'}</td>
                        <td><span class="badge bg-primary-subtle text-primary border border-primary">${item.status_pegawai || 'PNS'}</span></td>
                        <td>${item.tempat_tugas || '-'}</td>
                        <td>${item.pangkat_gol || '-'}</td>
                        <td>${item.no_hp || '-'}</td>
                    </tr>
                `;
            });

            $('#tbodyPreviewUpload').html(tbodyHtml);
            $('#uploadRecordCount').text(tempParsedPegawaiData.length);
            $('#lblJumlahImport').text(tempParsedPegawaiData.length);
            $('#btnProsesImport').prop('disabled', false);
            $('#previewUploadSection').slideDown();
            showToast(`Berhasil membaca ${tempParsedPegawaiData.length} data pegawai!`, "success");
        };

        window.prosesImportPegawai = function() {
            if (!tempParsedPegawaiData || tempParsedPegawaiData.length === 0) {
                showToast("Tidak ada data pegawai untuk di-import.", "warning");
                return;
            }

            const overwrite = $('#overwriteExistingPegawai').is(':checked');
            let insertedCount = 0;
            let updatedCount = 0;

            tempParsedPegawaiData.forEach(item => {
                const keyNip = item.nip ? item.nip.toString().trim() : '';
                const keyNik = item.nik ? item.nik.toString().trim() : '';

                let existingIdx = -1;
                if (keyNip || keyNik) {
                    existingIdx = dataPegawai.findIndex(p => 
                        (keyNip !== '' && p.nip === keyNip) || 
                        (keyNik !== '' && p.nik === keyNik)
                    );
                }

                if (existingIdx !== -1) {
                    if (overwrite) {
                        dataPegawai[existingIdx] = { ...dataPegawai[existingIdx], ...item };
                        updatedCount++;
                    }
                } else {
                    item.rowIndex = dataPegawai.length + 2;
                    dataPegawai.push(item);
                    insertedCount++;
                }
            });

            $('#btnProsesImport').html('<i class="fas fa-spinner fa-spin me-1"></i> Menyimpan...').prop('disabled', true);

            $.ajax({
                url: '/api/gas',
                type: 'POST',
                contentType: 'application/json',
                data: JSON.stringify({
                    action: 'bulkUploadPegawai',
                    data: tempParsedPegawaiData
                }),
                success: function(res) {
                    $('#btnProsesImport').html('<i class="fas fa-cloud-upload-alt me-1"></i> Import Selesai').prop('disabled', false);
                    let modalEl = document.getElementById('modalUploadPegawai');
                    let modal = bootstrap.Modal.getInstance(modalEl);
                    if (modal) modal.hide();

                    refreshAllData();
                    showToast(`Proses Import Berhasil! ${insertedCount} data baru ditambahkan, ${updatedCount} data diperbarui.`, "success");
                },
                error: function(err) {
                    $('#btnProsesImport').html('<i class="fas fa-cloud-upload-alt me-1"></i> Coba Lagi').prop('disabled', false);
                    refreshAllData();
                    showToast(`Data disimpan secara lokal (${insertedCount} baru, ${updatedCount} diperbarui).`, "info");
                }
            });
        };

        // MULTI-STEP TAMBAH PEGAWAI WIZARD LOGIC
        window.currentWizardStep = 1;
        window.wizardCompletedSteps = [false, false, false, false, false, false];
        window.wizardKeluargaList = [];
        window.wizardPendidikanList = [];
        window.wizardJabatanList = [];
        window.wizardGajiList = [];
        window.editingPegawaiIndex = -1;

        window.showSection = function(target) {
            if (!target) return;
            $('#sidebar ul li').removeClass('active');
            $(`#sidebar a[data-target="${target}"]`).parent().addClass('active');
            if (target.startsWith('master-') || target === 'master-jabatan') {
                $('#submenuMasterData').collapse('show');
            }
            if (target.startsWith('usulan-')) {
                $('#submenuUsulan').collapse('show');
            }
            if (target.startsWith('admin-')) {
                $('#submenuAdmin').collapse('show');
            }
            $('.mobile-bottom-nav ul li').removeClass('active');
            $(`.mobile-bottom-nav a[data-target="${target}"]`).parent().addClass('active');

            const titles = {
                'dashboard': 'Dashboard',
                'data-master': 'Data Pegawai',
                'master-jabatan': 'Jabatan Berdasarkan Menpan',
                'master-jabatan-menpan': 'Jabatan Berdasarkan Menpan',
                'master-jabatan-orb': 'Jabatan Berdasarkan ORB',
                'master-status-rumpun': 'Master Rumpun Jabatan',
                'master-pangkat-golongan': 'Master Pangkat / Golongan',
                'master-jenjang-pendidikan': 'Master Jenjang Pendidikan',
