                'usulan-kenaikan-pangkat': 'Usulan Kenaikan Pangkat',
                'usulan-kenaikan-jenjang': 'Usulan Kenaikan Jenjang',
                'tambah-pegawai': window.editingPegawaiIndex >= 0 ? 'Edit Data Pegawai' : 'Tambah Pegawai',
                'duk': 'Daftar Urut Kepangkatan (DUK)',
                'disiplin': 'Disiplin Pegawai & Hukdis',
                'gap-kompetensi': 'Gap Kompetensi Pegawai',
                'diklat': 'Modul Diklat',
                'uraian': 'Uraian Tugas',
                'dokumen': 'Arsip Dokumen',
                'gaji': 'Penggajian',
                'analitik': 'Analitik & Statistik',
                'laporan': 'Laporan & Export',
                'pengaturan': 'Pengaturan',
                'admin-list-pengguna': 'Admin - List Pengguna',
                'admin-tambah-pengguna': 'Admin - Tambah Pengguna',
                'admin-list-menu': 'Admin - List Menu',
                'admin-tambah-menu': 'Admin - Tambah Menu',
                'admin-list-page': 'Admin - List Page',
                'admin-tambah-page': 'Admin - Tambah Page',
                'admin-list-akses': 'Admin - List Akses',
                'admin-list-group': 'Admin - List Group',
                'admin-tambah-group': 'Admin - Tambah Group'
            };

            const animateSectionIn = function(secId) {
                $('.page-section').removeClass('section-active-fade active').hide();
                const $targetSec = $('#' + secId);
                if ($targetSec.length) {
                    $targetSec.show();
                    setTimeout(() => {
                        $targetSec.addClass('section-active-fade');
                    }, 10);
                }
            };

            if (target === 'master-jabatan' || target.startsWith('master-')) {
                animateSectionIn('master-jabatan');
                let masterType = 'menpan';
                if (target === 'master-jabatan-orb') masterType = 'orb';
                else if (target === 'master-status-rumpun') masterType = 'rumpun';
                else if (target === 'master-pangkat-golongan') masterType = 'pangkat';
                else if (target === 'master-jenjang-pendidikan') masterType = 'pendidikan';
                else if (target === 'master-unit-tugas') masterType = 'unit';

                if (typeof window.switchMasterType === 'function') {
                    window.switchMasterType(masterType);
                }
            } else if (target.startsWith('admin-')) {
                animateSectionIn('admin-section');

                if (target === 'admin-list-pengguna') window.switchAdminTab('pengguna');
                else if (target === 'admin-tambah-pengguna') { window.switchAdminTab('pengguna'); window.openModalAdminPengguna(); }
                else if (target === 'admin-list-menu') window.switchAdminTab('menu');
                else if (target === 'admin-tambah-menu') { window.switchAdminTab('menu'); window.openModalAdminMenu(); }
                else if (target === 'admin-list-page') window.switchAdminTab('page');
                else if (target === 'admin-tambah-page') { window.switchAdminTab('page'); window.openModalAdminPage(); }
                else if (target === 'admin-list-akses') window.switchAdminTab('akses');
                else if (target === 'admin-list-group') window.switchAdminTab('group');
                else if (target === 'admin-tambah-group') { window.switchAdminTab('group'); window.openModalAdminGroup(); }
            } else {
                animateSectionIn(target);
            }

            if (titles[target]) $('#page-title').text(titles[target]);
            if (target === 'duk') window.renderDUK();
            if (target === 'disiplin') window.renderDisiplin();
            if (target === 'data-master') window.renderTableMaster();
            if (target === 'usulan-tunjangan-keluarga') window.renderUsulanTunjangan();
            if (target === 'usulan-kenaikan-pangkat') window.renderUsulanPangkat();
            if (target === 'usulan-kenaikan-jenjang') window.renderUsulanJenjang();
            if (target === 'gap-kompetensi') window.renderGapKompetensi();
            if (target === 'uraian') window.renderUraian();
            if (target === 'dokumen') window.renderDokumen();
            window.scrollTo({ top: 0, behavior: 'smooth' });
        };

