        window.editForm = function(idx) {
            if (idx < 0 || idx >= dataPegawai.length) return;
            const p = dataPegawai[idx];
            window.editingPegawaiIndex = idx;
            window.currentWizardStep = 1;
            window.wizardCompletedSteps = [true, true, true, true, true, true];

            $('#w_nama').val(p.nama || '');
            $('#w_gelar_depan').val(p.gelar_depan || '');
            $('#w_gelar_belakang').val(p.gelar_belakang || '');
            $('#w_jk').val(p.jenis_kelamin || 'Perempuan');
            $('#w_tempat_lahir').val(p.tempat_lahir || '');
            $('#w_tgl_lahir').val(p.tanggal_lahir || '');
            $('#w_nik').val(p.nik || '');
            $('#w_agama').val(p.agama || 'Islam');

            $('#w_ukpd').val(p.tempat_tugas || p.nama_ukpd || 'Puskesmas Seribu Utara');
            $('#w_jenis_pegawai').val(p.status_pegawai || 'PNS');
            $('#w_jenis_kontrak').val(p.jenis_kontrak || '');
            $('#w_nrk').val(p.nrk || '');
            $('#w_nip').val(p.nip || '');
            $('#w_kondisi').val(p.kondisi || 'Aktif');
            $('#w_tmt_ukpd').val(p.tmt || '');

            $('#w_jabatan_pergub').val(p.jabatan_orb || p.jabatan_pergub || p.jabatan || '');
            $('#w_jabatan_kepmenpan').val(p.jabatan_permenpan11 || p.jabatan_kepmenpan11 || p.jabatan || '');
            $('#w_status_rumpun').val(p.status_rumpun || p.rumpun || '');
            $('#w_atasan').val(p.atasan || '');
            $('#w_pangkat_gol').val(p.pangkat_gol || '');
            $('#w_tmt_pangkat').val(p.tmt_pangkat || '');

            $('#w_jenjang').val(p.pendidikan || '');
            $('#w_prodi').val(p.prodi || '');
