            $('#w_dom_jalan').val(p.alamat || '');

            if (p.foto && p.foto.trim() !== '') {
                $('#w_foto').val(p.foto);
                $('#w_foto_preview').attr('src', p.foto).removeClass('d-none');
                $('#w_foto_icon').addClass('d-none');
            } else {
                $('#w_foto').val('');
                $('#w_foto_preview').attr('src', '').addClass('d-none');
                $('#w_foto_icon').removeClass('d-none');
            }

            try {
                window.wizardKeluargaList = p.keluarga ? (typeof p.keluarga === 'string' ? JSON.parse(p.keluarga) : p.keluarga) : [];
            } catch(e) { window.wizardKeluargaList = []; }

            try {
                window.wizardPendidikanList = p.pendidikan_history ? (typeof p.pendidikan_history === 'string' ? JSON.parse(p.pendidikan_history) : p.pendidikan_history) : [];
            } catch(e) { window.wizardPendidikanList = []; }

            try {
                window.wizardJabatanList = p.jabatan_history ? (typeof p.jabatan_history === 'string' ? JSON.parse(p.jabatan_history) : p.jabatan_history) : [];
            } catch(e) { window.wizardJabatanList = []; }

            try {
                window.wizardGajiList = p.gaji_history ? (typeof p.gaji_history === 'string' ? JSON.parse(p.gaji_history) : p.gaji_history) : [];
            } catch(e) { window.wizardGajiList = []; }

            window.renderWizardKeluarga();
            window.renderWizardPendidikan();
            window.renderWizardJabatan();
            window.renderWizardGaji();

            $('#wizard-error-banner').addClass('d-none');

            window.showSection('tambah-pegawai');
            window.goToWizardStep(1);
        };

        window.goToWizardStep = function(stepNum) {
            if (stepNum < 1 || stepNum > 6) return;
            window.currentWizardStep = stepNum;

            const stepNames = [
                'Identitas Pribadi',
                'Data Kepegawaian',
                'Jabatan & Pangkat',
                'Pendidikan & Kontak',
                'Alamat',
                'Riwayat Opsional'
            ];
            const stepPcts = ['17%', '33%', '50%', '67%', '83%', '100%'];
            const stepWidths = ['17%', '33%', '50%', '67%', '83%', '100%'];

            $('#wizard-step-title-count').text(`Step ${stepNum} dari 6`);
            $('#wizard-progress-pct').text(stepPcts[stepNum - 1]);
            $('#wizard-progress-name').text(stepNames[stepNum - 1]);
            $('#wizard-progress-bar').css('width', stepWidths[stepNum - 1]);

            for (let i = 1; i <= 6; i++) {
                const pill = $(`#step-pill-${i}`);
                const badge = $(`#step-badge-${i}`);

                pill.removeClass('active completed');
                if (i === stepNum) {
                    pill.addClass('active');
                    badge.html(i);
                } else if (window.wizardCompletedSteps[i - 1]) {
                    pill.addClass('completed');
                    badge.html('<i class="fas fa-check" style="font-size:0.7rem;"></i>');
                } else {
                    badge.html(i);
                }
            }

            $('.wizard-step-panel').addClass('d-none');
            $(`#wizard-step-panel-${stepNum}`).removeClass('d-none');

            if (stepNum === 1) {
                $('#btn-wizard-prev').addClass('d-none');
            } else {
                $('#btn-wizard-prev').removeClass('d-none');
            }

            if (stepNum === 6) {
                $('#btn-wizard-next').text('Simpan Pegawai').removeClass('btn-primary').addClass('btn-success');
                $('#btn-wizard-skip').removeClass('d-none');
            } else {
                $('#btn-wizard-next').html('Lanjut <i class="fas fa-arrow-right ms-1"></i>').removeClass('btn-success').addClass('btn-primary');
                $('#btn-wizard-skip').addClass('d-none');
            }

            $('#wizard-error-banner').addClass('d-none');
            window.scrollTo({ top: 0, behavior: 'smooth' });
        };

        window.validateWizardStep = function(stepNum) {
            let isValid = true;
            if (stepNum === 1) {
                if (!$('#w_nama').val().trim() || !$('#w_jk').val() || !$('#w_tempat_lahir').val().trim() || !$('#w_tgl_lahir').val() || !$('#w_agama').val()) {
                    isValid = false;
                }
            } else if (stepNum === 2) {
                if (!$('#w_ukpd').val() || !$('#w_jenis_pegawai').val() || !$('#w_kondisi').val()) {
                    isValid = false;
                }
            } else if (stepNum === 3) {
                if (!$('#w_jabatan_pergub').val().trim() || !$('#w_jabatan_kepmenpan').val().trim() || !$('#w_status_rumpun').val().trim()) {
                    isValid = false;
                }
            }
            return isValid;
        };

        window.wizardNextStep = function() {
            if (!window.validateWizardStep(window.currentWizardStep)) {
                $('#wizard-error-banner').removeClass('d-none');
                window.scrollTo({ top: 100, behavior: 'smooth' });
                return;
            }

            $('#wizard-error-banner').addClass('d-none');
            window.wizardCompletedSteps[window.currentWizardStep - 1] = true;

            if (window.currentWizardStep < 6) {
                window.goToWizardStep(window.currentWizardStep + 1);
            } else {
                window.submitWizardPegawai();
            }
        };

        window.wizardPrevStep = function() {
            if (window.currentWizardStep > 1) {
                window.goToWizardStep(window.currentWizardStep - 1);
            }
        };

