                timestamp: new Date().toLocaleString('id-ID')
            };

            localStorage.setItem('simpeg_tambah_draft', JSON.stringify(draft));
            $('#wizard-draft-status').html(`<span class="text-success"><i class="fas fa-check-circle me-1"></i>Draft tersimpan otomatis: ${draft.timestamp}</span>`);
            showToast("Draft berhasil disimpan ke penyimpanan lokal!", "success");
        };

        window.loadWizardDraft = function() {
            try {
                const saved = localStorage.getItem('simpeg_tambah_draft');
                if (saved) {
                    const draft = JSON.parse(saved);
                    Object.keys(draft).forEach(key => {
                        if (key !== 'timestamp' && $('#' + key).length) {
                            $('#' + key).val(draft[key]);
                        }
                    });
                    if (draft.w_foto) {
                        $('#w_foto_preview').attr('src', draft.w_foto).removeClass('d-none');
                        $('#w_foto_icon').addClass('d-none');
                    }
                    if (draft.timestamp) {
                        $('#wizard-draft-status').html(`<span class="text-muted">Draft tersimpan otomatis: ${draft.timestamp}</span>`);
                    }
                }
            } catch(e){}
        };

        window.cancelWizard = function() {
            window.editingPegawaiIndex = -1;
            window.showSection('data-master');
        };

        window.handleWizardFotoUpload = function(input) {
            if (input.files && input.files[0]) {
                const file = input.files[0];
                if (file.size > 200 * 1024) {
                    showToast("Ukuran foto maksimal 200 KB. Silakan pilih foto dengan ukuran lebih kecil.", "warning");
                }
                const reader = new FileReader();
                reader.onload = function(e) {
                    $('#w_foto').val(e.target.result);
                    $('#w_foto_preview').attr('src', e.target.result).removeClass('d-none');
                    $('#w_foto_icon').addClass('d-none');
                };
                reader.readAsDataURL(file);
            }
        };

        window.addWizardKeluargaRow = function() {
            const nama = prompt("Nama Anggota Keluarga:");
            if (!nama) return;
            const relasi = prompt("Hubungan Keluarga (Suami/Istri/Anak):") || 'Anak';
            window.wizardKeluargaList.push({ nama: nama, hubungan: relasi, ttl: '', nohp: '' });
            window.renderWizardKeluarga();
        };

        window.renderWizardKeluarga = function() {
            $('#badge-count-keluarga').text(`${window.wizardKeluargaList.length} entri`);
            if (window.wizardKeluargaList.length === 0) {
                $('#wizardKeluargaRows').html('<p class="text-muted small italic text-center py-2 mb-0">Belum ada data anggota keluarga ditambahkan.</p>');
                return;
            }
            let html = '';
            window.wizardKeluargaList.forEach((item, idx) => {
                html += `<div class="d-flex justify-content-between align-items-center bg-white p-2 px-3 border rounded-3 small">
                    <div><strong>${item.nama}</strong> <span class="badge bg-primary-subtle text-primary border border-primary ms-2">${item.hubungan}</span></div>
                    <button type="button" class="btn btn-sm btn-light text-danger py-0 px-2" onclick="window.removeWizardKeluarga(${idx})"><i class="fas fa-times"></i></button>
                </div>`;
            });
            $('#wizardKeluargaRows').html(html);
        };

        window.removeWizardKeluarga = function(idx) {
            window.wizardKeluargaList.splice(idx, 1);
            window.renderWizardKeluarga();
        };

        window.addWizardPendidikanRow = function() {
            const jenjang = prompt("Jenjang Pendidikan (e.g. S1 / D3 / SMA):");
            if (!jenjang) return;
            const inst = prompt("Nama Sekolah / Universitas:") || '-';
            window.wizardPendidikanList.push({ jenjang: jenjang, institusi: inst });
            window.renderWizardPendidikan();
        };

        window.renderWizardPendidikan = function() {
            $('#badge-count-pendidikan').text(`${window.wizardPendidikanList.length} entri`);
            if (window.wizardPendidikanList.length === 0) {
                $('#wizardPendidikanRows').html('<p class="text-muted small italic text-center py-2 mb-0">Belum ada riwayat pendidikan ditambahkan.</p>');
                return;
            }
            let html = '';
            window.wizardPendidikanList.forEach((item, idx) => {
                html += `<div class="d-flex justify-content-between align-items-center bg-white p-2 px-3 border rounded-3 small">
                    <div><strong>${item.jenjang}</strong> - ${item.institusi}</div>
                    <button type="button" class="btn btn-sm btn-light text-danger py-0 px-2" onclick="window.removeWizardPendidikan(${idx})"><i class="fas fa-times"></i></button>
                </div>`;
            });
            $('#wizardPendidikanRows').html(html);
        };

        window.removeWizardPendidikan = function(idx) {
            window.wizardPendidikanList.splice(idx, 1);
            window.renderWizardPendidikan();
        };

        window.addWizardJabatanRow = function() {
