        window.submitWizardPegawai = function() {
            const gelarD = $('#w_gelar_depan').val().trim();
            const gelarB = $('#w_gelar_belakang').val().trim();
            const namaCore = $('#w_nama').val().trim();
            let fullName = namaCore;
            if (gelarD && !fullName.startsWith(gelarD)) fullName = `${gelarD} ${fullName}`;
            if (gelarB && !fullName.endsWith(gelarB)) fullName = `${fullName}, ${gelarB}`;

            const payloadData = {
                nama: fullName || 'Pegawai',
                nik: $('#w_nik').val().trim(),
                nip: $('#w_nip').val().trim(),
                nrk: $('#w_nrk').val().trim(),
                jenis_kelamin: $('#w_jk').val(),
                tempat_lahir: $('#w_tempat_lahir').val().trim(),
                tanggal_lahir: $('#w_tgl_lahir').val(),
                agama: $('#w_agama').val(),
                status_pegawai: $('#w_jenis_pegawai').val() || 'PNS',
                tempat_tugas: $('#w_ukpd').val() || 'Puskesmas Seribu Utara',
                nama_ukpd: $('#w_ukpd').val() || 'Puskesmas Seribu Utara',
                jabatan: $('#w_jabatan_pergub').val().trim() || 'Pegawai',
                jabatan_orb: $('#w_jabatan_pergub').val().trim(),
                jabatan_pergub: $('#w_jabatan_pergub').val().trim(),
                jabatan_permenpan11: $('#w_jabatan_kepmenpan').val().trim(),
                jabatan_kepmenpan11: $('#w_jabatan_kepmenpan').val().trim(),
                status_rumpun: $('#w_status_rumpun').val().trim(),
                pangkat_gol: $('#w_pangkat_gol').val().trim() || 'NON PNS',
                tmt: $('#w_tmt_ukpd').val() || new Date().toISOString().slice(0, 10),
                no_hp: $('#w_nohp').val().trim(),
                email: $('#w_email').val().trim(),
                bpjs: $('#w_bpjs').val().trim(),
                status_nikah: $('#w_status_nikah').val(),
                alamat: $('#w_dom_jalan').val().trim() || $('#w_ktp_jalan').val().trim(),
                foto: $('#w_foto').val(),
                keluarga: JSON.stringify(window.wizardKeluargaList),
                pendidikan_history: JSON.stringify(window.wizardPendidikanList),
                jabatan_history: JSON.stringify(window.wizardJabatanList),
                gaji_history: JSON.stringify(window.wizardGajiList)
            };

            const isEdit = window.editingPegawaiIndex >= 0;

            if (isEdit) {
                payloadData.rowIndex = dataPegawai[window.editingPegawaiIndex].rowIndex || (window.editingPegawaiIndex + 2);
                dataPegawai[window.editingPegawaiIndex] = { ...dataPegawai[window.editingPegawaiIndex], ...payloadData };
            } else {
                payloadData.rowIndex = dataPegawai.length + 2;
                dataPegawai.push(payloadData);
            }

            $.ajax({
                url: '/api/gas',
                type: 'POST',
                contentType: 'application/json',
                data: JSON.stringify({
                    action: isEdit ? 'editPegawai' : 'simpanPegawai',
                    data: payloadData
                }),
                success: function(res) {
                    localStorage.removeItem('simpeg_tambah_draft');
                    window.editingPegawaiIndex = -1;
                    refreshAllData();
                    showToast(isEdit ? "Data Pegawai berhasil diperbarui!" : "Data Pegawai berhasil ditambahkan!", "success");
                    window.cancelWizard();
                },
                error: function(err) {
                    localStorage.removeItem('simpeg_tambah_draft');
                    window.editingPegawaiIndex = -1;
                    refreshAllData();
                    showToast(isEdit ? "Data Pegawai diperbarui secara lokal." : "Data Pegawai disimpan secara lokal.", "info");
                    window.cancelWizard();
                }
            });
        };

        // MASTER DATA LOGIC (MENPAN, ORB, STATUS RUMPUN, PANGKAT/GOLONGAN, JENJANG PENDIDIKAN, UNIT TUGAS)
        window.currentMasterType = 'menpan'; // 'menpan', 'orb', 'rumpun', 'pangkat', 'pendidikan', 'unit'
        window.currentJabatanType = 'menpan'; // Alias for compatibility
        window.masterJabatanMenpanList = [];
        window.masterJabatanOrbList = [];
        window.masterStatusRumpunList = [];
        window.masterPangkatGolonganList = [];
        window.masterJenjangPendidikanList = [];
        window.masterUnitTugasList = [];
        window.currentJabatanPage = 1;
        window.jabatanPageSize = 100;
        window.filteredJabatanList = [];

