            }

            // Load ORB
            const savedOrb = localStorage.getItem('simpeg_master_jabatan_orb');
            if (savedOrb) {
                try { window.masterJabatanOrbList = JSON.parse(savedOrb); } catch(e) { window.masterJabatanOrbList = []; }
            }
            if (!window.masterJabatanOrbList || window.masterJabatanOrbList.length === 0) {
                const seedOrb = [
                    "Kepala Dinas Kesehatan", "Kepala Puskesmas", "Kepala Sub Bagian Tata Usaha",
                    "Kasatpel Pelayanan Medis dan Keperawatan", "Kasatpel UKM dan UKP",
                    "Kepala Bagian Adminstrasi Umum dan Keuangan", "Kepala Bagian Data, Informasi dan Organisasi",
                    "Kepala Bagian Keuangan dan Perencanaan", "Kepala Bagian SDM, Pendidikan dan Pelatihan",
                    "Kepala Bidang Keuangan", "Kepala Bidang Pelayanan Kesehatan", "Kepala Bidang Pelayanan Medis dan Keperawatan",
                    "Kepala Bidang Penunjang", "Kepala Bidang Sumber Daya Kesehatan",
                    "Kepala Seksi Kesehatan Masyarakat", "Kepala Seksi Pencegahan dan Pengendalian Penyakit",
                    "Kepala Seksi Pelayanan Kesehatan", "Kepala Seksi Sumber Daya Manusia Kesehatan",
                    "Koordinator Satuan Pelayanan", "Direktur RSUD", "Wadir Pelayanan Medis",
                    "Operator Layanan Operasional", "Pasukan Putih", "Pengadministrasi Keuangan", "Pengadministrasi Perkantoran", "Pengadministrasi Umum",
                    "Pengelola Data", "Pengelola Keuangan", "Pengelola Teknis Informasi", "Pengawas Kesehatan",
                    "Petugas Keamanan", "Petugas Kebersihan", "Petugas Laboratorium", "PSM Kesejahteraan", "Sekretaris", "Tenaga Bantuan Lingkungan", "Verifikator Keuangan"
                ];
                window.masterJabatanOrbList = seedOrb.map((nama, idx) => ({
                    id: idx + 1, nama: nama, status: 'Aktif', updated_at: '18/6/2024, 07:00:00'
                }));
            }

            // Load Rumpun Jabatan
            const savedRumpun = localStorage.getItem('simpeg_master_rumpun_jabatan') || localStorage.getItem('simpeg_master_status_rumpun');
            if (savedRumpun) {
                try { window.masterStatusRumpunList = JSON.parse(savedRumpun); } catch(e) { window.masterStatusRumpunList = []; }
            }
            const seedRumpun = [
                "Jabatan Administrator",
                "Jabatan Pengawas",
                "Jabatan Fungsional Keahlian Kesehatan",
                "Jabatan Fungsional Keterampilan Kesehatan",
                "Jabatan Teknis Tingkat Ahli",
                "Jabatan Teknis Tingkat Terampil",
                "Jabatan Administrasi Tingkat Terampil",
                "Jabatan Operasional Tingkat Terampil"
            ];
            const isLegacyRumpun = window.masterStatusRumpunList && window.masterStatusRumpunList.some(item => item.nama && (item.nama.includes('Tenaga Kesehatan') || item.nama.includes('Non Tenaga') || item.nama.includes('Penunjang / Operasional')));
            if (!window.masterStatusRumpunList || window.masterStatusRumpunList.length === 0 || isLegacyRumpun) {
                window.masterStatusRumpunList = seedRumpun.map((nama, idx) => ({
                    id: idx + 1, nama: nama, status: 'Aktif', updated_at: '03/08/2026, 00:00:00'
                }));
                try {
                    localStorage.setItem('simpeg_master_status_rumpun', JSON.stringify(window.masterStatusRumpunList));
                    localStorage.setItem('simpeg_master_rumpun_jabatan', JSON.stringify(window.masterStatusRumpunList));
                } catch(e) {}
            }

            // Load Pangkat / Golongan
            const savedPangkat = localStorage.getItem('simpeg_master_pangkat_golongan');
            if (savedPangkat) {
                try { window.masterPangkatGolonganList = JSON.parse(savedPangkat); } catch(e) { window.masterPangkatGolonganList = []; }
            }
            if (!window.masterPangkatGolonganList || window.masterPangkatGolonganList.length === 0) {
                const seedPangkat = [
                    "I/a - Juru Muda", "I/b - Juru Muda Tk. I", "I/c - Juru", "I/d - Juru Tk. I",
                    "II/a - Pengatur Muda", "II/b - Pengatur Muda Tk. I", "II/c - Pengatur", "II/d - Pengatur Tk. I",
                    "III/a - Penata Muda", "III/b - Penata Muda Tk. I", "III/c - Penata", "III/d - Penata Tk. I",
                    "IV/a - Pembina", "IV/b - Pembina Tk. I", "IV/c - Pembina Utama Muda", "IV/d - Pembina Utama Madya", "IV/e - Pembina Utama",
                    "IX - PPPK", "Non-PNS / PTT / PJLP"
                ];
                window.masterPangkatGolonganList = seedPangkat.map((nama, idx) => ({
                    id: idx + 1, nama: nama, status: 'Aktif', updated_at: '18/6/2024, 07:00:00'
                }));
            }

            // Load Jenjang Pendidikan
            const savedPendidikan = localStorage.getItem('simpeg_master_jenjang_pendidikan');
            if (savedPendidikan) {
                try { window.masterJenjangPendidikanList = JSON.parse(savedPendidikan); } catch(e) { window.masterJenjangPendidikanList = []; }
            }
            if (!window.masterJenjangPendidikanList || window.masterJenjangPendidikanList.length === 0) {
                const seedPendidikan = [
                    "SD / Sederajat", "SMP / Sederajat", "SMA / SMK / Sederajat",
                    "D1 (Diploma I)", "D2 (Diploma II)", "D3 (Diploma III)",
                    "D4 / S1 (Sarjana / Diploma IV)", "Profesi (Dokter / Apoteker / Ners)",
                    "S2 (Magister / Spesialis)", "S3 (Doktor / Sub-Spesialis)"
                ];
                window.masterJenjangPendidikanList = seedPendidikan.map((nama, idx) => ({
                    id: idx + 1, nama: nama, status: 'Aktif', updated_at: '18/6/2024, 07:00:00'
                }));
            }

            // Load Unit Tugas (strictly only 5 official units)
            const seedUnit = [
                "Puskesmas Seribu Utara",
                "Puskesmas Pembantu Pulau Panggang",
                "Puskesmas Pembantu Pulau Harapan",
                "POSKES Pulau Sabira",
                "PUSLING Pulau Pramuka"
            ];

            const savedUnit = localStorage.getItem('simpeg_master_unit_tugas');
            let loadedUnits = [];
            if (savedUnit) {
                try { loadedUnits = JSON.parse(savedUnit); } catch(e) { loadedUnits = []; }
            }
            if (Array.isArray(loadedUnits) && loadedUnits.length > 0) {
                loadedUnits = loadedUnits.filter(u => u && u.nama && seedUnit.map(s => s.toLowerCase()).includes(u.nama.trim().toLowerCase()));
            }
            if (!loadedUnits || loadedUnits.length === 0) {
                window.masterUnitTugasList = seedUnit.map((nama, idx) => ({
                    id: idx + 1, nama: nama, status: 'Aktif', updated_at: '18/6/2024, 07:00:00'
                }));
            } else {
                seedUnit.forEach((nama, idx) => {
                    if (!loadedUnits.some(u => u.nama.trim().toLowerCase() === nama.toLowerCase())) {
                        loadedUnits.push({ id: idx + 1, nama: nama, status: 'Aktif', updated_at: '18/6/2024, 07:00:00' });
                    }
                });
                window.masterUnitTugasList = loadedUnits;
            }

            // Sync from dataPegawai
            if (typeof dataPegawai !== 'undefined' && Array.isArray(dataPegawai)) {
                dataPegawai.forEach(p => {
                    if (p.jabatan && p.jabatan.trim() !== '' && p.jabatan !== '-') {
                        const exists = window.masterJabatanMenpanList.some(item => item.nama.toLowerCase() === p.jabatan.trim().toLowerCase());
                        if (!exists) {
                            window.masterJabatanMenpanList.push({
                                id: window.masterJabatanMenpanList.length + 1,
                                nama: p.jabatan.trim(),
                                status: 'Aktif',
                                updated_at: new Date().toLocaleString('id-ID')
                            });
                        }
                    }
                    const orb = p.jabatan_orb || p.jabatan_pergub;
                    if (orb && orb.trim() !== '' && orb !== '-') {
                        const existsOrb = window.masterJabatanOrbList.some(item => item.nama.toLowerCase() === orb.trim().toLowerCase());
                        if (!existsOrb) {
                            window.masterJabatanOrbList.push({
                                id: window.masterJabatanOrbList.length + 1,
                                nama: orb.trim(),
                                status: 'Aktif',
                                updated_at: new Date().toLocaleString('id-ID')
                            });
                        }
                    }
                    if (p.status_rumpun && p.status_rumpun.trim() !== '' && p.status_rumpun !== '-') {
                        const existsRumpun = window.masterStatusRumpunList.some(item => item.nama.toLowerCase() === p.status_rumpun.trim().toLowerCase());
                        if (!existsRumpun) {
                            window.masterStatusRumpunList.push({
                                id: window.masterStatusRumpunList.length + 1,
                                nama: p.status_rumpun.trim(),
                                status: 'Aktif',
                                updated_at: new Date().toLocaleString('id-ID')
                            });
                        }
                    }
                    if (p.pangkat_gol && p.pangkat_gol.trim() !== '' && p.pangkat_gol !== '-') {
                        const existsPangkat = window.masterPangkatGolonganList.some(item => item.nama.toLowerCase() === p.pangkat_gol.trim().toLowerCase());
                        if (!existsPangkat) {
                            window.masterPangkatGolonganList.push({
                                id: window.masterPangkatGolonganList.length + 1,
                                nama: p.pangkat_gol.trim(),
                                status: 'Aktif',
                                updated_at: new Date().toLocaleString('id-ID')
                            });
                        }
                    }
                    if (p.jenjang_pendidikan && p.jenjang_pendidikan.trim() !== '' && p.jenjang_pendidikan !== '-') {
                        const existsPend = window.masterJenjangPendidikanList.some(item => item.nama.toLowerCase() === p.jenjang_pendidikan.trim().toLowerCase());
                        if (!existsPend) {
                            window.masterJenjangPendidikanList.push({
                                id: window.masterJenjangPendidikanList.length + 1,
                                nama: p.jenjang_pendidikan.trim(),
                                status: 'Aktif',
                                updated_at: new Date().toLocaleString('id-ID')
                            });
                        }
                    }
                    // Master Unit Tugas is strictly limited to 5 official units
                });
            }

            window.saveMasterJabatanToStorage();
        };

        window.saveMasterJabatanToStorage = function() {
            try {
                localStorage.setItem('simpeg_master_jabatan_menpan', JSON.stringify(window.masterJabatanMenpanList));
                localStorage.setItem('simpeg_master_jabatan_orb', JSON.stringify(window.masterJabatanOrbList));
                localStorage.setItem('simpeg_master_status_rumpun', JSON.stringify(window.masterStatusRumpunList));
                localStorage.setItem('simpeg_master_rumpun_jabatan', JSON.stringify(window.masterStatusRumpunList));
                localStorage.setItem('simpeg_master_pangkat_golongan', JSON.stringify(window.masterPangkatGolonganList));
                localStorage.setItem('simpeg_master_jenjang_pendidikan', JSON.stringify(window.masterJenjangPendidikanList));
                localStorage.setItem('simpeg_master_unit_tugas', JSON.stringify(window.masterUnitTugasList));
            } catch(e){}
            window.populateJabatanDatalists();
        };

        window.populateJabatanDatalists = function() {
            // Populate Pergub (ORB) datalist
            let htmlOrb = '';
            if (window.masterJabatanOrbList && window.masterJabatanOrbList.length > 0) {
                window.masterJabatanOrbList.forEach(item => {
                    if (item.status === 'Aktif') {
                        htmlOrb += `<option value="${item.nama}">${item.nama}</option>`;
                    }
                });
            }
            $('#list_jabatan_pergub').html(htmlOrb);

            // Populate Kepmenpan 11 (Menpan) datalist
            let htmlMenpan = '';
            if (window.masterJabatanMenpanList && window.masterJabatanMenpanList.length > 0) {
                window.masterJabatanMenpanList.forEach(item => {
                    if (item.status === 'Aktif') {
