        window.switchJabatanType = function(type) {
            window.switchMasterType(type);
        };

        window.switchMasterType = function(type) {
            window.currentMasterType = type || 'menpan';
            window.currentJabatanType = window.currentMasterType;
            window.currentJabatanPage = 1;

            // Reset tab styles
            $('#tab-btn-menpan, #tab-btn-orb, #tab-btn-rumpun, #tab-btn-pangkat, #tab-btn-pendidikan, #tab-btn-unit')
