        window.getActiveMasterList = function() {
            if (window.currentMasterType === 'orb') return window.masterJabatanOrbList;
            if (window.currentMasterType === 'rumpun') return window.masterStatusRumpunList;
            if (window.currentMasterType === 'pangkat') return window.masterPangkatGolonganList;
            if (window.currentMasterType === 'pendidikan') return window.masterJenjangPendidikanList;
            if (window.currentMasterType === 'unit') return window.masterUnitTugasList;
            return window.masterJabatanMenpanList;
        };

        window.filterMasterJabatan = function() {
            window.currentJabatanPage = 1;
            window.renderMasterJabatan();
        };

        window.renderMasterJabatan = function() {
            if (!window.masterJabatanMenpanList || window.masterJabatanMenpanList.length === 0) {
                window.initMasterJabatanData();
            }

            const activeList = window.getActiveMasterList();

            const keyword = ($('#searchMasterJabatan').val() || '').toLowerCase().trim();
            if (keyword) {
                window.filteredJabatanList = activeList.filter(item => 
                    item.nama.toLowerCase().includes(keyword)
                );
            } else {
                window.filteredJabatanList = [...activeList];
            }

            const total = window.filteredJabatanList.length;
            $('#totalMasterJabatanCount').text(total);

            const pageSize = parseInt($('#jabatanPageSize').val() || '100');
            window.jabatanPageSize = pageSize;

            const totalPages = Math.ceil(total / pageSize) || 1;
            if (window.currentJabatanPage > totalPages) window.currentJabatanPage = totalPages;
            if (window.currentJabatanPage < 1) window.currentJabatanPage = 1;

            const startIdx = (window.currentJabatanPage - 1) * pageSize;
            const endIdx = Math.min(startIdx + pageSize, total);

            const pageItems = window.filteredJabatanList.slice(startIdx, endIdx);

            let html = '';
            if (pageItems.length === 0) {
                html = `<tr><td colspan="5" class="text-center text-muted py-4">Tidak ada data ditemukan.</td></tr>`;
            } else {
                pageItems.forEach((item, idx) => {
                    const num = startIdx + idx + 1;
                    const statusBadge = item.status === 'Aktif' 
                        ? `<span class="badge bg-success-subtle text-success border border-success px-2 py-1">Aktif</span>`
                        : `<span class="badge bg-secondary-subtle text-secondary border border-secondary px-2 py-1">Tidak Aktif</span>`;

                    const safeId = String(item.id).replace(/'/g, "\\'");

                    html += `<tr>
                        <td class="ps-4 fw-semibold text-secondary">${num}</td>
                        <td class="fw-bold text-dark">${item.nama}</td>
                        <td>${statusBadge}</td>
                        <td class="text-muted small">${item.updated_at || '-'}</td>
                        <td class="text-end pe-4">
                            <button type="button" class="btn btn-sm btn-light text-primary border me-1 rounded-2" onclick="window.editMasterJabatan('${safeId}')" title="Edit"><i class="fas fa-edit"></i></button>
                            <button type="button" class="btn btn-sm btn-light text-danger border rounded-2" onclick="window.deleteMasterJabatan('${safeId}')" title="Hapus"><i class="fas fa-trash-alt"></i></button>
                        </td>
                    </tr>`;
                });
            }

            $('#tbodyMasterJabatan').html(html);

            $('#jabatanPaginationInfo').text(`Menampilkan ${total === 0 ? 0 : startIdx + 1} - ${endIdx} dari ${total} data`);
            $('#jabatanPageIndicator').text(`Hal ${window.currentJabatanPage} / ${totalPages}`);
            $('#btnPrevJabatanPage').prop('disabled', window.currentJabatanPage <= 1);
            $('#btnNextJabatanPage').prop('disabled', window.currentJabatanPage >= totalPages);
        };

        window.prevJabatanPage = function() {
            if (window.currentJabatanPage > 1) {
                window.currentJabatanPage--;
                window.renderMasterJabatan();
            }
        };

        window.nextJabatanPage = function() {
            const total = window.filteredJabatanList.length;
            const totalPages = Math.ceil(total / window.jabatanPageSize) || 1;
            if (window.currentJabatanPage < totalPages) {
                window.currentJabatanPage++;
                window.renderMasterJabatan();
            }
        };

        window.changeJabatanPageSize = function() {
            window.currentJabatanPage = 1;
            window.renderMasterJabatan();
        };

        window.saveMasterJabatan = function() {
            const nama = $('#j_nama_jabatan').val().trim();
            if (!nama) {
                showToast("Nama data harus diisi!", "warning");
                return;
            }

            const isAktif = $('#j_status_aktif').is(':checked');
            const statusStr = isAktif ? 'Aktif' : 'Tidak Aktif';
            const idVal = $('#j_id').val();
            const nowStr = new Date().toLocaleString('id-ID');

            const activeList = window.getActiveMasterList();

            if (idVal !== '' && idVal !== null && idVal !== undefined) {
                const item = activeList.find(x => x.id == idVal || String(x.id) === String(idVal));
                if (item) {
                    item.nama = nama;
                    item.status = statusStr;
                    item.updated_at = nowStr;
                    showToast("Data master berhasil diperbarui!", "success");
                }
            } else {
                const newId = activeList.length > 0 ? Math.max(...activeList.map(x => parseInt(x.id) || 0)) + 1 : 1;
                activeList.unshift({
                    id: newId,
                    nama: nama,
                    status: statusStr,
                    updated_at: nowStr
                });
                showToast("Data master baru berhasil ditambahkan!", "success");
            }

            window.saveMasterJabatanToStorage();
            if (typeof window.populateJabatanDatalists === 'function') {
                window.populateJabatanDatalists();
            }
            window.resetFormJabatan();
            window.renderMasterJabatan();
        };

        window.editMasterJabatan = function(id) {
            if (id === undefined || id === null) return;
            const activeList = window.getActiveMasterList();
            const item = activeList.find(x => x.id == id || String(x.id) === String(id));
            if (!item) return;

            $('#j_id').val(item.id);
            $('#j_nama_jabatan').val(item.nama);
            $('#j_status_aktif').prop('checked', item.status === 'Aktif');

            let labelTitle = 'Edit Data';
            if (window.currentMasterType === 'orb') labelTitle = 'Edit Jabatan ORB';
            else if (window.currentMasterType === 'rumpun') labelTitle = 'Edit Rumpun Jabatan';
            else if (window.currentMasterType === 'pangkat') labelTitle = 'Edit Pangkat / Golongan';
            else if (window.currentMasterType === 'pendidikan') labelTitle = 'Edit Jenjang Pendidikan';
            else if (window.currentMasterType === 'unit') labelTitle = 'Edit Unit Tugas';
            else labelTitle = 'Edit Jabatan Menpan';

            $('#form-jabatan-title').text(labelTitle);
            $('#btn-save-jabatan-text').text('Simpan Changes');
            $('#btn-save-jabatan').removeClass('btn-primary').addClass('btn-success');

            const formElement = document.getElementById('formMasterJabatan');
            if (formElement) {
                formElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
            } else {
                window.scrollTo({ top: 100, behavior: 'smooth' });
            }
            setTimeout(() => {
                $('#j_nama_jabatan').focus().select();
            }, 100);
        };

        window.deleteMasterJabatan = function(id) {
            if (id === undefined || id === null) return;
            const activeList = window.getActiveMasterList();
            const item = activeList.find(x => x.id == id || String(x.id) === String(id));
            if (!item) return;

            if (confirm(`Apakah Anda yakin ingin menghapus data "${item.nama}"?`)) {
                if (window.currentMasterType === 'orb') {
                    window.masterJabatanOrbList = window.masterJabatanOrbList.filter(x => x.id != id && String(x.id) !== String(id));
                } else if (window.currentMasterType === 'rumpun') {
                    window.masterStatusRumpunList = window.masterStatusRumpunList.filter(x => x.id != id && String(x.id) !== String(id));
                } else if (window.currentMasterType === 'pangkat') {
                    window.masterPangkatGolonganList = window.masterPangkatGolonganList.filter(x => x.id != id && String(x.id) !== String(id));
                } else if (window.currentMasterType === 'pendidikan') {
                    window.masterJenjangPendidikanList = window.masterJenjangPendidikanList.filter(x => x.id != id && String(x.id) !== String(id));
                } else if (window.currentMasterType === 'unit') {
                    window.masterUnitTugasList = window.masterUnitTugasList.filter(x => x.id != id && String(x.id) !== String(id));
                } else {
                    window.masterJabatanMenpanList = window.masterJabatanMenpanList.filter(x => x.id != id && String(x.id) !== String(id));
                }
                window.saveMasterJabatanToStorage();
                if (typeof window.populateJabatanDatalists === 'function') {
                    window.populateJabatanDatalists();
                }
                showToast("Data master berhasil dihapus!", "info");
                window.renderMasterJabatan();
            }
        };

        window.resetFormJabatan = function() {
            $('#j_id').val('');
            $('#j_nama_jabatan').val('');
            $('#j_status_aktif').prop('checked', true);

            let labelTitle = 'Tambah Data';
            if (window.currentMasterType === 'orb') labelTitle = 'Tambah Jabatan ORB';
            else if (window.currentMasterType === 'rumpun') labelTitle = 'Tambah Rumpun Jabatan';
            else if (window.currentMasterType === 'pangkat') labelTitle = 'Tambah Pangkat / Golongan';
            else if (window.currentMasterType === 'pendidikan') labelTitle = 'Tambah Jenjang Pendidikan';
            else if (window.currentMasterType === 'unit') labelTitle = 'Tambah Unit Tugas';
            else labelTitle = 'Tambah Jabatan Menpan';

            $('#form-jabatan-title').text(labelTitle);
            $('#btn-save-jabatan-text').text('Tambah');
            $('#btn-save-jabatan').removeClass('btn-success').addClass('btn-primary');
        };

