        window.renderUsulanTunjangan = function() {
            if (!window.usulanDataList) window.initUsulanData();
            const search = ($('#searchUsulanKeluarga').val() || '').toLowerCase();
            const filterStatus = $('#filterUsulanKeluargaStatus').val() || '';
            const filterUnit = $('#filterUsulanKeluargaUnit').val() || '';

            let list = window.usulanDataList.filter(u => u.jenis === 'tunjangan');

            // Stats
            let total = list.length;
            let pending = list.filter(u => u.status === 'Menunggu Verifikasi').length;
            let approved = list.filter(u => u.status === 'Disetujui').length;
            let rejected = list.filter(u => u.status === 'Ditolak').length;

