        window.openModalUsulan = function(defaultJenis) {
            if (!window.dataPegawai) window.dataPegawai = [];
            $('#form_usulan_id').val('');
            $('#form_usulan_tgl').val(new Date().toISOString().split('T')[0]);

            // Populate Pegawai Dropdown
            let options = '<option value="">-- Pilih Pegawai Pemohon --</option>';
            dataPegawai.forEach((p, idx) => {
                const name = p.nama || p['Nama Lengkap'] || `Pegawai #${idx+1}`;
                const nip = p.nip || p.NIP || '-';
                options += `<option value="${idx}">${name} (NIP: ${nip})</option>`;
            });
            $('#form_usulan_pegawai_id').html(options);

            $('#usulan_preview_nip, #usulan_preview_jabatan, #usulan_preview_pangkat, #usulan_preview_unit').text('-');

            if (defaultJenis) {
                $('#form_usulan_jenis').val(defaultJenis);
            }
            window.onUsulanJenisChange();

            // Clear Specific Inputs
            $('#form_kel_nama, #form_kel_nik, #form_kel_tgl, #form_kel_status').val('');
            $('#form_pangkat_lama, #form_pangkat_tmt_usulan, #form_pangkat_mkg').val('');
            $('#form_jenjang_jabatan, #form_jenjang_ukom_no, #form_jenjang_ukom_tgl, #form_jenjang_ak').val('');
            $('#form_usulan_berkas, #form_usulan_catatan').val('');

            let modal = new bootstrap.Modal(document.getElementById('modalUsulanForm'));
            modal.show();
        };

        window.onUsulanJenisChange = function() {
            const jenis = $('#form_usulan_jenis').val();
            $('.usulan-specific-section').hide();
            if (jenis === 'tunjangan') {
                $('#section_fields_tunjangan').show();
                $('#modalUsulanTitle').text('Pengajuan Usulan Tunjangan Keluarga');
                $('#modalUsulanSubtitle').text('Formulir penambahan anggota keluarga untuk tunjangan pegawai');
            } else if (jenis === 'pangkat') {
                $('#section_fields_pangkat').show();
                $('#modalUsulanTitle').text('Pengajuan Usulan Kenaikan Pangkat');
                $('#modalUsulanSubtitle').text('Formulir usulan kenaikan pangkat / golongan (KP) pegawai');
            } else if (jenis === 'jenjang') {
                $('#section_fields_jenjang').show();
                $('#modalUsulanTitle').text('Pengajuan Usulan Kenaikan Jenjang');
                $('#modalUsulanSubtitle').text('Formulir usulan kenaikan jenjang jabatan fungsional kesehatan');
            }
        };

        window.onUsulanPegawaiChange = function() {
            const pIdx = $('#form_usulan_pegawai_id').val();
            if (pIdx !== '' && dataPegawai[pIdx]) {
                const p = dataPegawai[pIdx];
                const nip = p.nip || p.NIP || '-';
                const jab = p.jabatan || p.Jabatan || '-';
                const pangkat = p.pangkat || p['Pangkat / Golongan'] || '-';
                const unit = p.tempat_tugas || p['Tempat Tugas'] || 'Puskesmas Kepulauan Seribu Utara';

                $('#usulan_preview_nip').text(nip);
                $('#usulan_preview_jabatan').text(jab);
                $('#usulan_preview_pangkat').text(pangkat);
                $('#usulan_preview_unit').text(unit);

                // Auto-fill defaults
                $('#form_pangkat_lama').val(pangkat);
                $('#form_jenjang_jabatan').val(jab);
            } else {
                $('#usulan_preview_nip, #usulan_preview_jabatan, #usulan_preview_pangkat, #usulan_preview_unit').text('-');
            }
        };

        window.saveUsulan = function(e) {
            e.preventDefault();
            const jenis = $('#form_usulan_jenis').val();
            const pIdx = $('#form_usulan_pegawai_id').val();

            if (pIdx === '' || !dataPegawai[pIdx]) {
                showToast("Silakan pilih pegawai pemohon terlebih dahulu.", "warning");
                return;
            }

            const p = dataPegawai[pIdx];
            const randNum = Math.floor(100 + Math.random() * 900);
            const todayCode = new Date().toISOString().slice(0,7).replace('-', '');
            const newId = `USL-${todayCode}-${randNum}`;

            const item = {
                id: newId,
                jenis: jenis,
                tgl: $('#form_usulan_tgl').val() || new Date().toISOString().split('T')[0],
                nip: p.nip || p.NIP || '',
                nama: p.nama || p['Nama Lengkap'] || '',
                jabatan: p.jabatan || p.Jabatan || '',
                pangkat: p.pangkat || p['Pangkat / Golongan'] || '',
                unit: p.tempat_tugas || p['Tempat Tugas'] || 'Puskesmas Kepulauan Seribu Utara',
                berkas: $('#form_usulan_berkas').val() || '',
                catatan: $('#form_usulan_catatan').val() || '',
                status: 'Menunggu Verifikasi',
                nosk: '',
                catatan_verif: ''
            };

            if (jenis === 'tunjangan') {
                item.kel_jenis = $('#form_kel_jenis').val();
                item.kel_nama = $('#form_kel_nama').val();
                item.kel_nik = $('#form_kel_nik').val();
                item.kel_hub = $('#form_kel_hub').val();
                item.kel_tgl = $('#form_kel_tgl').val();
                item.kel_status = $('#form_kel_status').val();
            } else if (jenis === 'pangkat') {
                item.jenis_kp = $('#form_pangkat_jenis_kp').val();
                item.pangkat_lama = $('#form_pangkat_lama').val();
                item.pangkat_usulan = $('#form_pangkat_usulan').val();
                item.tmt_usulan = $('#form_pangkat_tmt_usulan').val();
                item.mkg = $('#form_pangkat_mkg').val();
            } else if (jenis === 'jenjang') {
                item.jenjang_jabatan = $('#form_jenjang_jabatan').val();
                item.jenjang_lama = $('#form_jenjang_lama').val();
                item.jenjang_usulan = $('#form_jenjang_usulan').val();
                item.ukom_no = $('#form_jenjang_ukom_no').val();
                item.ukom_tgl = $('#form_jenjang_ukom_tgl').val();
                item.ak = $('#form_jenjang_ak').val();
            }

            window.usulanDataList.unshift(item);
            window.saveUsulanToStorage();

            let modalEl = document.getElementById('modalUsulanForm');
            let modal = bootstrap.Modal.getInstance(modalEl);
            if (modal) modal.hide();

            showToast(`Usulan baru (${item.id}) berhasil dibuat & diajukan!`, "success");

            if (jenis === 'tunjangan') window.renderUsulanTunjangan();
            if (jenis === 'pangkat') window.renderUsulanPangkat();
            if (jenis === 'jenjang') window.renderUsulanJenjang();
        };

        window.openModalVerifikasi = function(id) {
            const item = window.usulanDataList.find(u => u.id === id);
            if (!item) return;

            $('#verif_usulan_id').val(item.id);
            $('#verif_usulan_jenis').val(item.jenis);
            $('#verif_preview_no').text(item.id);
            $('#verif_preview_nama').text(`${item.nama} (NIP: ${item.nip})`);

            let detailStr = '';
            if (item.jenis === 'tunjangan') detailStr = `Usulan Tunjangan Keluarga: ${item.kel_nama} (${item.kel_hub})`;
            else if (item.jenis === 'pangkat') detailStr = `Usulan Kenaikan Pangkat: ${item.pangkat_lama} ➔ ${item.pangkat_usulan}`;
            else if (item.jenis === 'jenjang') detailStr = `Usulan Kenaikan Jenjang: ${item.jenjang_lama} ➔ ${item.jenjang_usulan}`;

            $('#verif_preview_detail').text(detailStr);
            $('#verif_status').val(item.status || 'Menunggu Verifikasi');
            $('#verif_nosk').val(item.nosk || '');
            $('#verif_catatan').val(item.catatan_verif || '');

            let modal = new bootstrap.Modal(document.getElementById('modalVerifikasiUsulan'));
            modal.show();
        };

        window.saveVerifikasiUsulan = function(e) {
            e.preventDefault();
            const id = $('#verif_usulan_id').val();
            const item = window.usulanDataList.find(u => u.id === id);
            if (!item) return;

            item.status = $('#verif_status').val();
            item.nosk = $('#verif_nosk').val();
            item.catatan_verif = $('#verif_catatan').val();

            window.saveUsulanToStorage();

            let modalEl = document.getElementById('modalVerifikasiUsulan');
            let modal = bootstrap.Modal.getInstance(modalEl);
            if (modal) modal.hide();

            showToast(`Status verifikasi usulan ${id} berhasil diperbarui!`, "success");

            if (item.jenis === 'tunjangan') window.renderUsulanTunjangan();
            if (item.jenis === 'pangkat') window.renderUsulanPangkat();
            if (item.jenis === 'jenjang') window.renderUsulanJenjang();
        };

        window.openDetailUsulan = function(id) {
            const item = window.usulanDataList.find(u => u.id === id);
            if (!item) return;

            let badgeClass = 'bg-warning text-dark';
            if (item.status === 'Disetujui') badgeClass = 'bg-success';
            if (item.status === 'Ditolak') badgeClass = 'bg-danger';

            let rincianHtml = '';
            if (item.jenis === 'tunjangan') {
                rincianHtml = `
                    <div class="card bg-light border-0 p-3 mb-3">
                        <h6 class="fw-bold text-info mb-2"><i class="fas fa-users me-1"></i> Data Anggota Keluarga</h6>
                        <div class="row g-2 small">
                            <div class="col-md-6">Nama Anggota: <strong>${item.kel_nama || '-'}</strong></div>
                            <div class="col-md-6">NIK: <strong>${item.kel_nik || '-'}</strong></div>
                            <div class="col-md-6">Hubungan: <strong>${item.kel_hub || '-'} (${item.kel_jenis || '-'})</strong></div>
                            <div class="col-md-6">Tgl Nikah/Lahir: <strong>${item.kel_tgl || '-'}</strong></div>
                            <div class="col-md-6">Pekerjaan/Status: <strong>${item.kel_status || '-'}</strong></div>
                        </div>
                    </div>
                `;
            } else if (item.jenis === 'pangkat') {
                rincianHtml = `
                    <div class="card bg-light border-0 p-3 mb-3">
                        <h6 class="fw-bold text-warning mb-2"><i class="fas fa-level-up-alt me-1"></i> Detail Kenaikan Pangkat</h6>
                        <div class="row g-2 small">
                            <div class="col-md-6">Jenis KP: <strong>${item.jenis_kp || '-'}</strong></div>
                            <div class="col-md-6">Pangkat Lama: <strong>${item.pangkat_lama || item.pangkat || '-'}</strong></div>
                            <div class="col-md-6">Pangkat Diusulkan: <strong class="text-success">${item.pangkat_usulan || '-'}</strong></div>
                            <div class="col-md-6">TMT Usulan: <strong>${item.tmt_usulan || '-'}</strong></div>
                            <div class="col-md-6">Masa Kerja Golongan: <strong>${item.mkg || '-'}</strong></div>
                        </div>
                    </div>
                `;
            } else if (item.jenis === 'jenjang') {
                rincianHtml = `
                    <div class="card bg-light border-0 p-3 mb-3">
                        <h6 class="fw-bold text-success mb-2"><i class="fas fa-user-graduate me-1"></i> Detail Kenaikan Jenjang Jabfung</h6>
                        <div class="row g-2 small">
                            <div class="col-md-6">Jabatan Fungsional: <strong>${item.jenjang_jabatan || item.jabatan || '-'}</strong></div>
