        window.deleteUsulan = function(id) {
            if (confirm(`Apakah Anda yakin ingin menghapus berkas usulan ${id}?`)) {
                window.usulanDataList = window.usulanDataList.filter(u => u.id !== id);
                window.saveUsulanToStorage();
                showToast(`Usulan ${id} telah dihapus.`, "info");
                window.renderUsulanTunjangan();
                window.renderUsulanPangkat();
                window.renderUsulanJenjang();
            }
        };

        window.exportUsulanCSV = function(jenis) {
            let list = window.usulanDataList.filter(u => u.jenis === jenis);
            if (!list || list.length === 0) {
                showToast("Tidak ada data usulan untuk diexport.", "warning");
                return;
            }

            let csvContent = "data:text/csv;charset=utf-8,";
            let filename = `Usulan_${jenis}_PKSU_${new Date().toISOString().split('T')[0]}.csv`;

            if (jenis === 'tunjangan') {
                csvContent += "No Usulan,Tgl Usulan,NIP,Nama Pegawai,Unit,Nama Anggota Keluarga,NIK Keluarga,Hubungan,Status Usulan,No SK\n";
                list.forEach(i => {
                    csvContent += `"${i.id}","${i.tgl}","${i.nip}","${i.nama}","${i.unit}","${i.kel_nama}","${i.kel_nik}","${i.kel_hub}","${i.status}","${i.nosk}"\n`;
                });
            } else if (jenis === 'pangkat') {
                csvContent += "No Usulan,Tgl Usulan,NIP,Nama Pegawai,Unit,Pangkat Lama,Pangkat Usulan,TMT Usulan,Status Usulan,No SK\n";
                list.forEach(i => {
                    csvContent += `"${i.id}","${i.tgl}","${i.nip}","${i.nama}","${i.unit}","${i.pangkat_lama}","${i.pangkat_usulan}","${i.tmt_usulan}","${i.status}","${i.nosk}"\n`;
                });
            } else if (jenis === 'jenjang') {
                csvContent += "No Usulan,Tgl Usulan,NIP,Nama Pegawai,Unit,Jenjang Lama,Jenjang Usulan,No Ukom,AK,Status Usulan,No SK\n";
                list.forEach(i => {
                    csvContent += `"${i.id}","${i.tgl}","${i.nip}","${i.nama}","${i.unit}","${i.jenjang_lama}","${i.jenjang_usulan}","${i.ukom_no}","${i.ak}","${i.status}","${i.nosk}"\n`;
                });
            }

            const encodedUri = encodeURI(csvContent);
            const link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", filename);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            showToast("Export CSV usulan berhasil di-download!", "success");
        };

