        window.saveGapToStorage = function() {
            localStorage.setItem('simpeg_gap_kompetensi_list', JSON.stringify(window.gapKompetensiList));
        };

        window.calcGapSummary = function(item) {
            const stdAvg = (item.manajerial_std + item.sosial_std + item.teknis_std) / 3;
            const riilAvg = (item.manajerial_riil + item.sosial_riil + item.teknis_riil) / 3;
            const pct = stdAvg > 0 ? Math.round((riilAvg / stdAvg) * 100) : 100;

            let category = 'Memenuhi Standar';
            let badgeClass = 'bg-success';
            if (pct < 60) {
                category = 'Gap Tinggi';
                badgeClass = 'bg-danger';
            } else if (pct < 80) {
                category = 'Gap Sedang';
                badgeClass = 'bg-warning text-dark';
            } else if (pct < 100) {
                category = 'Gap Ringan';
                badgeClass = 'bg-info text-dark';
            }

            return { stdAvg: stdAvg.toFixed(1), riilAvg: riilAvg.toFixed(1), pct: pct, category: category, badgeClass: badgeClass };
        };

        window.renderGapKompetensi = function() {
            if (!window.gapKompetensiList) window.initGapKompetensiData();
            const search = ($('#searchGapKompetensi').val() || '').toLowerCase();
            const filterCategory = $('#filterGapStatus').val() || '';
            const filterUnit = $('#filterGapUnit').val() || '';

            let list = [...window.gapKompetensiList];

            // Statistics Calculation
            let total = list.length;
            let metCount = 0;
            let moderateCount = 0;
            let highCount = 0;

            list.forEach(i => {
                const s = window.calcGapSummary(i);
                if (s.category === 'Memenuhi Standar') metCount++;
                else if (s.category === 'Gap Tinggi') highCount++;
                else moderateCount++;
            });

            $('#stat-gap-total').text(total);
            $('#stat-gap-met').text(metCount);
            $('#stat-gap-moderate').text(moderateCount);
            $('#stat-gap-high').text(highCount);

            // Filter
            if (search) {
                list = list.filter(u => 
                    (u.nama && u.nama.toLowerCase().includes(search)) ||
                    (u.nip && u.nip.toLowerCase().includes(search)) ||
                    (u.jabatan && u.jabatan.toLowerCase().includes(search)) ||
                    (u.id && u.id.toLowerCase().includes(search))
                );
            }
            if (filterUnit) list = list.filter(u => u.unit === filterUnit);
            if (filterCategory) {
                list = list.filter(u => {
                    const s = window.calcGapSummary(u);
                    return s.category === filterCategory;
                });
            }

            let html = '';
            if (list.length === 0) {
                html = `<tr><td colspan="7" class="text-center py-4 text-muted"><i class="fas fa-folder-open me-2"></i> Belum ada data analisis gap kompetensi.</td></tr>`;
            } else {
                list.forEach((item, idx) => {
                    const s = window.calcGapSummary(item);

                    html += `
                        <tr>
                            <td class="text-center small">${idx + 1}</td>
                            <td>
                                <div class="fw-bold text-dark small">${item.nama || '-'}</div>
                                <div class="small text-muted">NIP: ${item.nip || '-'}</div>
                                <div class="small text-secondary">${item.unit || '-'}</div>
                            </td>
                            <td>
                                <div class="fw-semibold text-primary small">${item.jabatan || '-'}</div>
                                <div class="small text-muted">Tahun Evaluasi: ${item.tahun || '2026'}</div>
                            </td>
                            <td>
                                <div class="small"><span class="text-muted">Mnj:</span> <strong>${item.manajerial_riil}/${item.manajerial_std}</strong> | <span class="text-muted">Sos:</span> <strong>${item.sosial_riil}/${item.sosial_std}</strong></div>
                                <div class="small"><span class="text-muted">Teknis:</span> <strong class="text-primary">${item.teknis_riil}/${item.teknis_std}</strong></div>
                            </td>
                            <td>
                                <div class="fw-bold small ${s.pct >= 100 ? 'text-success' : s.pct >= 80 ? 'text-info' : s.pct >= 60 ? 'text-warning' : 'text-danger'}">${s.pct}% Capaian</div>
                                <div class="progress mt-1" style="height: 6px;">
                                    <div class="progress-bar ${s.badgeClass}" style="width: ${Math.min(s.pct, 100)}%"></div>
                                </div>
                            </td>
                            <td>
                                <span class="badge ${s.badgeClass} rounded-pill">${s.category}</span>
                            </td>
                            <td class="text-center">
                                <div class="btn-group btn-group-sm">
                                    <button class="btn btn-outline-info" title="Detail Matriks Gap" onclick="window.openDetailGap('${item.id}')"><i class="fas fa-eye"></i></button>
                                    <button class="btn btn-outline-danger" title="Hapus Evaluasi" onclick="window.deleteGap('${item.id}')"><i class="fas fa-trash-alt"></i></button>
                                </div>
                            </td>
                        </tr>
                    `;
                });
            }
            $('#tableGapKompetensi tbody').html(html);
        };

