        window.saveGapKompetensi = function(e) {
            e.preventDefault();
            const pIdx = $('#form_gap_pegawai_id').val();
            if (pIdx === '' || !dataPegawai[pIdx]) {
                showToast("Silakan pilih pegawai terlebih dahulu.", "warning");
                return;
            }

            const p = dataPegawai[pIdx];
            const randNum = Math.floor(100 + Math.random() * 900);
            const newId = `GAP-${$('#form_gap_tahun').val()}-${randNum}`;

            const item = {
                id: newId,
                tahun: parseInt($('#form_gap_tahun').val()) || 2026,
                nip: p.nip || p.NIP || '',
                nama: p.nama || p['Nama Lengkap'] || '',
                jabatan: p.jabatan || p.Jabatan || '',
                pangkat: p.pangkat || p['Pangkat / Golongan'] || '',
                unit: p.tempat_tugas || p['Tempat Tugas'] || 'Puskesmas Kepulauan Seribu Utara',
                manajerial_std: parseInt($('#form_gap_manajerial_std').val()) || 0,
                manajerial_riil: parseInt($('#form_gap_manajerial_riil').val()) || 0,
                sosial_std: parseInt($('#form_gap_sosial_std').val()) || 0,
                sosial_riil: parseInt($('#form_gap_sosial_riil').val()) || 0,
                teknis_std: parseInt($('#form_gap_teknis_std').val()) || 0,
                teknis_riil: parseInt($('#form_gap_teknis_riil').val()) || 0,
                rekomendasi: $('#form_gap_rekomendasi').val() || 'Sesuai Standar',
                catatan: $('#form_gap_catatan').val() || '-'
            };

            window.gapKompetensiList.unshift(item);
            window.saveGapToStorage();

            let modalEl = document.getElementById('modalGapKompetensiForm');
            let modal = bootstrap.Modal.getInstance(modalEl);
            if (modal) modal.hide();

            showToast(`Evaluasi Gap Kompetensi (${item.id}) berhasil disimpan!`, "success");
            window.renderGapKompetensi();
