        window.deleteGap = function(id) {
            if (confirm(`Apakah Anda yakin ingin menghapus data evaluasi gap ${id}?`)) {
                window.gapKompetensiList = window.gapKompetensiList.filter(u => u.id !== id);
                window.saveGapToStorage();
                showToast(`Data evaluasi gap ${id} telah dihapus.`, "info");
                window.renderGapKompetensi();
            }
        };

        // ==========================================
        // URAIAN TUGAS MANAGEMENT SYSTEM
        // ==========================================
        window.renderUraian = function() {
            if (typeof dataPegawai === 'undefined' || !Array.isArray(dataPegawai)) return;

            const searchQuery = ($('#searchUraian').val() || '').toLowerCase().trim();
            const unitFilter = $('#filterUraianUnit').val() || '';
            const statusFilter = $('#filterUraianStatus').val() || 'ALL';

            let totalPegawai = dataPegawai.length;
            let totalLengkap = 0;
            let totalDraft = 0;

            let tbodyHtml = '';
            let countRendered = 0;

            dataPegawai.forEach((p, idx) => {
                const nama = p.nama || 'Tanpa Nama';
                const nip = p.nip || '-';
                const ukpd = p.ukpd || p.unit_tugas || 'Puskesmas Seribu Utara';
                const jabatan = p.jabatan || p.jabatan_kepmenpan || p.jabatan_pergub || 'Staf Administrasi';
                const foto = p.foto || '/assets/default-avatar.png';

                // Check Uraian Tugas
                const ut = p.uraian_tugas || null;
                const isLengkap = ut && ut.ikhtisar && ut.tugas_pokok && ut.status === 'Lengkap';

                if (isLengkap) totalLengkap++;
                else totalDraft++;

                // Search Filter
                const matchSearch = !searchQuery || nama.toLowerCase().includes(searchQuery) || nip.toLowerCase().includes(searchQuery) || jabatan.toLowerCase().includes(searchQuery);
                // Unit Filter
                const matchUnit = !unitFilter || ukpd.toLowerCase() === unitFilter.toLowerCase();
                // Status Filter
                const matchStatus = statusFilter === 'ALL' || (statusFilter === 'Lengkap' && isLengkap) || (statusFilter === 'Draft' && !isLengkap);

                if (matchSearch && matchUnit && matchStatus) {
                    countRendered++;
                    const statusBadge = isLengkap 
                        ? `<span class="badge bg-success-subtle text-success px-2 py-1 rounded-pill"><i class="fas fa-check-circle me-1"></i> Lengkap (Aktif)</span>`
                        : `<span class="badge bg-warning-subtle text-warning-emphasis px-2 py-1 rounded-pill"><i class="fas fa-edit me-1"></i> Belum Diisi / Draft</span>`;

                    const tglSk = ut && ut.tgl_penetapan ? ut.tgl_penetapan : '-';

                    tbodyHtml += `
                        <tr>
                            <td class="text-center fw-bold text-muted">${countRendered}</td>
                            <td>
                                <div class="d-flex align-items-center gap-2">
                                    <img src="${foto}" class="rounded-circle object-fit-cover border" style="width: 38px; height: 38px;" onerror="this.src='https://ui-avatars.com/api/?name=${encodeURIComponent(nama)}&background=0D8ABC&color=fff'">
                                    <div>
                                        <div class="fw-bold text-dark">${nama}</div>
                                        <div class="text-muted small" style="font-size: 0.75rem;">NIP: ${nip}</div>
                                    </div>
                                </div>
                            </td>
                            <td>
                                <div class="fw-semibold text-primary">${jabatan}</div>
                                <div class="text-muted small" style="font-size: 0.72rem;"><i class="fas fa-building text-secondary me-1"></i> ${ukpd}</div>
                            </td>
                            <td>${statusBadge}</td>
                            <td><span class="text-muted small">${tglSk}</span></td>
                            <td class="text-center">
                                <div class="btn-group btn-group-sm">
                                    <button type="button" class="btn btn-sm btn-primary rounded-pill px-3 me-1 shadow-sm" onclick="window.openModalKelolaUraianTugas(${idx})" title="Isi / Edit Uraian Tugas">
                                        <i class="fas fa-pen-square me-1"></i> Kelola
                                    </button>
                                    <button type="button" class="btn btn-sm btn-outline-success rounded-pill px-2 me-1" onclick="window.cetakUraianTugas(${idx})" title="Cetak / Preview PDF">
                                        <i class="fas fa-print"></i>
                                    </button>
                                    <button type="button" class="btn btn-sm btn-outline-info rounded-pill px-2" onclick="window.openWABroadcastModalForUraian(${idx})" title="Kirim Reminder WA">
                                        <i class="fab fa-whatsapp"></i>
                                    </button>
                                </div>
                            </td>
                        </tr>
                    `;
                }
            });

            if (countRendered === 0) {
                tbodyHtml = `
                    <tr>
                        <td colspan="6" class="text-center py-4 text-muted">
                            <i class="fas fa-folder-open fs-3 d-block mb-2 text-secondary opacity-50"></i>
                            Tidak ada data pegawai yang sesuai dengan filter pencarian Uraian Tugas.
                        </td>
                    </tr>
                `;
            }

            $('#stat-uraian-total').text(totalPegawai);
            $('#stat-uraian-lengkap').text(totalLengkap);
            $('#stat-uraian-draft').text(totalDraft);

            $('#tbodyUraian').html(tbodyHtml);
        };

        window.openModalKelolaUraianTugas = function(pegawaiIdx) {
            if (typeof dataPegawai === 'undefined' || !dataPegawai[pegawaiIdx]) return;
            const p = dataPegawai[pegawaiIdx];

            $('#u_pegawai_index').val(pegawaiIdx);
            $('#u_preview_nama').text(p.nama || '-');
            $('#u_preview_nip').text(p.nip || '-');
            $('#u_preview_jabatan').text(p.jabatan || p.jabatan_kepmenpan || p.jabatan_pergub || 'Staf Kesehatan');
            $('#u_preview_unit').text(p.ukpd || p.unit_tugas || 'Puskesmas Seribu Utara');
            $('#u_preview_foto').attr('src', p.foto || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(p.nama || 'P') + '&background=0D8ABC&color=fff');

            const ut = p.uraian_tugas || {};
            const isLengkap = ut && ut.ikhtisar && ut.tugas_pokok && ut.status === 'Lengkap';

            if (isLengkap) {
                $('#u_preview_status_badge').removeClass('bg-warning-subtle text-warning-emphasis bg-primary-subtle text-primary').addClass('bg-success-subtle text-success').text('Lengkap (Aktif)');
            } else {
                $('#u_preview_status_badge').removeClass('bg-success-subtle text-success').addClass('bg-warning-subtle text-warning-emphasis').text('Belum Diisi / Draft');
            }

            // Fill form values if exists
            $('#u_ikhtisar_jabatan').val(ut.ikhtisar || '');
            $('#u_tugas_pokok').val(ut.tugas_pokok || '');
            $('#u_tugas_tambahan').val(ut.tugas_tambahan || '');
            $('#u_wewenang').val(ut.wewenang || '');
            $('#u_tanggung_jawab').val(ut.tanggung_jawab || '');
            $('#u_tgl_penetapan').val(ut.tgl_penetapan || new Date().toISOString().slice(0, 10));
            $('#u_nama_atasan').val(ut.nama_atasan || 'Kepala Puskesmas Kepulauan Seribu Utara');

            let modalEl = document.getElementById('modalKelolaUraianTugas');
            let modal = new bootstrap.Modal(modalEl);
            modal.show();
        };

        window.applySmartUraianTemplate = function() {
            const idx = $('#u_pegawai_index').val();
            if (idx === '' || typeof dataPegawai === 'undefined' || !dataPegawai[idx]) return;

            const p = dataPegawai[idx];
            const j = (p.jabatan || p.jabatan_kepmenpan || p.jabatan_pergub || '').toLowerCase();

            let ikhtisar = "";
            let tugasPokok = "";
            let tugasTambahan = "";
            let wewenang = "";
            let tanggungJawab = "";

            if (j.includes('dokter')) {
                ikhtisar = "Melakukan pelayanan kesehatan promotif, preventif, kuratif, dan rehabilitatif serta pengelolaan pelayanan medis di Puskesmas dan jejaringnya untuk meningkatkan derajat kesehatan masyarakat.";
                tugasPokok = "1. Melakukan pemeriksaan medis, anamnesis, dan penegakan diagnosis pasien rawat jalan/IGD.\n2. Memberikan resep obat, tindakan medis, dan terapi sesuai standar operasional prosedur (SOP).\n3. Melakukan rujukan pasien yang memerlukan penanganan tingkat lanjut secara tepat dan akurat.\n4. Menyusun rekam medis pasien secara lengkap, rapi, dan tepat waktu.\n5. Memberikan edukasi kesehatan dan konseling medis kepada pasien serta keluarga.";
                tugasTambahan = "1. Penanggung Jawab / Koordinator Pelayanan Medis & Kegawatdaruratan Pulau.\n2. Tim Fasilitator Akreditasi Puskesmas dan audit medis internal.";
                wewenang = "1. Menentukan diagnosis medis dan memberikan resep obat sesuai indikasi klinis.\n2. Melakukan tindakan medis invasif/non-invasif darurat sesuai kewenangan klinis (clinical privilege).";
                tanggungJawab = "1. Keselamatan dan ketepatan penanganan medis pasien.\n2. Kerahasiaan data rekam medis pasien sesuai perundang-undangan.";
            } else if (j.includes('perawat')) {
                ikhtisar = "Melakukan kegiatan pelayanan asuhan keperawatan yang meliputi pengkajian keperawatan, perumusan diagnosis, penyusunan rencana, tindakan keperawatan, evaluasi, serta dokumentasi keperawatan.";
                tugasPokok = "1. Melakukan pengkajian keperawatan dasar dan lanjutan pada individu dan keluarga.\n2. Melakukan komunikasi terapeutik dan tindakan keperawatan mandiri maupun kolaboratif.\n3. Melakukan perawatan luka, pemantauan tanda-tanda vital (TTV), dan pemberian obat sesuai instruksi medis.\n4. Melengkapi dokumentasi rekam medis dan asuhan keperawatan (ASKEP).\n5. Memberikan penyuluhan dan edukasi kesehatan masyarakat.";
                tugasTambahan = "1. Anggota Tim Keselamatan Pasien dan Pengendalian Infeksi (PPI) Puskesmas.\n2. Tim Pelayanan Kesehatan Keliling (PUSLING) dan Posyandu Pulau.";
                wewenang = "1. Melaksanakan tindakan asuhan keperawatan mandiri dan tindakan kolaboratif medis.\n2. Mengatur alur triase dan ruang perawatan sesuai kebutuhan kondisi pasien.";
                tanggungJawab = "1. Mutu dan keselamatan tindakan asuhan keperawatan pada pasien.\n2. Keutuhan dan pemeliharaan alat kesehatan (alkes) keperawatan.";
            } else if (j.includes('bidan')) {
                ikhtisar = "Melakukan pelayanan asuhan kebidanan pada ibu hamil, bersalin, nifas, bayi baru lahir, keluarga berencana (KB), serta pelayanan kesehatan reproduksi perempuan.";
                tugasPokok = "1. Melakukan pemeriksaan kehamilan (ANC) berkualitas dan pemantauan tumbuh kembang janin.\n2. Melakukan pertolongan persalinan normal dan penanganan awal kegawatdaruratan maternal-neonatal.\n3. Melakukan asuhan kebidanan pada ibu nifas dan bayi baru lahir (BBL).\n4. Memberikan pelayanan Keluarga Berencana (KB) dan konseling kesehatan reproduksi.\n5. Melakukan pencatatan dan pelaporan PWS-KIA serta rekam medis kebidanan.";
                tugasTambahan = "1. Koordinator Program KIA/KB dan Pendampingan Posyandu Balita/Lansia Pulau.\n2. Anggota Tim Penurunan Stunting Puskesmas.";
                wewenang = "1. Melakukan tindakan kebidanan mandiri dan penanganan awal kegawatdaruratan kebidanan.\n2. Memberikan suplemen dan obat-obatan kebidanan sesuai kewenangan profesi.";
                tanggungJawab = "1. Keselamatan ibu dan bayi selama proses pelayanan kebidanan.\n2. Ketepatan pelaporan data KIA dan cakupan pelayanan KB.";
            } else if (j.includes('apoteker') || j.includes('farmasi') || j.includes('obat')) {
                ikhtisar = "Melakukan pengelolaan sediaan farmasi, alat kesehatan, bahan medis habis pakai (BMHP), serta pelayanan farmasi klinik di Puskesmas.";
                tugasPokok = "1. Melakukan penerimaan, penyimpanan, pendistribusian, dan penataan obat/BMHP.\n2. Melakukan skrining resep, penyiapan obat, dan etiket resep secara cermat.\n3. Melakukan penyerahan obat disertai Pemberian Informasi Obat (PIO) dan konseling.\n4. Melakukan pencatatan mutasi kartu stok obat dan rekapitulasi LPLPO.\n5. Pemantauan tanggal kadaluarsa (expired date) sediaan farmasi.";
                tugasTambahan = "1. Tim Pengadaan dan Inventarisasi Sediaan Obat Puskesmas.\n2. Tim Edukasi Penggunaan Obat Rasional (GEMA TAFORMA).";
                wewenang = "1. Menolak resep yang tidak jelas, tidak lengkap, atau berpotensi interaksi berbahaya.\n2. Melakukan penggantian merek sediaan sesuai persetujuan dokter penanggung jawab.";
                tanggungJawab = "1. Ketersediaan, keamanan, dan kualitas obat/BMHP yang diserahkan.\n2. Akurasi pencatatan stok dan pelaporan sediaan psikotropika/narkotika.";
            } else if (j.includes('sanitarian') || j.includes('lingkungan') || j.includes('kesling')) {
                ikhtisar = "Melakukan kegiatan kesehatan lingkungan yang meliputi pengawasan kualitas air, penyehatan makanan/minuman, pengelolaan limbah medis, dan pengendalian vektor penyakit.";
                tugasPokok = "1. Melakukan inspeksi kesehatan lingkungan (IKL) tempat-tempat umum dan sarana air bersih.\n2. Pengawasan dan pengelolaan limbah medis padat/cair B3 Puskesmas.\n3. Pengambilan sampel air dan pemeriksaan kualitas lingkungan pemukiman.\n4. Konseling kesehatan lingkungan bagi masyarakat dan penderita penyakit berbasis lingkungan.\n5. Pengendalian dan surveilans jentik nyamuk/vektor di area pulau.";
                tugasTambahan = "1. Anggota Tim K3 dan Pengelolaan Limbah B3 Wilayah.\n2. Koordinator Program Sanitasi Total Berbasis Masyarakat (STBM).";
                wewenang = "1. Memberikan rekomendasi laik sehat sarana saniter dan industri rumah tangga.\n2. Melakukan tindakan penghentian sementara penggunaan air/sarana yang tercemar.";
                tanggungJawab = "1. Terkelola dengan baik limbah medis B3 Puskesmas secara aman.\n2. Keakuratan data dan hasil pemeriksaan sampel lingkungan.";
            } else if (j.includes('laboratorium') || j.includes('pranata') || j.includes('atlm')) {
                ikhtisar = "Melakukan pelayanan laboratorium kesehatan meliputi penerimaan spesimen, pemeriksaan spesimen, pemeliharaan reagen, serta verifikasi hasil pemeriksaan spesimen.";
                tugasPokok = "1. Melakukan pengambilan spesimen darah, urine, dahak, dan bahan laboratorium lain.\n2. Melakukan pemeriksaan laboratorium hematologi, kimia klinik, mikrobiologi, dan imunologi.\n3. Melakukan validasi dan pencatatan hasil pemeriksaan laboratorium.\n4. Pemeliharaan dan kalibrasi alat instrumen laboratorium secara rutin.\n5. Pengelolaan reagen dan bahan kontrol laboratorium.";
                tugasTambahan = "1. Tim Penanggulangan KLB / Pemeriksaan Swab & Laboratorium Lapangan.\n2. Pengelola Pemantauan Pemantapan Mutu Internal (PMI) & Eksternal (PME).";
                wewenang = "1. Menolak spesimen yang rusak, lisis, atau tidak memenuhi syarat sampel laboratorium.\n2. Mengeluarkan hasil rincian laboratorium resmi setelah divalidasi.";
                tanggungJawab = "1. Akurasi, presisi, dan validitas hasil pemeriksaan laboratorium.\n2. Keselamatan dan pencegahan kontaminasi spesimen.";
            } else {
                ikhtisar = "Melakukan kegiatan administrasi, tata usaha, pengelolaan data kepegawaian, keuangan/arsip, dan pelayanan tata kelola kantor Puskesmas.";
                tugasPokok = "1. Mengelola persuratan, pengarsipan, dan administrasi perkantoran secara tertib.\n2. Melakukan penginputan dan pembaruan data pada aplikasi SIMPEG dan sistem kepegawaian.\n3. Menyusun rekapitulasi kehadiran, laporan berkala, dan dokumentasi rapat instansi.\n4. Membantu pelayanan administrasi umum bagi pegawai dan masyarakat.\n5. Pemeliharaan perlengkapan sarana kerja dan aset kantor.";
                tugasTambahan = "1. Anggota Tim Admin Kepegawaian dan Umum Puskesmas.\n2. Petugas Pelayanan Informasi dan Pengaduan Masyarakat (Humas).";
                wewenang = "1. Mengelola dan mengarsipkan dokumen resmi instansi sesuai SOP.\n2. Memberikan konfirmasi data administrasi kepegawaian internal.";
                tanggungJawab = "1. Kerahasiaan, keamanan, dan kerapihan arsip kepegawaian/instansi.\n2. Ketepatan waktu penyusunan laporan administrasi perkantoran.";
            }

            $('#u_ikhtisar_jabatan').val(ikhtisar);
            $('#u_tugas_pokok').val(tugasPokok);
            $('#u_tugas_tambahan').val(tugasTambahan);
            $('#u_wewenang').val(wewenang);
            $('#u_tanggung_jawab').val(tanggungJawab);

            if (typeof showToast === 'function') {
                showToast(`Template Uraian Tugas untuk jabatan "${p.jabatan || 'Pegawai'}" berhasil diisikan!`, "success");
            }
        };

        window.saveUraianTugas = function() {
            const idx = $('#u_pegawai_index').val();
            if (idx === '' || typeof dataPegawai === 'undefined' || !dataPegawai[idx]) return;

            const ikhtisar = $('#u_ikhtisar_jabatan').val().trim();
            const tugasPokok = $('#u_tugas_pokok').val().trim();
            const tugasTambahan = $('#u_tugas_tambahan').val().trim();
            const wewenang = $('#u_wewenang').val().trim();
            const tanggungJawab = $('#u_tanggung_jawab').val().trim();
            const tglPenetapan = $('#u_tgl_penetapan').val();
            const namaAtasan = $('#u_nama_atasan').val().trim();

            if (!ikhtisar || !tugasPokok || !wewenang || !tanggungJawab) {
                alert("Mohon lengkapi Ikhtisar Jabatan, Tugas Pokok, Wewenang, dan Tanggung Jawab terlebih dahulu!");
                return;
            }

            dataPegawai[idx].uraian_tugas = {
                ikhtisar: ikhtisar,
                tugas_pokok: tugasPokok,
                tugas_tambahan: tugasTambahan,
                wewenang: wewenang,
                tanggung_jawab: tanggungJawab,
                tgl_penetapan: tglPenetapan || new Date().toISOString().slice(0, 10),
                nama_atasan: namaAtasan || 'Kepala Puskesmas Kepulauan Seribu Utara',
                status: 'Lengkap',
                updated_at: new Date().toLocaleString('id-ID')
            };

            // Persist to localStorage dataPegawai if function exists
            if (typeof window.savePegawaiToStorage === 'function') {
                window.savePegawaiToStorage();
            } else {
                try {
                    localStorage.setItem('simpeg_data_pegawai', JSON.stringify(dataPegawai));
                } catch(e) {}
            }

            let modalEl = document.getElementById('modalKelolaUraianTugas');
            let modal = bootstrap.Modal.getInstance(modalEl);
            if (modal) modal.hide();

            if (typeof showToast === 'function') {
                showToast(`Uraian Tugas pegawai ${dataPegawai[idx].nama} berhasil disimpan!`, "success");
            } else {
                alert("Uraian Tugas berhasil disimpan!");
            }

            window.renderUraian();
        };

        window.previewCetakUraianTugasFromModal = function() {
            const idx = $('#u_pegawai_index').val();
            if (idx !== '') {
                window.cetakUraianTugas(idx);
            }
        };

        window.cetakUraianTugas = function(pegawaiIdx) {
            if (typeof dataPegawai === 'undefined' || !dataPegawai[pegawaiIdx]) return;
            const p = dataPegawai[pegawaiIdx];
            const ut = p.uraian_tugas || {};

            if (!ut.ikhtisar || !ut.tugas_pokok) {
                if (!confirm("Pegawai ini belum mengisi Uraian Tugas secara lengkap. Apakah Anda ingin tetap membuka/mencetak dokumen draf?")) {
                    return;
                }
            }

            const formatLines = (str) => {
                if (!str) return '-';
                return str.split('\n').map(line => line.trim()).filter(line => line !== '').map(line => `<div style="margin-bottom: 4px;">${line}</div>`).join('');
            };

            const printHtml = `
                <!DOCTYPE html>
                <html b:css='false' b:defaultmagic='true' b:layoutsUrl='http://www.google.com/layouts' b:responsive='true' b:version='2' class='v2' expr:dir='data:blog.languageDirection' xmlns='http://www.w3.org/1999/xhtml' xmlns:b='http://www.google.com/2005/gml/b' xmlns:data='http://www.google.com/2005/gml/data' xmlns:expr='http://www.google.com/2005/gml/expr'>
                <head>
                    <meta charset="UTF-8">
                    <title>Surat Uraian Tugas - ${p.nama || 'Pegawai'}</title>
                    ___STYLE_BLOCK_4___
                </head>
                <body>
<b:section id="main" class="main">
<b:widget id="Blog1" locked="true" title="Blog Posts" type="Blog" version="1">
<b:includable id="main">
                    <div class="no-print" style="margin-bottom: 15px; text-align: right;">
                        <button onclick="window.print()" style="background: #0d6efd; color: #fff; border: none; padding: 8px 18px; border-radius: 20px; font-weight: bold; cursor: pointer;">
                            🖨️ Cetak Dokumen Uraian Tugas
                        </button>
                    </div>

                    <div class="kop-container">
                        <div class="kop-prov">PEMERINTAH PROVINSI DKI JAKARTA</div>
                        <div class="kop-dinas">DINAS KESEHATAN SUKU DINAS KESEHATAN KAB. ADM. KEPULAUAN SERIBU</div>
                        <div class="kop-pkm">PUSKESMAS KEPULAUAN SERIBU UTARA</div>
                        <div class="kop-addr">Jl. Utama Pulau Kelapa, Kec. Kepulauan Seribu Utara, Kab. Adm. Kepulauan Seribu, Kode Pos 14540</div>
                    </div>

                    <div class="doc-title">
                        <h3>SURAT PENETAPAN URAIAN TUGAS PEGAWAI</h3>
                        <p>Nomor: 800/UT/${p.nip || '0000'}/PKSU/${new Date().getFullYear()}</p>
                    </div>

                    <table class="tbl-info">
                        <tr><td width="22%"><strong>Nama Pegawai</strong></td><td width="3%">:</td><td width="75%"><strong>${p.nama || '-'}</strong></td></tr>
                        <tr><td>NIP / NRK</td><td>:</td><td>${p.nip || '-'} / ${p.nrk || '-'}</td></tr>
                        <tr><td>Pangkat / Golongan</td><td>:</td><td>${p.pangkat_gol || p.golongan || '-'}</td></tr>
                        <tr><td>Jabatan Resmi</td><td>:</td><td>${p.jabatan || p.jabatan_kepmenpan || p.jabatan_pergub || '-'}</td></tr>
                        <tr><td>Unit Kerja / UKPD</td><td>:</td><td>${p.ukpd || p.unit_tugas || 'Puskesmas Kepulauan Seribu Utara'}</td></tr>
                    </table>

                    <div class="sec-box">
                        <div class="sec-title">I. IKHTISAR JABATAN</div>
                        <div class="sec-content">${ut.ikhtisar || '-'}</div>
                    </div>

                    <div class="sec-box">
                        <div class="sec-title">II. TUGAS POKOK DAN FUNGSI UTAMA</div>
                        <div class="sec-content">${formatLines(ut.tugas_pokok)}</div>
                    </div>

                    <div class="sec-box">
                        <div class="sec-title">III. TUGAS TAMBAHAN / TERINTEGRASI</div>
                        <div class="sec-content">${formatLines(ut.tugas_tambahan)}</div>
                    </div>

                    <div class="sec-box">
                        <div class="sec-title">IV. WEWENANG JABATAN</div>
                        <div class="sec-content">${formatLines(ut.wewenang)}</div>
