        window.openWABroadcastModalForUraian = function(pegawaiIdx) {
            if (typeof dataPegawai === 'undefined' || !dataPegawai[pegawaiIdx]) return;
            const p = dataPegawai[pegawaiIdx];

            const msg = `Halo Bpk/Ibu *${p.nama}*,\n\nSalam sehat dari Subbagian Kepegawaian *Puskesmas Kepulauan Seribu Utara*.\n\nDiinformasikan untuk segera melengkapi Formulir Uraian Tugas Pegawai (Ikhtisar, Tugas Pokok, Tugas Tambahan, Wewenang & Tanggung Jawab) pada sistem *SIMPEG Digital*.\n\nTerima kasih.`;

            if (typeof window.openModalWABroadcast === 'function') {
                window.openModalWABroadcast(p.nohp || p.hp || '', msg);
            } else {
                const phone = (p.nohp || '').replace(/[^0-9]/g, '');
                window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`, '_blank');
            }
        };

        // ==========================================
        // DOKUMEN PEGAWAI (GOOGLE DRIVE) SYSTEM
        // ==========================================
        window.getDokumenCounts = function(p) {
            const da = p.dokumen_arsip || {};
            let count = 0;
            let totalPossible = 8;

            const check = (item) => {
                if (da[item] && (da[item].url || da[item].no)) return true;
                return false;
            };

            if (check('ktp')) count++;
            if (check('npwp')) count++;
            if (check('kk')) count++;
            if (check('nikah')) count++;
            if (check('ijazah')) count++;
            if (check('sk')) count++;
            if (check('str')) count++;
            if (check('sip')) count++;

            const extraCount = Array.isArray(da.lainnya) ? da.lainnya.filter(l => l && (l.url || l.nama)).length : 0;

            return {
                uploaded: count,
                total: totalPossible,
                extraCount: extraCount,
                isLengkap: count >= 5
            };
        };

        window.renderDokumen = function() {
            if (typeof dataPegawai === 'undefined' || !Array.isArray(dataPegawai)) return;

            const searchQuery = ($('#searchDokumen').val() || '').toLowerCase().trim();
            const unitFilter = $('#filterDokumenUnit').val() || '';
            const statusFilter = $('#filterDokumenStatus').val() || 'ALL';

            let totalPegawai = dataPegawai.length;
            let totalLengkap = 0;
            let totalDraft = 0;
            let totalDriveFiles = 0;

            let tbodyHtml = '';
            let countRendered = 0;

            dataPegawai.forEach((p, idx) => {
                const nama = p.nama || 'Tanpa Nama';
                const nip = p.nip || '-';
                const ukpd = p.ukpd || p.unit_tugas || 'Puskesmas Seribu Utara';
                const jabatan = p.jabatan || p.jabatan_kepmenpan || p.jabatan_pergub || 'Staf Administrasi';
                const foto = p.foto || '/assets/default-avatar.png';

                const stats = window.getDokumenCounts(p);
                if (stats.isLengkap) totalLengkap++;
                else totalDraft++;

                totalDriveFiles += (stats.uploaded + stats.extraCount);

                const matchSearch = !searchQuery || nama.toLowerCase().includes(searchQuery) || nip.toLowerCase().includes(searchQuery) || jabatan.toLowerCase().includes(searchQuery);
                const matchUnit = !unitFilter || ukpd.toLowerCase() === unitFilter.toLowerCase();
                const matchStatus = statusFilter === 'ALL' || (statusFilter === 'Lengkap' && stats.isLengkap) || (statusFilter === 'Draft' && !stats.isLengkap);

                if (matchSearch && matchUnit && matchStatus) {
                    countRendered++;

                    const percent = Math.min(100, Math.round((stats.uploaded / stats.total) * 100));
                    const progressColor = percent >= 75 ? 'bg-success' : (percent >= 50 ? 'bg-info' : (percent >= 25 ? 'bg-warning' : 'bg-danger'));

                    const progressHtml = `
                        <div class="d-flex align-items-center justify-content-between mb-1" style="font-size: 0.75rem;">
                            <span class="fw-bold text-dark">${stats.uploaded}/${stats.total} Dokumen</span>
                            <span class="fw-semibold text-muted">${percent}%</span>
                        </div>
                        <div class="progress" style="height: 6px;">
                            <div class="progress-bar ${progressColor}" role="progressbar" style="width: ${percent}%;" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"></div>
                        </div>
                    `;

                    const da = p.dokumen_arsip || {};
                    const hasDoc = (key) => da[key] && (da[key].url || da[key].no);

                    const badgeDoc = (label, key) => {
                        return hasDoc(key) 
                            ? `<span class="badge bg-success-subtle text-success border border-success-subtle px-1 py-1 me-1 mb-1" style="font-size: 0.68rem;" title="${label} Terunggah"><i class="fas fa-check-circle me-1"></i>${label}</span>`
                            : `<span class="badge bg-light text-muted border px-1 py-1 me-1 mb-1" style="font-size: 0.68rem;" title="${label} Belum Ada"><i class="fas fa-minus-circle me-1"></i>${label}</span>`;
                    };

                    const keyBadgesHtml = `
                        <div class="d-flex flex-wrap align-items-center">
                            ${badgeDoc('KTP', 'ktp')}
                            ${badgeDoc('NPWP', 'npwp')}
                            ${badgeDoc('Ijazah', 'ijazah')}
                            ${badgeDoc('SK', 'sk')}
                            ${badgeDoc('STR', 'str')}
                            ${badgeDoc('SIP', 'sip')}
                            ${badgeDoc('KK', 'kk')}
                            ${badgeDoc('Nikah', 'nikah')}
                        </div>
                    `;

                    tbodyHtml += `
                        <tr>
                            <td class="text-center fw-bold text-muted">${countRendered}</td>
                            <td>
                                <div class="d-flex align-items-center gap-2">
                                    <img src="${foto}" class="rounded-circle object-fit-cover border" style="width: 38px; height: 38px;" onerror="this.src='https://ui-avatars.com/api/?name=${encodeURIComponent(nama)}&background=0D8ABC&color=fff'">
                                    <div>
                                        <div class="fw-bold text-dark">${nama}</div>
                                        <div class="text-muted small" style="font-size: 0.75rem;">NIP: ${nip}</div>
                                    </div>
                                </div>
                            </td>
                            <td>
                                <div class="fw-semibold text-primary">${jabatan}</div>
                                <div class="text-muted small" style="font-size: 0.72rem;"><i class="fas fa-building text-secondary me-1"></i> ${ukpd}</div>
                            </td>
                            <td>${progressHtml}</td>
                            <td>${keyBadgesHtml}</td>
                            <td class="text-center">
                                <div class="btn-group btn-group-sm">
                                    <button type="button" class="btn btn-sm btn-danger rounded-pill px-3 me-1 shadow-sm" onclick="window.openModalKelolaDokumen(${idx})" title="Kelola Arsip Google Drive">
                                        <i class="fab fa-google-drive me-1"></i> Kelola
                                    </button>
                                    <button type="button" class="btn btn-sm btn-outline-info rounded-pill px-2" onclick="window.openWABroadcastFromDocTable(${idx})" title="Kirim Reminder WA">
                                        <i class="fab fa-whatsapp"></i>
                                    </button>
                                </div>
                            </td>
                        </tr>
                    `;
                }
            });

            if (countRendered === 0) {
                tbodyHtml = `
                    <tr>
                        <td colspan="6" class="text-center py-4 text-muted">
                            <i class="fab fa-google-drive fs-3 d-block mb-2 text-danger opacity-50"></i>
                            Tidak ditemukan data dokumen pegawai yang sesuai dengan filter pencarian.
                        </td>
                    </tr>
                `;
            }

            $('#stat-doc-total').text(totalPegawai);
            $('#stat-doc-lengkap').text(totalLengkap);
            $('#stat-doc-draft').text(totalDraft);
            $('#stat-doc-files').text(totalDriveFiles);

            $('#tbodyDokumen').html(tbodyHtml);
        };

        window.openModalKelolaDokumen = function(pegawaiIdx) {
            if (typeof dataPegawai === 'undefined' || !dataPegawai[pegawaiIdx]) return;
            const p = dataPegawai[pegawaiIdx];

            $('#d_pegawai_index').val(pegawaiIdx);
            $('#d_preview_nama').text(p.nama || '-');
            $('#d_preview_nip').text(p.nip || '-');
            $('#d_preview_jabatan').text(p.jabatan || p.jabatan_kepmenpan || p.jabatan_pergub || 'Staf Kesehatan');
            $('#d_preview_unit').text(p.ukpd || p.unit_tugas || 'Puskesmas Seribu Utara');
            $('#d_preview_foto').attr('src', p.foto || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(p.nama || 'P') + '&background=0D8ABC&color=fff');

            const da = p.dokumen_arsip || {};

            const folderUrl = da.drive_folder_url || `https://drive.google.com/drive/folders/SIMPEG_PKS_${p.nip || '0000'}_${(p.nama || 'PEGAWAI').replace(/\s+/g, '_')}`;
            $('#d_folder_drive_link').attr('href', folderUrl).text(folderUrl);

            const setDocField = (prefix, dataObj) => {
                const item = dataObj || {};
                $(`#doc_no_${prefix}`).val(item.no || '');
                $(`#doc_url_${prefix}`).val(item.url || '');
                if ($(`#badge_doc_${prefix}`).length) {
                    if (item.url || item.no) {
                        $(`#badge_doc_${prefix}`).removeClass('bg-light text-muted').addClass('bg-success text-white').text('Terunggah');
                    } else {
                        $(`#badge_doc_${prefix}`).removeClass('bg-success text-white').addClass('bg-light text-muted').text('Belum Unggah');
                    }
                }
            };

            setDocField('ktp', da.ktp);
            setDocField('npwp', da.npwp);
            setDocField('kk', da.kk);
            setDocField('nikah', da.nikah);
            setDocField('ijazah', da.ijazah);
            setDocField('sk', da.sk);
            setDocField('str', da.str);
            setDocField('sip', da.sip);

            if (da.ijazah && da.ijazah.tingkat) $('#doc_tingkat_ijazah').val(da.ijazah.tingkat);
            if (da.sk && da.sk.jenis) $('#doc_jenis_sk').val(da.sk.jenis);
            if (da.str && da.str.tgl) $('#doc_tgl_str').val(da.str.tgl);
            if (da.sip && da.sip.tgl) $('#doc_tgl_sip').val(da.sip.tgl);

            $('#file_ktp, #file_npwp, #file_kk, #file_nikah, #file_ijazah, #file_sk, #file_str, #file_sip').val('');

            $('#tbodyDocLainnya').empty();
            if (Array.isArray(da.lainnya) && da.lainnya.length > 0) {
                da.lainnya.forEach(l => {
                    window.addDocLainnyaRow(l.nama || '', l.no || '', l.url || '');
                });
            } else {
                window.addDocLainnyaRow('Sertifikat Pelatihan / Diklat', 'Sertifikat Kemenkes', 'https://drive.google.com/file/d/sample_sertifikat/view');
            }

            const stats = window.getDokumenCounts(p);
            $('#d_preview_status_badge').text(`${stats.uploaded} / ${stats.total} Dokumen`);

            let modalEl = document.getElementById('modalKelolaDokumen');
            let modal = new bootstrap.Modal(modalEl);
            modal.show();
        };

        window.generateAutoDriveFolderLink = function() {
            const idx = $('#d_pegawai_index').val();
            if (idx === '' || typeof dataPegawai === 'undefined' || !dataPegawai[idx]) return;

            const p = dataPegawai[idx];
            const cleanNama = (p.nama || 'PEGAWAI').replace(/[^a-zA-Z0-9]/g, '_');
            const cleanNip = (p.nip || '0000').replace(/[^a-zA-Z0-9]/g, '');

            const autoUrl = `https://drive.google.com/drive/folders/SIMPEG_PKSU_${cleanNip}_${cleanNama}`;
            $('#d_folder_drive_link').attr('href', autoUrl).text(autoUrl);

            if (typeof showToast === 'function') {
                showToast("Tautan folder Google Drive pegawai berhasil digenerate!", "success");
            }
        };

        window.handleFileUploadSimulation = function(inputEl, urlTargetId, badgeId) {
            if (!inputEl.files || inputEl.files.length === 0) return;

            const file = inputEl.files[0];
            const idx = $('#d_pegawai_index').val();
            const p = (idx !== '' && typeof dataPegawai !== 'undefined') ? dataPegawai[idx] : { nip: '0000', nama: 'Pegawai' };

            const cleanFileName = file.name.replace(/[^a-zA-Z0-9._-]/g, '_');
            const simUrl = `https://drive.google.com/file/d/1G_Drive_${Date.now()}_${cleanFileName}/view?usp=sharing`;

            $(`#${urlTargetId}`).val(simUrl);
            if (badgeId && $(`#${badgeId}`).length) {
                $(`#${badgeId}`).removeClass('bg-light text-muted').addClass('bg-success text-white').text('Terunggah');
            }

            if (typeof showToast === 'function') {
                showToast(`File "${file.name}" tersimpan & terhubung dengan Google Drive!`, "success");
            }
        };

        window.previewDocUrl = function(urlTargetId) {
            const url = $(`#${urlTargetId}`).val();
            if (!url) {
                alert("Belum ada tautan file Google Drive yang dimasukkan.");
                return;
            }
            window.open(url, '_blank');
        };

        window.addDocLainnyaRow = function(nama = '', ket = '', url = '') {
            const rowId = 'doc_row_' + Date.now() + '_' + Math.floor(Math.random()*1000);
            const trHtml = `
                <tr id="${rowId}">
                    <td><input type="text" class="form-control form-control-sm l_nama" value="${nama}" placeholder="Contoh: Sertifikat K3 / SKP 2025"></td>
                    <td><input type="text" class="form-control form-control-sm l_no" value="${ket}" placeholder="No. Sertifikat / Ket"></td>
                    <td>
                        <div class="input-group input-group-sm">
                            <input type="url" class="form-control form-control-sm l_url" value="${url}" placeholder="https://drive.google.com/file/d/...">
                            <button type="button" class="btn btn-outline-secondary" onclick="window.open(this.previousElementSibling.value || '#', '_blank')"><i class="fas fa-external-link-alt"></i></button>
                        </div>
                    </td>
                    <td class="text-center">
                        <button type="button" class="btn btn-sm btn-outline-danger" onclick="$('#${rowId}').remove()"><i class="fas fa-trash"></i></button>
                    </td>
                </tr>
            `;
            $('#tbodyDocLainnya').append(trHtml);
        };

        window.saveDokumenPegawai = function() {
            const idx = $('#d_pegawai_index').val();
            if (idx === '' || typeof dataPegawai === 'undefined' || !dataPegawai[idx]) return;

            const folderUrl = $('#d_folder_drive_link').attr('href');

            const ktp = { no: $('#doc_no_ktp').val().trim(), url: $('#doc_url_ktp').val().trim() };
            const npwp = { no: $('#doc_no_npwp').val().trim(), url: $('#doc_url_npwp').val().trim() };
            const kk = { no: $('#doc_no_kk').val().trim(), url: $('#doc_url_kk').val().trim() };
            const nikah = { no: $('#doc_no_nikah').val().trim(), url: $('#doc_url_nikah').val().trim() };

            const ijazah = { tingkat: $('#doc_tingkat_ijazah').val(), no: $('#doc_no_ijazah').val().trim(), url: $('#doc_url_ijazah').val().trim() };
            const sk = { jenis: $('#doc_jenis_sk').val(), no: $('#doc_no_sk').val().trim(), url: $('#doc_url_sk').val().trim() };

            const str = { no: $('#doc_no_str').val().trim(), tgl: $('#doc_tgl_str').val(), url: $('#doc_url_str').val().trim() };
            const sip = { no: $('#doc_no_sip').val().trim(), tgl: $('#doc_tgl_sip').val(), url: $('#doc_url_sip').val().trim() };

            let lainnyaList = [];
            $('#tbodyDocLainnya tr').each(function() {
                const nama = $(this).find('.l_nama').val().trim();
                const no = $(this).find('.l_no').val().trim();
                const url = $(this).find('.l_url').val().trim();
                if (nama || url) {
                    lainnyaList.push({ nama, no, url });
                }
            });

            dataPegawai[idx].dokumen_arsip = {
                drive_folder_url: folderUrl,
                ktp: ktp,
                npwp: npwp,
                kk: kk,
                nikah: nikah,
                ijazah: ijazah,
                sk: sk,
                str: str,
                sip: sip,
                lainnya: lainnyaList,
                updated_at: new Date().toLocaleString('id-ID')
            };

            if (typeof window.savePegawaiToStorage === 'function') {
                window.savePegawaiToStorage();
            } else {
                try {
                    localStorage.setItem('simpeg_data_pegawai', JSON.stringify(dataPegawai));
                } catch(e) {}
            }

            let modalEl = document.getElementById('modalKelolaDokumen');
            let modal = bootstrap.Modal.getInstance(modalEl);
            if (modal) modal.hide();

            if (typeof showToast === 'function') {
                showToast(`Arsip Dokumen Digital pegawai ${dataPegawai[idx].nama} berhasil diperbarui!`, "success");
            }

            window.renderDokumen();
        };

