                    { id: 'PGE007', sec: 'gap-kompetensi', nama: 'Gap Kompetensi SDMK', kategori: 'Kepegawaian', akses: 'Admin Kepegawaian', status: 'Aktif' },
                    { id: 'PGE008', sec: 'admin-section', nama: 'Panel Kontrol Administrator', kategori: 'Administrator', akses: 'Super Admin', status: 'Aktif' }
                ];
                localStorage.setItem('simpeg_admin_page', JSON.stringify(defaultPage));
            }

            if (!localStorage.getItem('simpeg_admin_group')) {
                const defaultGroup = [
                    { id: 'GRP001', kode: 'GRP_SUPERADMIN', nama: 'Super Admin', desc: 'Hak akses penuh ke seluruh modul, sistem, dan konfigurasi admin', status: 'Aktif' },
                    { id: 'GRP002', kode: 'GRP_ADMIN_KEP', nama: 'Admin Kepegawaian', desc: 'Pengelolaan data pegawai, kenaikan pangkat, hukdis, dan penggajian', status: 'Aktif' },
                    { id: 'GRP003', kode: 'GRP_OPERATOR', nama: 'Operator Unit', desc: 'Input data pegawai dan verifikasi dokumen tingkat unit tugas / pustu', status: 'Aktif' },
                    { id: 'GRP004', kode: 'GRP_PEGAWAI', nama: 'Pegawai', desc: 'Akses portal mandiri pegawai untuk lihat profil, QR Card, dan usulan', status: 'Aktif' }
                ];
                localStorage.setItem('simpeg_admin_group', JSON.stringify(defaultGroup));
            }

            if (!localStorage.getItem('simpeg_admin_akses')) {
                const defaultAkses = {
                    'dashboard': { superadmin: true, adminkep: true, operator: true, pegawai: true },
                    'data-master': { superadmin: true, adminkep: true, operator: true, pegawai: true },
                    'master-data': { superadmin: true, adminkep: true, operator: false, pegawai: false },
                    'usulan': { superadmin: true, adminkep: true, operator: true, pegawai: true },
                    'duk': { superadmin: true, adminkep: true, operator: true, pegawai: true },
                    'disiplin': { superadmin: true, adminkep: true, operator: false, pegawai: false },
                    'gap-kompetensi': { superadmin: true, adminkep: true, operator: false, pegawai: false },
                    'gaji': { superadmin: true, adminkep: true, operator: false, pegawai: false },
                    'admin': { superadmin: true, adminkep: false, operator: false, pegawai: false }
                };
                localStorage.setItem('simpeg_admin_akses', JSON.stringify(defaultAkses));
            }

            window.populateAdminPegawaiDropdown();
        };

        window.populateAdminPegawaiDropdown = function() {
            const list = window.dataPegawai || [];
            let html = '<option value="">-- Non-Pegawai / External Admin --</option>';
            list.forEach(p => {
                const jab = p.jabatan_pergub || p.jabatan || p.jabatan_kepmenpan || 'Pegawai';
                const unit = p.tugas || p.ukpd || 'PKSU';
                html += `<option value="${p.nip}">${p.nama} (${p.nip}) - ${jab} [${unit}]</option>`;
            });
            $('#form_adm_nip_select').html(html);

            const groups = JSON.parse(localStorage.getItem('simpeg_admin_group') || '[]');
            let gHtml = '<option value="">-- Semua Group / Role --</option>';
            let gSelectHtml = '';
            groups.forEach(g => {
                gHtml += `<option value="${g.nama}">${g.nama}</option>`;
                gSelectHtml += `<option value="${g.nama}">${g.nama}</option>`;
            });
            $('#filterAdminPenggunaGroup').html(gHtml);
            if (gSelectHtml) $('#form_adm_group').html(gSelectHtml);
        };

        window.syncPenggunaWithDataPegawai = function() {
            const list = window.dataPegawai || [];
            if (!list || list.length === 0) {
                showToast("Tidak ada data pegawai untuk disinkronkan.", "warning");
                return;
            }

            let users = JSON.parse(localStorage.getItem('simpeg_admin_pengguna') || '[]');
            let addedCount = 0;
            let updatedCount = 0;

            list.forEach((p, idx) => {
                let existing = users.find(u => u.nip === p.nip || u.username === p.nip);
                const pJab = (p.jabatan || p.jabatan_pergub || '').toLowerCase();
                const pUkpd = (p.tugas || p.ukpd || '').toLowerCase();

                let defaultRole = 'Pegawai';
                if (pJab.includes('kasubag') || pJab.includes('kepegawaian') || pJab.includes('administrator')) {
                    defaultRole = 'Admin Kepegawaian';
                } else if (pUkpd.includes('pustu') || pUkpd.includes('operator') || pJab.includes('pengelola')) {
                    defaultRole = 'Operator Unit';
                }

                const generatedEmail = p.email || `${p.nip}@jakarta.go.id`;

                if (existing) {
                    existing.nama = p.nama;
                    existing.email = generatedEmail;
                    existing.nip = p.nip;
                    updatedCount++;
                } else {
                    const newId = 'ADM' + String(Date.now() + idx).slice(-5);
                    users.push({
                        id: newId,
                        username: p.nip,
                        nama: p.nama,
                        email: generatedEmail,
                        nip: p.nip,
                        group: defaultRole,
                        status: 'Aktif',
                        last_login: 'Belum pernah'
                    });
                    addedCount++;
                }
            });

            localStorage.setItem('simpeg_admin_pengguna', JSON.stringify(users));
            showToast(`Sinkronisasi Selesai: +${addedCount} akun baru dibuat, ${updatedCount} akun diperbarui.`, "success");
            window.renderAdminPengguna();
        };

        window.viewDetailPegawaiDirect = function(nip) {
            if (!nip) return;
            const list = window.dataPegawai || [];
            const idx = list.findIndex(p => p.nip === nip);
            if (idx >= 0) {
                if (typeof window.showDetailModal === 'function') {
                    window.showDetailModal(idx);
                } else if (typeof window.editForm === 'function') {
                    window.editForm(idx);
                } else {
                    showToast(`Data Pegawai NIP ${nip} ditemukan.`, "info");
                }
            } else {
                showToast(`Data Pegawai NIP ${nip} tidak ditemukan di master pegawai.`, "warning");
            }
        };

        window.switchAdminTab = function(tabName) {
            window.currentAdminTab = tabName;
            $('.admin-tab-view').hide();
            $('#adminTabNav .nav-link').removeClass('active');
            $(`#tab-admin-${tabName}`).addClass('active');
            $(`#view-admin-${tabName}`).fadeIn();

            const labels = {
                'pengguna': 'Tambah Pengguna',
                'menu': 'Tambah Menu',
                'page': 'Tambah Page',
                'akses': 'Simpan Hak Akses',
                'group': 'Tambah Group'
            };
            $('#lblBtnTambahAdmin').text(labels[tabName] || 'Tambah Data');

            if (tabName === 'pengguna') window.renderAdminPengguna();
            else if (tabName === 'menu') window.renderAdminMenu();
            else if (tabName === 'page') window.renderAdminPage();
            else if (tabName === 'akses') window.renderAdminAkses();
            else if (tabName === 'group') window.renderAdminGroup();
        };

        window.openModalAdminTambahCurrent = function() {
            const tab = window.currentAdminTab;
            if (tab === 'pengguna') window.openModalAdminPengguna();
            else if (tab === 'menu') window.openModalAdminMenu();
            else if (tab === 'page') window.openModalAdminPage();
            else if (tab === 'akses') window.saveAdminAksesMatrix();
            else if (tab === 'group') window.openModalAdminGroup();
        };

        // --- 1. PENGGUNA MANAGEMENT ---
        window.renderAdminPengguna = function() {
            window.populateAdminPegawaiDropdown();
            const users = JSON.parse(localStorage.getItem('simpeg_admin_pengguna') || '[]');
            const search = ($('#searchAdminPengguna').val() || '').toLowerCase();
            const filterGroup = $('#filterAdminPenggunaGroup').val() || '';

            let totalUsers = users.length;
            let linkedUsers = 0;
            let externalUsers = 0;

            users.forEach(u => {
                if (u.nip && (window.dataPegawai || []).some(p => p.nip === u.nip)) {
                    linkedUsers++;
                } else {
                    externalUsers++;
                }
            });

            $('#stat_adm_total').text(`${totalUsers} Akun`);
            $('#stat_adm_linked').text(`${linkedUsers} Pegawai`);
            $('#stat_adm_external').text(`${externalUsers} Akun`);

            let filtered = users.filter(u => {
                const matchSearch = u.username.toLowerCase().includes(search) || u.nama.toLowerCase().includes(search) || (u.nip && u.nip.includes(search));
                const matchGroup = !filterGroup || u.group === filterGroup;
                return matchSearch && matchGroup;
            });

            let tbody = '';
            if (filtered.length === 0) {
                tbody = '<tr><td colspan="7" class="text-center text-muted py-4"><i class="fas fa-info-circle me-1"></i> Tidak ada pengguna sistem ditemukan</td></tr>';
            } else {
                filtered.forEach((u, idx) => {
                    const p = (window.dataPegawai || []).find(item => item.nip === u.nip || item.nip === u.username);
                    const badgeStatus = u.status === 'Aktif' ? 'bg-success' : 'bg-danger';
                    const badgeRole = u.group === 'Super Admin' ? 'bg-danger' : (u.group === 'Admin Kepegawaian' ? 'bg-primary' : (u.group === 'Operator Unit' ? 'bg-warning text-dark' : 'bg-secondary'));

                    let pInfoHtml = '';
                    let avatarHtml = '';

                    if (p) {
                        const initial = p.nama ? p.nama.charAt(0).toUpperCase() : 'P';
                        avatarHtml = p.foto && p.foto.length > 10 ? 
                            `<img src="${p.foto}" class="rounded-circle me-2 object-fit-cover shadow-sm" style="width:36px; height:36px;">` : 
                            `<div class="rounded-circle bg-primary-subtle text-primary fw-bold d-inline-flex align-items-center justify-content-center me-2 shadow-sm" style="width:36px; height:36px; font-size:14px;">${initial}</div>`;

                        pInfoHtml = `
                            <div class="d-flex align-items-center">
                                <div>
                                    <div class="fw-bold text-dark mb-0">${p.nama}</div>
                                    <div class="small text-muted"><span class="font-monospace text-primary me-1"><i class="fas fa-id-card me-1"></i>${p.nip}</span> | <span class="badge bg-light text-dark border">${p.status_pegawai || 'PNS'}</span></div>
                                    <div class="small text-secondary text-truncate" style="max-width:280px;" title="${p.jabatan_pergub || p.jabatan || '-'}"><i class="fas fa-user-md me-1 text-primary"></i>${p.jabatan_pergub || p.jabatan || '-'}</div>
                                    <div class="small text-muted"><i class="fas fa-map-marker-alt me-1 text-danger"></i>${p.tugas || p.ukpd || 'PKSU'} <span class="text-primary fw-semibold">(${p.pangkat_gol || '-'})</span></div>
                                </div>
                            </div>
                        `;
                    } else {
                        avatarHtml = `<div class="rounded-circle bg-warning-subtle text-warning-emphasis fw-bold d-inline-flex align-items-center justify-content-center me-2 shadow-sm" style="width:36px; height:36px; font-size:14px;"><i class="fas fa-user-shield"></i></div>`;
                        pInfoHtml = `
                            <div class="text-muted small">
                                <span class="badge bg-secondary-subtle text-secondary border"><i class="fas fa-user-slash me-1"></i> Akun External / Non-Pegawai</span>
                                <div class="mt-1 font-monospace">NIP: ${u.nip || '-'}</div>
                            </div>
                        `;
                    }

                    tbody += `
                        <tr>
                            <td>${idx + 1}</td>
                            <td>
                                <div class="d-flex align-items-center">
                                    ${avatarHtml}
                                    <div>
                                        <div class="fw-bold text-dark">${u.nama}</div>
                                        <div class="small text-muted"><i class="fas fa-user text-secondary me-1"></i><code class="text-primary">${u.username}</code></div>
                                        <div class="small text-muted"><i class="fas fa-envelope text-secondary me-1"></i>${u.email}</div>
                                    </div>
                                </div>
                            </td>
                            <td>${pInfoHtml}</td>
                            <td><span class="badge ${badgeRole} rounded-pill px-3 py-1">${u.group}</span></td>
                            <td><span class="badge ${badgeStatus}">${u.status}</span></td>
                            <td><small class="text-muted">${u.last_login || 'Belum pernah'}</small></td>
                            <td class="text-center">
                                <div class="btn-group btn-group-sm">
                                    ${p ? `<button class="btn btn-outline-info rounded-circle me-1" onclick="window.viewDetailPegawaiDirect('${p.nip}')" title="Lihat Profil Detail Pegawai"><i class="fas fa-id-card"></i></button>` : ''}
                                    <button class="btn btn-outline-primary rounded-circle me-1" onclick="window.editAdminPengguna('${u.id}')" title="Edit Akun Admin"><i class="fas fa-edit"></i></button>
                                    <button class="btn btn-outline-danger rounded-circle" onclick="window.deleteAdminPengguna('${u.id}')" title="Hapus Akun Admin"><i class="fas fa-trash"></i></button>
                                </div>
                            </td>
                        </tr>
                    `;
                });
            }
            $('#tableAdminPengguna tbody').html(tbody);
        };

        window.openModalAdminPengguna = function() {
            window.populateAdminPegawaiDropdown();
            $('#form_adm_user_id').val('');
            $('#form_adm_user_name').val('');
            $('#form_adm_nama').val('');
            $('#form_adm_email').val('');
            $('#form_adm_password').val('');
            $('#form_adm_nip_select').val('');
            $('#form_adm_group').val('Super Admin');
            $('#form_adm_user_status').val('Aktif');
            $('#cardPegawaiLinkedPreview').addClass('d-none');
            $('#modalAdminPengguna').modal('show');
        };

        window.onAdminPenggunaNipChange = function() {
            const nip = $('#form_adm_nip_select').val();
            if (nip) {
                const p = (window.dataPegawai || []).find(item => item.nip === nip);
                if (p) {
                    $('#form_adm_nama').val(p.nama);
                    $('#form_adm_email').val(p.email || `${p.nip}@jakarta.go.id`);
                    if (!$('#form_adm_user_name').val() || $('#form_adm_user_name').val().startsWith('ADM')) {
                        $('#form_adm_user_name').val(p.nip);
                    }

                    const pJab = (p.jabatan || p.jabatan_pergub || '').toLowerCase();
                    if (pJab.includes('kasubag') || pJab.includes('kepegawaian')) {
                        $('#form_adm_group').val('Admin Kepegawaian');
                    } else if (pJab.includes('operator') || (p.tugas && p.tugas.toLowerCase().includes('pustu'))) {
                        $('#form_adm_group').val('Operator Unit');
                    } else {
                        $('#form_adm_group').val('Pegawai');
                    }

                    // Live Preview Card
                    const initial = p.nama ? p.nama.charAt(0).toUpperCase() : 'P';
                    let avatarHtml = initial;
                    if (p.foto && p.foto.length > 10) {
                        avatarHtml = `<img src="${p.foto}" class="w-100 h-100 rounded-circle object-fit-cover">`;
                    }

                    $('#prev_p_avatar').html(avatarHtml);
                    $('#prev_p_nama').html(`${p.nama} <span class="badge bg-primary-subtle text-primary ms-1">${p.status_pegawai || 'PNS'}</span>`);
                    $('#prev_p_nip').html(`NIP: ${p.nip} ${p.nrk ? '| NRK: ' + p.nrk : ''}`);
                    $('#prev_p_jabatan').html(`<i class="fas fa-briefcase me-1"></i>${p.jabatan_pergub || p.jabatan || '-'}`);
                    $('#prev_p_unit').html(`<i class="fas fa-building me-1"></i>${p.tugas || p.ukpd || 'PKSU'} (${p.pangkat_gol || '-'})`);

                    $('#cardPegawaiLinkedPreview').removeClass('d-none').hide().fadeIn();
                    return;
                }
            }
            $('#cardPegawaiLinkedPreview').addClass('d-none');
        };

        window.editAdminPengguna = function(id) {
            window.populateAdminPegawaiDropdown();
            const users = JSON.parse(localStorage.getItem('simpeg_admin_pengguna') || '[]');
            const u = users.find(item => item.id === id);
            if (!u) return;

            $('#form_adm_user_id').val(u.id);
            $('#form_adm_user_name').val(u.username);
            $('#form_adm_nama').val(u.nama);
            $('#form_adm_email').val(u.email);
            $('#form_adm_password').val('******');
            $('#form_adm_nip_select').val(u.nip || '');
            $('#form_adm_group').val(u.group);
            $('#form_adm_user_status').val(u.status);
            window.onAdminPenggunaNipChange();
            $('#modalAdminPengguna').modal('show');
        };

        window.saveAdminPengguna = function(e) {
            e.preventDefault();
            const id = $('#form_adm_user_id').val();
            const username = $('#form_adm_user_name').val().trim();
            const nama = $('#form_adm_nama').val().trim();
            const email = $('#form_adm_email').val().trim();
            const nip = $('#form_adm_nip_select').val();
            const group = $('#form_adm_group').val();
            const status = $('#form_adm_user_status').val();

            let users = JSON.parse(localStorage.getItem('simpeg_admin_pengguna') || '[]');

            if (id) {
                let u = users.find(item => item.id === id);
                if (u) {
                    u.username = username;
                    u.nama = nama;
                    u.email = email;
                    u.nip = nip;
                    u.group = group;
                    u.status = status;
                }
            } else {
                const newId = 'ADM' + String(Date.now()).slice(-4);
                users.unshift({
                    id: newId,
                    username: username,
                    nama: nama,
                    email: email,
                    nip: nip,
                    group: group,
                    status: status,
                    last_login: 'Baru ditambahkan'
                });
            }

            localStorage.setItem('simpeg_admin_pengguna', JSON.stringify(users));
            $('#modalAdminPengguna').modal('hide');
            showToast("Data Pengguna berhasil disimpan!", "success");
            window.renderAdminPengguna();
        };

        window.deleteAdminPengguna = function(id) {
            if (confirm("Apakah Anda yakin ingin menghapus pengguna ini?")) {
                let users = JSON.parse(localStorage.getItem('simpeg_admin_pengguna') || '[]');
                users = users.filter(item => item.id !== id);
                localStorage.setItem('simpeg_admin_pengguna', JSON.stringify(users));
                showToast("Pengguna berhasil dihapus", "info");
                window.renderAdminPengguna();
            }
        };

        // --- 2. MENU MANAGEMENT ---
        window.renderAdminMenu = function() {
            const menus = JSON.parse(localStorage.getItem('simpeg_admin_menu') || '[]');
            const search = ($('#searchAdminMenu').val() || '').toLowerCase();

            let filtered = menus.filter(m => m.nama.toLowerCase().includes(search) || m.target.toLowerCase().includes(search));
            filtered.sort((a, b) => a.urutan - b.urutan);

            let tbody = '';
            if (filtered.length === 0) {
                tbody = '<tr><td colspan="7" class="text-center text-muted py-4"><i class="fas fa-info-circle me-1"></i> Tidak ada menu ditemukan</td></tr>';
            } else {
                filtered.forEach((m, idx) => {
                    const badgeStatus = m.status === 'Aktif' ? 'bg-success' : 'bg-secondary';
                    tbody += `
                        <tr>
                            <td>${idx + 1}</td>
                            <td>
                                <i class="${m.icon} me-2 fs-6"></i>
                                <span class="fw-bold text-dark">${m.nama}</span>
                            </td>
                            <td><code class="text-primary">${m.target}</code></td>
                            <td><span class="badge bg-light text-dark border">${m.parent}</span></td>
                            <td><span class="fw-bold">${m.urutan}</span></td>
                            <td><span class="badge ${badgeStatus}">${m.status}</span></td>
                            <td class="text-center">
                                <button class="btn btn-sm btn-outline-primary me-1 rounded-circle" onclick="window.editAdminMenu('${m.id}')"><i class="fas fa-edit"></i></button>
                                <button class="btn btn-sm btn-outline-danger rounded-circle" onclick="window.deleteAdminMenu('${m.id}')"><i class="fas fa-trash"></i></button>
                            </td>
                        </tr>
                    `;
                });
            }
            $('#tableAdminMenu tbody').html(tbody);
        };

        window.openModalAdminMenu = function() {
            $('#form_adm_menu_id').val('');
            $('#form_adm_menu_nama').val('');
            $('#form_adm_menu_target').val('');
            $('#form_adm_menu_icon').val('fas fa-th-list text-primary');
            $('#form_adm_menu_parent').val('Root / Main Menu');
            $('#form_adm_menu_urutan').val('1');
            $('#form_adm_menu_status').val('Aktif');
            $('#modalAdminMenu').modal('show');
        };

        window.editAdminMenu = function(id) {
            const menus = JSON.parse(localStorage.getItem('simpeg_admin_menu') || '[]');
            const m = menus.find(item => item.id === id);
            if (!m) return;

            $('#form_adm_menu_id').val(m.id);
            $('#form_adm_menu_nama').val(m.nama);
            $('#form_adm_menu_target').val(m.target);
            $('#form_adm_menu_icon').val(m.icon);
            $('#form_adm_menu_parent').val(m.parent);
            $('#form_adm_menu_urutan').val(m.urutan);
            $('#form_adm_menu_status').val(m.status);
            $('#modalAdminMenu').modal('show');
        };

        window.saveAdminMenu = function(e) {
            e.preventDefault();
            const id = $('#form_adm_menu_id').val();
            const nama = $('#form_adm_menu_nama').val().trim();
            const target = $('#form_adm_menu_target').val().trim();
            const icon = $('#form_adm_menu_icon').val().trim();
            const parent = $('#form_adm_menu_parent').val();
            const urutan = parseInt($('#form_adm_menu_urutan').val()) || 1;
            const status = $('#form_adm_menu_status').val();

            let menus = JSON.parse(localStorage.getItem('simpeg_admin_menu') || '[]');

            if (id) {
                let m = menus.find(item => item.id === id);
                if (m) {
                    m.nama = nama;
                    m.target = target;
                    m.icon = icon;
                    m.parent = parent;
                    m.urutan = urutan;
                    m.status = status;
                }
            } else {
                const newId = 'MNU' + String(Date.now()).slice(-4);
                menus.push({ id: newId, nama, target, icon, parent, urutan, status });
            }

            localStorage.setItem('simpeg_admin_menu', JSON.stringify(menus));
            $('#modalAdminMenu').modal('hide');
            showToast("Menu berhasil disimpan!", "success");
            window.renderAdminMenu();
        };

        window.deleteAdminMenu = function(id) {
            if (confirm("Apakah Anda yakin ingin menghapus menu ini?")) {
                let menus = JSON.parse(localStorage.getItem('simpeg_admin_menu') || '[]');
                menus = menus.filter(item => item.id !== id);
                localStorage.setItem('simpeg_admin_menu', JSON.stringify(menus));
                showToast("Menu berhasil dihapus", "info");
                window.renderAdminMenu();
            }
        };

        // --- 3. PAGE MANAGEMENT ---
        window.renderAdminPage = function() {
            const pages = JSON.parse(localStorage.getItem('simpeg_admin_page') || '[]');
            const search = ($('#searchAdminPage').val() || '').toLowerCase();

            let filtered = pages.filter(p => p.nama.toLowerCase().includes(search) || p.sec.toLowerCase().includes(search));

            let tbody = '';
            if (filtered.length === 0) {
                tbody = '<tr><td colspan="7" class="text-center text-muted py-4"><i class="fas fa-info-circle me-1"></i> Tidak ada halaman ditemukan</td></tr>';
            } else {
                filtered.forEach((p, idx) => {
                    const badgeStatus = p.status === 'Aktif' ? 'bg-success' : 'bg-secondary';
                    tbody += `
                        <tr>
                            <td>${idx + 1}</td>
                            <td><code class="text-indigo fw-bold">${p.sec}</code></td>
                            <td><span class="fw-bold text-dark">${p.nama}</span></td>
                            <td><span class="badge bg-light text-dark border">${p.kategori}</span></td>
                            <td><span class="badge bg-info-subtle text-info border border-info-subtle">${p.akses}</span></td>
                            <td><span class="badge ${badgeStatus}">${p.status}</span></td>
                            <td class="text-center">
                                <button class="btn btn-sm btn-outline-primary me-1 rounded-circle" onclick="window.editAdminPage('${p.id}')"><i class="fas fa-edit"></i></button>
                                <button class="btn btn-sm btn-outline-danger rounded-circle" onclick="window.deleteAdminPage('${p.id}')"><i class="fas fa-trash"></i></button>
                            </td>
                        </tr>
                    `;
                });
            }
            $('#tableAdminPage tbody').html(tbody);
        };

        window.openModalAdminPage = function() {
            $('#form_adm_page_id').val('');
            $('#form_adm_page_sec').val('');
            $('#form_adm_page_nama').val('');
            $('#form_adm_page_kategori').val('Kepegawaian');
            $('#form_adm_page_akses').val('Pegawai');
            $('#form_adm_page_status').val('Aktif');
            $('#modalAdminPage').modal('show');
        };

        window.editAdminPage = function(id) {
            const pages = JSON.parse(localStorage.getItem('simpeg_admin_page') || '[]');
            const p = pages.find(item => item.id === id);
            if (!p) return;

            $('#form_adm_page_id').val(p.id);
            $('#form_adm_page_sec').val(p.sec);
            $('#form_adm_page_nama').val(p.nama);
            $('#form_adm_page_kategori').val(p.kategori);
            $('#form_adm_page_akses').val(p.akses);
            $('#form_adm_page_status').val(p.status);
            $('#modalAdminPage').modal('show');
        };

        window.saveAdminPage = function(e) {
            e.preventDefault();
            const id = $('#form_adm_page_id').val();
            const sec = $('#form_adm_page_sec').val().trim();
            const nama = $('#form_adm_page_nama').val().trim();
            const kategori = $('#form_adm_page_kategori').val();
            const akses = $('#form_adm_page_akses').val();
            const status = $('#form_adm_page_status').val();

            let pages = JSON.parse(localStorage.getItem('simpeg_admin_page') || '[]');

            if (id) {
                let p = pages.find(item => item.id === id);
                if (p) {
                    p.sec = sec;
                    p.nama = nama;
                    p.kategori = kategori;
                    p.akses = akses;
                    p.status = status;
                }
            } else {
                const newId = 'PGE' + String(Date.now()).slice(-4);
                pages.push({ id: newId, sec, nama, kategori, akses, status });
            }

            localStorage.setItem('simpeg_admin_page', JSON.stringify(pages));
            $('#modalAdminPage').modal('hide');
            showToast("Page berhasil disimpan!", "success");
            window.renderAdminPage();
        };

        window.deleteAdminPage = function(id) {
            if (confirm("Apakah Anda yakin ingin menghapus page ini?")) {
                let pages = JSON.parse(localStorage.getItem('simpeg_admin_page') || '[]');
                pages = pages.filter(item => item.id !== id);
                localStorage.setItem('simpeg_admin_page', JSON.stringify(pages));
                showToast("Page berhasil dihapus", "info");
                window.renderAdminPage();
            }
        };

        // --- 4. AKSES MATRIX MANAGEMENT ---
        window.renderAdminAkses = function() {
            const aks = JSON.parse(localStorage.getItem('simpeg_admin_akses') || '{}');
            const modules = [
                { key: 'dashboard', name: 'Dashboard Analytics & Summary' },
                { key: 'data-master', name: 'Data Master Pegawai & Biodata' },
                { key: 'master-data', name: 'Master Jabatan, Rumpun & Pangkat' },
                { key: 'usulan', name: 'Usulan Tunjangan, Pangkat & Jenjang' },
                { key: 'duk', name: 'Daftar Urut Kepangkatan (DUK)' },
                { key: 'disiplin', name: 'Disiplin Pegawai & Catatan Hukdis' },
                { key: 'gap-kompetensi', name: 'Evaluasi Gap Kompetensi' },
                { key: 'gaji', name: 'Modul Penggajian & Slip Gaji' },
                { key: 'admin', name: 'Panel Administrator Control' }
            ];

            let tbody = '';
            modules.forEach(m => {
                const item = aks[m.key] || { superadmin: true, adminkep: true, operator: false, pegawai: false };
                tbody += `
                    <tr>
                        <td class="fw-bold text-dark"><i class="fas fa-folder text-primary me-2"></i>${m.name}</td>
                        <td class="text-center"><input type="checkbox" class="form-check-input" id="chk_${m.key}_superadmin" ${item.superadmin ? 'checked' : ''}></td>
                        <td class="text-center"><input type="checkbox" class="form-check-input" id="chk_${m.key}_adminkep" ${item.adminkep ? 'checked' : ''}></td>
                        <td class="text-center"><input type="checkbox" class="form-check-input" id="chk_${m.key}_operator" ${item.operator ? 'checked' : ''}></td>
                        <td class="text-center"><input type="checkbox" class="form-check-input" id="chk_${m.key}_pegawai" ${item.pegawai ? 'checked' : ''}></td>
                    </tr>
                `;
            });
            $('#tableAdminAkses tbody').html(tbody);
        };

        window.saveAdminAksesMatrix = function() {
            const modules = ['dashboard', 'data-master', 'master-data', 'usulan', 'duk', 'disiplin', 'gap-kompetensi', 'gaji', 'admin'];
            let matrix = {};
            modules.forEach(k => {
                matrix[k] = {
                    superadmin: $(`#chk_${k}_superadmin`).is(':checked'),
                    adminkep: $(`#chk_${k}_adminkep`).is(':checked'),
                    operator: $(`#chk_${k}_operator`).is(':checked'),
                    pegawai: $(`#chk_${k}_pegawai`).is(':checked')
                };
            });
            localStorage.setItem('simpeg_admin_akses', JSON.stringify(matrix));
            showToast("Matriks Hak Akses berhasil diperbarui!", "success");
        };

        // --- 5. GROUP MANAGEMENT ---
        window.renderAdminGroup = function() {
            const groups = JSON.parse(localStorage.getItem('simpeg_admin_group') || '[]');
            const search = ($('#searchAdminGroup').val() || '').toLowerCase();

            let filtered = groups.filter(g => g.nama.toLowerCase().includes(search) || g.kode.toLowerCase().includes(search));

            let tbody = '';
            if (filtered.length === 0) {
                tbody = '<tr><td colspan="6" class="text-center text-muted py-4"><i class="fas fa-info-circle me-1"></i> Tidak ada group ditemukan</td></tr>';
            } else {
                filtered.forEach((g, idx) => {
                    const badgeStatus = g.status === 'Aktif' ? 'bg-success' : 'bg-secondary';
                    tbody += `
                        <tr>
                            <td>${idx + 1}</td>
                            <td><code class="text-primary fw-bold">${g.kode}</code></td>
                            <td><span class="fw-bold text-dark">${g.nama}</span></td>
                            <td><small class="text-muted">${g.desc || '-'}</small></td>
                            <td><span class="badge ${badgeStatus}">${g.status}</span></td>
                            <td class="text-center">
                                <button class="btn btn-sm btn-outline-primary me-1 rounded-circle" onclick="window.editAdminGroup('${g.id}')"><i class="fas fa-edit"></i></button>
                                <button class="btn btn-sm btn-outline-danger rounded-circle" onclick="window.deleteAdminGroup('${g.id}')"><i class="fas fa-trash"></i></button>
                            </td>
                        </tr>
                    `;
                });
            }
            $('#tableAdminGroup tbody').html(tbody);
        };

        window.openModalAdminGroup = function() {
            $('#form_adm_grp_id').val('');
            $('#form_adm_grp_kode').val('');
