        window.editAdminGroup = function(id) {
            const groups = JSON.parse(localStorage.getItem('simpeg_admin_group') || '[]');
            const g = groups.find(item => item.id === id);
            if (!g) return;

            $('#form_adm_grp_id').val(g.id);
