        window.saveAdminGroup = function(e) {
            e.preventDefault();
            const id = $('#form_adm_grp_id').val();
            const kode = $('#form_adm_grp_kode').val().trim();
            const nama = $('#form_adm_grp_nama').val().trim();
            const desc = $('#form_adm_grp_desc').val().trim();
            const status = $('#form_adm_grp_status').val();

            let groups = JSON.parse(localStorage.getItem('simpeg_admin_group') || '[]');

            if (id) {
                let g = groups.find(item => item.id === id);
                if (g) {
                    g.kode = kode;
                    g.nama = nama;
                    g.desc = desc;
                    g.status = status;
                }
            } else {
                const newId = 'GRP' + String(Date.now()).slice(-4);
                groups.push({ id: newId, kode, nama, desc, status });
            }

            localStorage.setItem('simpeg_admin_group', JSON.stringify(groups));
