            showToast("Group berhasil disimpan!", "success");
            window.renderAdminGroup();
            window.populateAdminPegawaiDropdown();
        };

        window.deleteAdminGroup = function(id) {
            if (confirm("Apakah Anda yakin ingin menghapus group ini?")) {
                let groups = JSON.parse(localStorage.getItem('simpeg_admin_group') || '[]');
                groups = groups.filter(item => item.id !== id);
                localStorage.setItem('simpeg_admin_group', JSON.stringify(groups));
                showToast("Group berhasil dihapus", "info");
                window.renderAdminGroup();
                window.populateAdminPegawaiDropdown();
            }
        };

        window.exportGapCSV = function() {
            let list = window.gapKompetensiList;
            if (!list || list.length === 0) {
                showToast("Tidak ada data gap kompetensi untuk diexport.", "warning");
                return;
            }

            let csvContent = "data:text/csv;charset=utf-8,";
            let filename = `Gap_Kompetensi_Pegawai_PKSU_${new Date().toISOString().split('T')[0]}.csv`;

            csvContent += "ID Evaluasi,Tahun,NIP,Nama Pegawai,Jabatan,Unit,Manajerial Std,Manajerial Riil,Sosial Std,Sosial Riil,Teknis Std,Teknis Riil,Capaian Pct,Kategori Gap,Rekomendasi Diklat\n";
            list.forEach(i => {
                const s = window.calcGapSummary(i);
                csvContent += `"${i.id}","${i.tahun}","${i.nip}","${i.nama}","${i.jabatan}","${i.unit}","${i.manajerial_std}","${i.manajerial_riil}","${i.sosial_std}","${i.sosial_riil}","${i.teknis_std}","${i.teknis_riil}","${s.pct}%","${s.category}","${i.rekomendasi}"\n`;
            });

            const encodedUri = encodeURI(csvContent);
            const link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", filename);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            showToast("Export CSV Gap Kompetensi berhasil!", "success");
        };

        $(document).ready(function() {
            showPublicDashboard();
            loadDataFromGAS();
            window.initMasterJabatanData();
            window.populateJabatanDatalists();
            window.initUsulanData();
            window.initGapKompetensiData();

            // Setup Drag & Drop for Upload DropZone
            const dropZone = document.getElementById('dropZoneUpload');
            if (dropZone) {
                ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
                    dropZone.addEventListener(eventName, function(e) {
                        e.preventDefault();
                        e.stopPropagation();
                    }, false);
                });

                ['dragenter', 'dragover'].forEach(eventName => {
                    dropZone.addEventListener(eventName, function() {
                        dropZone.classList.add('bg-success-subtle');
                    }, false);
                });

                ['dragleave', 'drop'].forEach(eventName => {
                    dropZone.addEventListener(eventName, function() {
                        dropZone.classList.remove('bg-success-subtle');
                    }, false);
                });

                dropZone.addEventListener('drop', function(e) {
                    let dt = e.dataTransfer;
                    let files = dt.files;
                    if (files && files.length > 0) {
                        window.handleFilePegawaiSelect({ target: { files: files } });
                    }
                }, false);
            }

            $('#sidebar ul li a, .mobile-bottom-nav a').on('click', function(e) {
                if($(this).attr('onclick')) return;
                e.preventDefault();
                let target = $(this).data('target');
                if(!target) return;
                window.showSection(target);
            });

            // Modal QR Scanner Event Handlers
            $('#modalQRScanner').on('shown.bs.modal', function () {
                window.startQRCameraScanner();
            });
            $('#modalQRScanner').on('hidden.bs.modal', function () {
                window.stopQRCameraScanner();
            });
        });

